/* SINH TỰ ĐỘNG bởi tools/build-ipr102.js — đừng sửa tay. Môn IPR102 (Quyền sở hữu trí tuệ): m = "ipr", c = chương 1–6, vi = bản dịch tiếng Việt (đừng dùng v: đã là nhãn kiểm chứng ở bộ câu MLN111) */
RAW.push(...[
{"id":"ipr-1","q":"Which of the followings is an infringement of copyright?","o":["Reading a book without consent of the author","Listening to a song without consent of the author","Translating an article without consent of the author","Researching a paper without consent of the author"],"a":[2],"m":"ipr","c":3,"n":1,"e":"Dịch (translation) là một dạng chuyển thể tác phẩm, thuộc quyền độc quyền của chủ sở hữu bản quyền nên phải xin phép. Đọc, nghe hay nghiên cứu tác phẩm chỉ là sử dụng/tiếp nhận, không phải hành vi bị bản quyền kiểm soát.","vi":{"q":"Hành vi nào sau đây là vi phạm bản quyền?","o":["Đọc một cuốn sách mà không có sự đồng ý của tác giả","Nghe một bài hát mà không có sự đồng ý của tác giả","Dịch một bài báo mà không có sự đồng ý của tác giả","Nghiên cứu một bài báo khoa học mà không có sự đồng ý của tác giả"]}},
{"id":"ipr-2","q":"One of the requirements for a mark to be registered as trademark is......","o":["not an infringement of other's right","to be new","to be creative","to be original"],"a":[0],"m":"ipr","c":4,"n":2,"e":"Điều kiện để đăng ký nhãn hiệu là có tính phân biệt và không xâm phạm quyền có trước của người khác. Nhãn hiệu không bắt buộc phải mới, sáng tạo hay nguyên gốc như tác phẩm hay sáng chế.","vi":{"q":"Một trong các điều kiện để một dấu hiệu được đăng ký làm nhãn hiệu là ......","o":["không xâm phạm quyền của người khác","phải mới","phải sáng tạo","phải nguyên gốc (original)"]}},
{"id":"ipr-3","q":"How long is the duration of database right according to the UK law?","o":["Lasts for the life of its creator plus a further 70 years.","Lasts for 70 years begins to run on the death of the last surviving creator if two or more.....jointly involved in the work","For the works generated before 1 January 1996 the duration of database right is life plus....50 years.","Lasts for 15 years from the end of the year the database was created or made accessible"],"a":[3],"m":"ipr","c":6,"n":3,"e":"Quyền cơ sở dữ liệu (database right) của Anh kéo dài 15 năm kể từ cuối năm cơ sở dữ liệu được tạo ra hoặc được công bố. Các mốc «đời tác giả + 70 năm» là của bản quyền.","vi":{"q":"Theo luật Anh, quyền đối với cơ sở dữ liệu (database right) có thời hạn bao lâu?","o":["Suốt đời tác giả cộng thêm 70 năm.","70 năm, bắt đầu tính từ khi người sáng tạo cuối cùng qua đời nếu có hai hay nhiều người cùng tham gia tạo ra tác phẩm.","Với tác phẩm được tạo ra trước ngày 1/1/1996, thời hạn của quyền cơ sở dữ liệu là suốt đời cộng thêm 50 năm.","15 năm kể từ cuối năm cơ sở dữ liệu được tạo ra hoặc được công bố, cho phép truy cập."]}},
{"id":"ipr-4","q":"A mechanical device is NOT protected by which IPR?","o":["Copyright","Design right","Patent","Registered design"],"a":[0],"m":"ipr","c":1,"n":4,"e":"Bản quyền bảo hộ sự thể hiện của tác phẩm (văn, nhạc, hình ảnh...), không bảo hộ một thiết bị cơ khí. Thiết bị cơ khí được bảo hộ bằng sáng chế (chức năng) và kiểu dáng đã đăng ký/quyền kiểu dáng (hình dáng).","vi":{"q":"Một thiết bị cơ khí KHÔNG được bảo hộ bởi quyền sở hữu trí tuệ nào?","o":["Bản quyền","Quyền kiểu dáng (design right)","Sáng chế","Kiểu dáng đã đăng ký (registered design)"]}},
{"id":"ipr-5","q":"The paternity right is NOT applied to:","o":["The creator of a literary, artistic, dramatic or musical copyright work and the director of a film (unless he or she is an employee)","The designer of a building or other structure","Computer programs or to any work created by a computer without human intervention","An individual person and only when there is also a copyright"],"a":[2],"m":"ipr","c":2,"n":5,"e":"Quyền được nhận là tác giả (paternity right) áp dụng cho tác phẩm văn học, kịch, âm nhạc, nghệ thuật, đạo diễn phim và thiết kế công trình. Chương trình máy tính và tác phẩm do máy tính tự tạo không có quyền này.","vi":{"q":"Quyền được nhận là tác giả (paternity right) KHÔNG áp dụng cho:","o":["Người sáng tạo tác phẩm văn học, nghệ thuật, kịch hoặc âm nhạc có bản quyền và đạo diễn của một bộ phim (trừ khi người đó là nhân viên)","Người thiết kế một tòa nhà hoặc công trình khác","Chương trình máy tính hoặc bất kỳ tác phẩm nào do máy tính tạo ra mà không có sự can thiệp của con người","Một cá nhân, và chỉ khi đồng thời có bản quyền"]}},
{"id":"ipr-6","q":"Which is the principle of \"independence of protection\" stipulated in Bern Convention?","o":["Works originating in one of the Contracting States must be given the same protection in each of the other Contracting States as the latter grants to the works of its own nationals","Protection must not be conditional upon compliance with any formality","Protection is independent of the existence of protection in the country of origin of the work","As to works, protection must include \"every production in the literary, scientific and artistic domain, whatever the mode or form of its expression\""],"a":[2],"m":"ipr","c":2,"n":6,"e":"Công ước Berne có ba nguyên tắc: đối xử quốc gia, bảo hộ tự động (không cần thủ tục) và bảo hộ độc lập, tức không phụ thuộc việc tác phẩm có được bảo hộ ở nước xuất xứ hay không. Phương án {A} là đối xử quốc gia, {B} là bảo hộ tự động.","vi":{"q":"Đâu là nguyên tắc \"bảo hộ độc lập\" (independence of protection) được quy định trong Công ước Berne?","o":["Tác phẩm có nguồn gốc từ một nước thành viên phải được bảo hộ ở mỗi nước thành viên khác giống như nước đó bảo hộ tác phẩm của công dân mình","Việc bảo hộ không được phụ thuộc vào việc tuân thủ bất kỳ thủ tục nào","Việc bảo hộ độc lập với việc tác phẩm có được bảo hộ ở nước xuất xứ hay không","Đối với tác phẩm, sự bảo hộ phải bao gồm \"mọi sản phẩm trong lĩnh vực văn học, khoa học và nghệ thuật, bất kể phương thức hay hình thức thể hiện\""]}},
{"id":"ipr-7","q":"The remedies available for the trademark infringement are..... to those applicable for copyright","o":["the same","more favorable","less favorable","completely different"],"a":[0],"m":"ipr","c":1,"n":7,"e":"Các biện pháp khắc phục (lệnh cấm, bồi thường, giao nộp hàng vi phạm...) đối với nhãn hiệu đều giống như đối với bản quyền, nên chọn «giống nhau».","vi":{"q":"Các biện pháp khắc phục đối với hành vi xâm phạm nhãn hiệu ..... so với các biện pháp áp dụng cho bản quyền","o":["giống nhau","thuận lợi hơn","kém thuận lợi hơn","hoàn toàn khác"]}},
{"id":"ipr-8","q":"What is not relevant purpose for applying fair dealing","o":["Commercial purpose","Educational purpose","News reporting","Reviewing purpose"],"a":[0],"m":"ipr","c":3,"n":8,"e":"Fair dealing chỉ áp dụng cho một số mục đích như nghiên cứu, học tập cá nhân, phê bình/đánh giá, đưa tin. Mục đích thương mại không thuộc nhóm được miễn trừ.","vi":{"q":"Mục đích nào KHÔNG phù hợp để áp dụng sử dụng hợp lý (fair dealing)?","o":["Mục đích thương mại","Mục đích giáo dục","Đưa tin","Mục đích phê bình, đánh giá"]}},
{"id":"ipr-9","q":"Which is/are exceptions to copyright infringement?","o":["Public events","Time shifting","Education","All of others are correct"],"a":[3],"m":"ipr","c":3,"n":9,"f":1,"e":"Các hành vi như sự kiện công cộng, ghi hình để xem sau (time shifting) và giáo dục đều là ngoại lệ đối với xâm phạm bản quyền nên đáp án đúng là «tất cả».","vi":{"q":"Trường hợp nào là ngoại lệ đối với hành vi xâm phạm bản quyền?","o":["Sự kiện công cộng","Ghi hình để xem sau (time shifting)","Giáo dục","Tất cả các đáp án còn lại đều đúng"]}},
{"id":"ipr-10","q":"Which one of the followings is NOT correct according to UK law?","o":["Injunction and delivery-up can be applied even in case the plaintiff suffers no damage.","Courts may apply provisional measures where any delay is likely to cause irreparable harm to the right holder.","Provisional measurers are applicable if there is a demonstrable risk of evidence being destroyed.","The combination of injunction and delivery-up is not available if there is no damage incurred to the plaintiff."],"a":[3],"m":"ipr","c":1,"n":10,"e":"Lệnh cấm và giao nộp hàng vi phạm có thể áp dụng kể cả khi nguyên đơn không bị thiệt hại và có thể kết hợp với nhau. Vì vậy câu nói «không thể kết hợp nếu không có thiệt hại» là phát biểu sai cần chọn.","vi":{"q":"Phát biểu nào sau đây KHÔNG đúng theo luật Anh?","o":["Lệnh cấm (injunction) và giao nộp hàng vi phạm (delivery-up) có thể áp dụng ngay cả khi nguyên đơn không bị thiệt hại.","Tòa án có thể áp dụng biện pháp khẩn cấp tạm thời khi sự chậm trễ có khả năng gây thiệt hại không thể khắc phục cho chủ sở hữu quyền.","Biện pháp khẩn cấp tạm thời được áp dụng nếu có nguy cơ rõ ràng là chứng cứ sẽ bị tiêu hủy.","Không thể kết hợp lệnh cấm và giao nộp hàng vi phạm nếu nguyên đơn không bị thiệt hại."]}},
{"id":"ipr-11","q":"What is the best definition about \"passing-off\"?","o":["The use of identical or similar marks or get-ups to cause confusion in the public by relying on the reputation of a mark or get-up, which has already been used long enough.","The use of different mark by relying on the reputation of a mark or get-up, which has been used long enough. However, this use is not caused any confusion.","The use of distinctive marks or get-ups to cause confusion in the public","A trade mark infringement"],"a":[0],"m":"ipr","c":5,"n":11,"e":"Passing off là việc dùng nhãn hiệu hoặc get-up giống hoặc tương tự để gây nhầm lẫn, lợi dụng uy tín đã có. Hai yếu tố gắn với định nghĩa là uy tín (goodwill) và nhầm lẫn; {D} sai vì passing off không đồng nhất với xâm phạm nhãn hiệu.","vi":{"q":"Định nghĩa nào đúng nhất về \"passing-off\" (hành vi mạo danh, lợi dụng uy tín)?","o":["Việc sử dụng nhãn hiệu hoặc diện mạo thương mại (get-up) giống hệt hoặc tương tự để gây nhầm lẫn cho công chúng, dựa vào uy tín của một nhãn hiệu hoặc get-up đã được sử dụng đủ lâu.","Việc sử dụng một nhãn hiệu khác nhưng dựa vào uy tín của nhãn hiệu hoặc get-up đã được sử dụng đủ lâu; tuy nhiên việc sử dụng này không gây nhầm lẫn.","Việc sử dụng nhãn hiệu hoặc get-up có tính phân biệt để gây nhầm lẫn cho công chúng","Một hành vi xâm phạm nhãn hiệu"]}},
{"id":"ipr-12","q":"Philips has taken a photograph of a particular scenic view. John knew about that photograp.... still independently took a photograph with the same view, same perspectives. John's photograph... similar to the Philips'one. The two photographs are virtually indistinguishable.","o":["John had to ask Philips for consent before taking his photograph.","Philips can request John for a copyright compensation.","John made a copy of Philips' photograph and it is a copyright infringement.","It is not copying and not copyright infringement for John"],"a":[3],"m":"ipr","c":3,"n":12,"e":"Bản quyền chỉ chống sao chép, không chống sáng tạo độc lập. Dù hai bức ảnh giống nhau, nếu John tự chụp độc lập thì không phải sao chép và không xâm phạm.","vi":{"q":"Philips chụp một bức ảnh về một khung cảnh thiên nhiên nhất định. John biết về bức ảnh đó nhưng vẫn tự chụp một bức ảnh độc lập với cùng khung cảnh, cùng góc nhìn. Ảnh của John giống ảnh của Philips; hai bức ảnh gần như không thể phân biệt.","o":["John phải xin phép Philips trước khi chụp ảnh của mình.","Philips có thể yêu cầu John bồi thường bản quyền.","John đã sao chép ảnh của Philips và đó là hành vi xâm phạm bản quyền.","Đây không phải là sao chép và John không xâm phạm bản quyền"]}},
{"id":"ipr-13","q":"Which is an exception to copyright infringement?","o":["Research or private study","If a technical paper is published in a periodical with an abstract, then copying the abstract is permitted, unless there is a licensing scheme in force","Education","All of others are correct"],"a":[3],"m":"ipr","c":3,"n":13,"f":1,"e":"Nghiên cứu hoặc học tập cá nhân, sao chép phần tóm tắt bài báo (khi không có cơ chế cấp phép) và giáo dục đều là ngoại lệ hợp pháp nên chọn «tất cả».","vi":{"q":"Trường hợp nào là ngoại lệ đối với hành vi xâm phạm bản quyền?","o":["Nghiên cứu hoặc học tập cá nhân","Nếu một bài báo kỹ thuật được đăng trên tạp chí kèm phần tóm tắt thì được phép sao chép phần tóm tắt, trừ khi đang có cơ chế cấp phép","Giáo dục","Tất cả các đáp án còn lại đều đúng"]}},
{"id":"ipr-14","q":"In Vietnam law, how long the trade mark protection is?","o":["5 years","10 years","15 years","it depends but can last forever provided that the owner renews its application for protection"],"a":[3],"m":"ipr","c":4,"n":14,"e":"Ở Việt Nam, văn bằng bảo hộ nhãn hiệu có hiệu lực 10 năm và được gia hạn nhiều lần, mỗi lần 10 năm, nên về nguyên tắc có thể kéo dài vô thời hạn miễn là chủ sở hữu gia hạn.","vi":{"q":"Theo luật Việt Nam, nhãn hiệu được bảo hộ trong bao lâu?","o":["5 năm","10 năm","15 năm","Tùy trường hợp, nhưng có thể kéo dài vô thời hạn miễn là chủ sở hữu gia hạn hiệu lực bảo hộ"]}},
{"id":"ipr-15","q":"Since the aim of a trade mark is to encourage purchasers to buy your company's product or your company's service by using the mark when they place an order, what is deemed essential for a sign to be called \"trade mark\" from business perspective?","o":["Trade marks should be slightly different from marks used by competitors to avoid confusion.","Trade marks should be easy to remember and sufficiently different from marks used by competitors to avoid confusion.","That trade marks should be easy to remember and similar to marks used by competitors to avoid confusion.","That trade marks should be similar to marks used by competitors to create more confusions to enjoy benefits from dilution."],"a":[1],"m":"ipr","c":4,"n":15,"e":"Nhãn hiệu tốt phải dễ nhớ và đủ khác với nhãn hiệu của đối thủ để tránh nhầm lẫn. Cố ý giống đối thủ sẽ gây nhầm lẫn và có thể bị coi là xâm phạm.","vi":{"q":"Vì mục đích của nhãn hiệu là khuyến khích người mua chọn sản phẩm hoặc dịch vụ của công ty bạn khi đặt hàng, xét từ góc độ kinh doanh, điều gì là cần thiết để một dấu hiệu được gọi là \"nhãn hiệu\"?","o":["Nhãn hiệu nên hơi khác với nhãn hiệu của đối thủ để tránh nhầm lẫn.","Nhãn hiệu nên dễ nhớ và đủ khác biệt so với nhãn hiệu của đối thủ để tránh nhầm lẫn.","Nhãn hiệu nên dễ nhớ và giống với nhãn hiệu của đối thủ để tránh nhầm lẫn.","Nhãn hiệu nên giống với nhãn hiệu của đối thủ để gây thêm nhầm lẫn nhằm hưởng lợi từ sự pha loãng (dilution)."]}},
{"id":"ipr-16","q":"A Uniform Dispute Resolution Procedure (UDRP) is agreed by participants, which provide some mechanism to resolve dispute in terms of domain names and intellectual property.","o":["True.","False. UDRP provide mechanism to resolve dispute in terms of domain names only","False. UDRP provide mechanism to resolve dispute in terms of trade mark only","False. UDRP provide mechanism to resolve dispute in terms of the ownership of trade mark only."],"a":[0],"m":"ipr","c":5,"n":16,"e":"UDRP là thủ tục giải quyết tranh chấp tên miền theo thỏa thuận giữa các bên đăng ký, xử lý các tranh chấp giữa tên miền và quyền sở hữu trí tuệ (nhãn hiệu), nên phát biểu «đúng» là đáp án.","vi":{"q":"Thủ tục giải quyết tranh chấp thống nhất (UDRP) do các bên tham gia thỏa thuận, cung cấp cơ chế giải quyết tranh chấp liên quan đến tên miền và sở hữu trí tuệ.","o":["Đúng.","Sai. UDRP chỉ cung cấp cơ chế giải quyết tranh chấp về tên miền","Sai. UDRP chỉ cung cấp cơ chế giải quyết tranh chấp về nhãn hiệu","Sai. UDRP chỉ cung cấp cơ chế giải quyết tranh chấp về quyền sở hữu nhãn hiệu."]}},
{"id":"ipr-17","q":"Are domain names intellectual property?","o":["Not really.","Yes, they are.","Yes, provided that domain names are registered with the Internet service providers","Yes, since domain names provides the exact information of the owner of goods or services on the Internet"],"a":[0],"m":"ipr","c":5,"n":17,"e":"Tên miền bản thân không phải là một loại quyền sở hữu trí tuệ độc lập như bản quyền hay nhãn hiệu; nó được bảo vệ gián tiếp qua nhãn hiệu, passing off và UDRP. Vì thế đề chọn «Không hẳn».","vi":{"q":"Tên miền có phải là tài sản trí tuệ không?","o":["Không hẳn.","Có.","Có, với điều kiện tên miền được đăng ký với các nhà cung cấp dịch vụ Internet","Có, vì tên miền cung cấp thông tin chính xác về chủ sở hữu hàng hóa hoặc dịch vụ trên Internet"]}},
{"id":"ipr-18","q":"What are Civil remedies?","o":["Provisional measures, Injunction, imprisonment","Delivery-up, Compensatory damages, Punitive damages; and Account of profits","Imprisonment, Punitive damages; and Account of profits","Delivery-up, Imprisonment, Compensatory damages"],"a":[1],"m":"ipr","c":1,"n":18,"e":"Các biện pháp khắc phục dân sự gồm giao nộp hàng vi phạm, bồi thường thiệt hại bù đắp, bồi thường mang tính trừng phạt và truy thu lợi nhuận. Phạt tù là chế tài hình sự, không thuộc dân sự.","vi":{"q":"Các biện pháp khắc phục dân sự (civil remedies) gồm những gì?","o":["Biện pháp khẩn cấp tạm thời, lệnh cấm, phạt tù","Giao nộp hàng vi phạm, bồi thường thiệt hại bù đắp, bồi thường mang tính trừng phạt và truy thu lợi nhuận","Phạt tù, bồi thường mang tính trừng phạt và truy thu lợi nhuận","Giao nộp hàng vi phạm, phạt tù, bồi thường thiệt hại bù đắp"]}},
{"id":"ipr-19","q":"Cellupro, a company that designed and manufactured cell phones, had a unique design to their products and a particular color for their phones and packaging. This design and color is known as","o":["trade dress.","a service mark.","a fanciful mark.","trade style."],"a":[0],"m":"ipr","c":5,"n":19,"e":"Thiết kế và màu sắc đặc trưng của sản phẩm và bao bì tạo nên diện mạo thương mại, gọi là trade dress.","vi":{"q":"Cellupro là công ty thiết kế và sản xuất điện thoại di động, có thiết kế độc đáo cho sản phẩm và một màu sắc riêng cho điện thoại và bao bì. Thiết kế và màu sắc này được gọi là","o":["trade dress (diện mạo thương mại).","nhãn hiệu dịch vụ.","nhãn hiệu tưởng tượng (fanciful mark).","phong cách thương mại (trade style)."]}},
{"id":"ipr-20","q":"What does a trademark protect?","o":["A work of art","A secret formula","Logos, names and brands","General information"],"a":[2],"m":"ipr","c":4,"n":20,"e":"Nhãn hiệu bảo hộ dấu hiệu phân biệt hàng hóa/dịch vụ như logo, tên và thương hiệu. Tác phẩm nghệ thuật thuộc bản quyền, công thức bí mật thuộc bí mật thương mại.","vi":{"q":"Nhãn hiệu bảo hộ cái gì?","o":["Một tác phẩm nghệ thuật","Một công thức bí mật","Logo, tên và thương hiệu","Thông tin chung"]}},
{"id":"ipr-21","q":"The protection of copyright excludes","o":["A single word","Songs","A list of names and addresses in a telephone directory","Computer programs"],"a":[0],"m":"ipr","c":2,"n":21,"e":"Một từ đơn lẻ quá ngắn, không đạt mức nguyên gốc để được bảo hộ bản quyền. Bài hát, danh bạ (tập hợp) và chương trình máy tính đều được bảo hộ.","vi":{"q":"Bản quyền KHÔNG bảo hộ","o":["Một từ đơn lẻ","Bài hát","Danh sách tên và địa chỉ trong danh bạ điện thoại","Chương trình máy tính"]}},
{"id":"ipr-22","q":"Which is NOT right about \"Copying in a different medium\"?","o":["a photocopy of a book.","a scanned-in digital copy of a photograph","a reproduction and the copy have a material form","a transiation a copyright work"],"a":[3],"m":"ipr","c":3,"n":22,"e":"Sao chép sang phương tiện khác gồm photocopy, quét ảnh và tạo bản sao dạng vật chất. Dịch thuật là chuyển thể (adaptation), một hành vi riêng nên không thuộc nhóm này.","vi":{"q":"Điều nào KHÔNG đúng về \"sao chép sang một phương tiện khác\"?","o":["bản photocopy một cuốn sách.","bản sao kỹ thuật số quét từ một bức ảnh","bản sao chép và bản gốc đều ở dạng vật chất","bản dịch một tác phẩm có bản quyền"]}},
{"id":"ipr-23","q":"Acme Corporation attempted to register a trade mark that was generic and not fanciful, arbitrary, suggestive or descriptive with a secondary meaning. Under these circumstances, Acme has","o":["an excellent case for the registration of a trade mark because generic trade marks, as opposed to fanciful, arbitrary or suggestive trade marks, are capable of being copyrighted.","an excellent case for the registration of a trade mark because all trade marks are capable of being copyrighted.","no case for registration of the trade mark because a trade mark must be fanciful, arbitrary or suggestive to be capable of being copyrighted.","no case for registration of the trade mark because a trade mark must be independent, rather than fanciful, arbitrary or suggestive, to be capable of being copyrighted."],"a":[2],"m":"ipr","c":4,"n":23,"e":"Nhãn hiệu chung chung (generic) không có tính phân biệt nên không đăng ký được; chỉ nhãn hiệu tưởng tượng, tùy ý, gợi ý (hoặc mô tả có nghĩa thứ cấp) mới được. Câu {C} diễn đạt đúng ý này dù dùng sai chữ «bản quyền».","vi":{"q":"Công ty Acme định đăng ký một nhãn hiệu mang tính chung chung (generic), không phải là nhãn hiệu tưởng tượng, tùy ý, gợi ý hay mô tả có nghĩa thứ cấp. Trong tình huống này, Acme","o":["có cơ sở vững chắc để đăng ký nhãn hiệu vì các nhãn hiệu chung chung, khác với nhãn hiệu tưởng tượng, tùy ý hoặc gợi ý, có thể được bảo hộ bản quyền.","có cơ sở vững chắc để đăng ký nhãn hiệu vì mọi nhãn hiệu đều có thể được bảo hộ bản quyền.","không có cơ sở đăng ký nhãn hiệu vì nhãn hiệu phải là nhãn hiệu tưởng tượng, tùy ý hoặc gợi ý thì mới có thể được bảo hộ bản quyền.","không có cơ sở đăng ký nhãn hiệu vì nhãn hiệu phải mang tính độc lập, thay vì tưởng tượng, tùy ý hoặc gợi ý, thì mới có thể được bảo hộ bản quyền."]},"k":"Đề diễn đạt lẫn lộn «bảo hộ bản quyền» với «đăng ký nhãn hiệu» (nhãn hiệu không được bảo hộ bằng bản quyền); chỉ cần nhớ ý chính: nhãn hiệu chung chung (generic) không đăng ký được, phải có tính phân biệt."},
{"id":"ipr-24","q":"The \"Commonplace\", which is the requirement for protection of design right, means:","o":["The similarities of the design in question when compared objectively to other designs","\"Not original\" in the design field in question.","None of A&B","Both of A&B"],"a":[3],"m":"ipr","c":6,"n":24,"f":1,"e":"«Commonplace» theo luật quyền kiểu dáng nghĩa là thiết kế tầm thường, không có gì đặc biệt trong lĩnh vực, bao gồm cả việc không nguyên gốc và sự tương đồng khách quan với thiết kế khác. Nên {A} và {B} đều đúng.","vi":{"q":"\"Commonplace\" (tầm thường, phổ biến) là điều kiện để được bảo hộ quyền kiểu dáng (design right), có nghĩa là:","o":["Những điểm tương đồng của thiết kế đang xét khi so sánh khách quan với các thiết kế khác","\"Không nguyên gốc\" trong lĩnh vực thiết kế đang xét.","Không phải A và B","Cả A và B"]}},
{"id":"ipr-25","q":"What protects the intellectual property created by designers?","o":["Copyright","Registered designs","Both copyright and registered designs","Neither copyright nor registered designs"],"a":[2],"m":"ipr","c":1,"n":25,"e":"Tài sản trí tuệ của nhà thiết kế có thể được bảo hộ đồng thời bằng bản quyền (bản vẽ, thiết kế) và kiểu dáng đã đăng ký (hình dáng sản phẩm).","vi":{"q":"Quyền nào bảo hộ tài sản trí tuệ do các nhà thiết kế tạo ra?","o":["Bản quyền","Kiểu dáng đã đăng ký","Cả bản quyền và kiểu dáng đã đăng ký","Không phải bản quyền cũng không phải kiểu dáng đã đăng ký"]}},
{"id":"ipr-26","q":"What are criteria for winning a transfer of a domain name?","o":["A domain name must be identical or confusingly similar to a registered or unregistered trade mark, the use complained of must be by someone having no legitimate interest in the name, and bad faith","When there is innocently confusing use, an offer to sell the mark or a history of registering names based on third party trade marks.","All are correct","None of the answers are correct"],"a":[0],"m":"ipr","c":5,"n":26,"f":1,"e":"Để đòi chuyển giao tên miền cần ba điều kiện: tên trùng hoặc gây nhầm lẫn với nhãn hiệu, bên kia không có lợi ích chính đáng, và có ý định xấu (bad faith). {B} chỉ nêu biểu hiện của ý xấu, không đủ.","vi":{"q":"Tiêu chí để thắng kiện đòi chuyển giao một tên miền là gì?","o":["Tên miền phải trùng hoặc gây nhầm lẫn với một nhãn hiệu đã đăng ký hoặc chưa đăng ký; người sử dụng bị khiếu nại không có lợi ích chính đáng đối với tên đó; và có ý định xấu (bad faith)","Có hành vi sử dụng gây nhầm lẫn một cách vô tình, chào bán nhãn hiệu hoặc có tiền sử đăng ký tên dựa trên nhãn hiệu của bên thứ ba.","Tất cả đều đúng","Không đáp án nào đúng"]}},
{"id":"ipr-27","q":"A Uniform Dispute Resolution Procedure (UDRP) is run by","o":["WIPO","WTO","UN","UNCITRAL"],"a":[0],"m":"ipr","c":5,"n":27,"e":"UDRP do WIPO (Tổ chức Sở hữu Trí tuệ Thế giới) điều hành thông qua ICANN.","vi":{"q":"Thủ tục giải quyết tranh chấp thống nhất (UDRP) do tổ chức nào điều hành?","o":["WIPO","WTO","Liên hợp quốc (UN)","UNCITRAL"]}},
{"id":"ipr-28","q":"What does indirect compensation include?","o":["post-calculated, recurring payments, the amount of which is determined under economic (sales, profits).","a pre-calculated amount paid once or in installments","compensation for services and assistance rendered by technical or professional experts.","dividend or income from related operations: commission paid to licensor for his assistance"],"a":[1],"m":"ipr","c":1,"n":28,"e":"Theo đáp án của đề, khoản tiền tính trước trả một lần hoặc trả góp được chọn. Cần chú ý đây là mâu thuẫn với phân loại ở câu #262–264 (xem cảnh báo bên dưới).","vi":{"q":"Thù lao gián tiếp (indirect compensation) bao gồm những gì?","o":["các khoản thanh toán định kỳ tính sau, có số tiền xác định theo kết quả kinh tế (doanh thu, lợi nhuận).","một khoản tiền tính trước, trả một lần hoặc trả góp","thù lao cho dịch vụ và sự hỗ trợ của các chuyên gia kỹ thuật hoặc chuyên môn.","cổ tức hoặc thu nhập từ các hoạt động liên quan: hoa hồng trả cho bên cấp phép vì hỗ trợ bán hàng."]},"k":"Đề chọn {B}, nhưng câu #264 (cùng nội dung) chọn {D}: thù lao gián tiếp = cổ tức hoặc hoa hồng từ các hoạt động liên quan; khoản tiền tính trước trả một lần là «lump-sum» (#263). Nhiều khả năng bộ đề gốc gán nhầm câu này."},
{"id":"ipr-29","q":"Knowing Kevin is a self-employed designerCharlotte has introduced Kevin to Company XThe Company X then commissioned Kevin for 1500 Euro to design a machine. Who owns the right to the register design of the machine?","o":["Kevin himself","Company X","Charlotte","Company X and Kevin"],"a":[1],"m":"ipr","c":6,"n":29,"e":"Theo quy tắc cũ của luật Anh về kiểu dáng đã đăng ký, bên đặt hàng (Công ty X trả 1500 euro) là chủ sở hữu, không phải nhà thiết kế tự do hay người giới thiệu.","vi":{"q":"Biết Kevin là nhà thiết kế tự do, Charlotte giới thiệu Kevin cho Công ty X. Công ty X sau đó thuê Kevin thiết kế một cỗ máy với giá 1500 euro. Ai sở hữu quyền đối với kiểu dáng đăng ký của cỗ máy?","o":["Chính Kevin","Công ty X","Charlotte","Công ty X và Kevin"]},"k":"Theo quy tắc cũ của luật Anh, bên đặt hàng (Công ty X) là chủ sở hữu kiểu dáng; luật Anh hiện hành (từ 10/2014) đã bỏ quy tắc này và nhà thiết kế là chủ sở hữu. Đề theo quy tắc cũ."},
{"id":"ipr-30","q":"Pictorial design or logo is protected by which IPRs?","o":["Copyright, registered design, trademark","Topography right, trademark, design right","Registered design, confidential information, copyright","Topography right, confidential information, copyright"],"a":[0],"m":"ipr","c":1,"n":30,"e":"Logo/hình vẽ được bảo hộ bằng bản quyền (là tác phẩm đồ họa), kiểu dáng đã đăng ký (hình dáng) và nhãn hiệu (dấu hiệu nhận diện).","vi":{"q":"Hình vẽ hoặc logo được bảo hộ bởi những quyền sở hữu trí tuệ nào?","o":["Bản quyền, kiểu dáng đã đăng ký, nhãn hiệu","Quyền đối với thiết kế bố trí mạch bán dẫn (topography right), nhãn hiệu, quyền kiểu dáng","Kiểu dáng đã đăng ký, thông tin bí mật, bản quyền","Quyền đối với thiết kế bố trí mạch bán dẫn, thông tin bí mật, bản quyền"]}},
{"id":"ipr-31","q":"How long is the duration of computer-generated right according to the UK law?","o":["Lasts for the life of its creator plus a further 50 years.","Lasts for 70 years begins to run on the death of the last surviving creator if two or more.... jointly involved in the work","The copyright lasts for 50 years from the end of the year in which the copyright material....","Lasts for 15 years from the end of the year the database was created or made accessible"],"a":[2],"m":"ipr","c":2,"n":31,"e":"Theo luật Anh, bản quyền với tác phẩm do máy tính tạo ra kéo dài 50 năm kể từ cuối năm tác phẩm được tạo ra, không tính theo đời tác giả.","vi":{"q":"Theo luật Anh, bản quyền đối với tác phẩm do máy tính tạo ra (computer-generated) có thời hạn bao lâu?","o":["Suốt đời người tạo ra cộng thêm 50 năm.","70 năm, bắt đầu tính từ khi người sáng tạo cuối cùng qua đời nếu có hai hay nhiều người cùng tham gia tạo ra tác phẩm.","Bản quyền kéo dài 50 năm kể từ cuối năm mà tài liệu có bản quyền được tạo ra....","15 năm kể từ cuối năm cơ sở dữ liệu được tạo ra hoặc được công bố, cho phép truy cập."]}},
{"id":"ipr-32","q":"In the 1990s, there was an explosion of names registered by US Network Solutions, the administrator of the top level domain (TLD) with the suffix.com. What sorts of problems quickly arose then:","o":["owners of trade marks identical to the domain name objected to use of the domain name, and unscrupulous persons registered variations of famous company names and offered to sell them for large sums of money - this is called cyber-squatting.","Company can easily get their domain name as they wish on the Internet, and this is more easier to company with famous brand.","People can register for domain names easier and provide such names to anyone in need for free","Nothing happened."],"a":[0],"m":"ipr","c":5,"n":32,"e":"Bùng nổ đăng ký tên miền .com dẫn đến việc chủ nhãn hiệu phản đối và những kẻ đăng ký tên của công ty nổi tiếng để bán giá cao, gọi là cyber-squatting.","vi":{"q":"Vào những năm 1990 có sự bùng nổ việc đăng ký tên miền tại Network Solutions (Mỹ), đơn vị quản lý tên miền cấp cao nhất (TLD) đuôi .com. Khi đó nhanh chóng nảy sinh những vấn đề gì?","o":["chủ sở hữu các nhãn hiệu trùng với tên miền phản đối việc sử dụng tên miền đó, và những kẻ vô lương tâm đăng ký các biến thể của tên các công ty nổi tiếng rồi chào bán với giá rất cao — gọi là cyber-squatting (chiếm giữ tên miền).","Các công ty dễ dàng lấy được tên miền như ý trên Internet, và việc này càng dễ hơn với công ty có thương hiệu nổi tiếng.","Mọi người dễ đăng ký tên miền hơn và cung cấp miễn phí những tên miền đó cho bất kỳ ai cần.","Không có chuyện gì xảy ra."]}},
{"id":"ipr-33","q":"If a company develops a new technology for producing a special range of clothes, what type of intellectual property right can it use to prevent other from using such technology","o":["Copyright","Trademarks","Registered designs","Patents"],"a":[3],"m":"ipr","c":1,"n":33,"e":"Công nghệ/quy trình sản xuất mới được bảo hộ bằng sáng chế, cho quyền ngăn người khác sử dụng công nghệ đó.","vi":{"q":"Nếu một công ty phát triển công nghệ mới để sản xuất một dòng quần áo đặc biệt, họ có thể dùng loại quyền sở hữu trí tuệ nào để ngăn người khác sử dụng công nghệ đó?","o":["Bản quyền","Nhãn hiệu","Kiểu dáng đã đăng ký","Sáng chế"]}},
{"id":"ipr-34","q":"Cindy has very detailed and interesting ideas on writing a book. Based on these ideas, David writes a book without attribution of Cindy. David........","o":["infringes paternity right","infringes adaptation right","Infringes reproduction right","not infringes intellectual property right"],"a":[3],"m":"ipr","c":2,"n":34,"e":"Bản quyền bảo hộ sự thể hiện chứ không bảo hộ ý tưởng. David chỉ dựa vào ý tưởng của Cindy nên không xâm phạm quyền sở hữu trí tuệ nào.","vi":{"q":"Cindy có những ý tưởng rất chi tiết và thú vị về việc viết một cuốn sách. Dựa trên các ý tưởng đó, David viết một cuốn sách mà không ghi nhận Cindy. David........","o":["xâm phạm quyền được nhận là tác giả (paternity right)","xâm phạm quyền chuyển thể (adaptation right)","xâm phạm quyền sao chép (reproduction right)","không xâm phạm quyền sở hữu trí tuệ"]}},
{"id":"ipr-35","q":"To be protected by registered design, an article must...","o":["Have an individual character","Be original","Be non- commonplace","Be new"],"a":[0],"m":"ipr","c":6,"n":35,"e":"Điều kiện bảo hộ kiểu dáng đã đăng ký là tính mới và tính độc đáo riêng (individual character). Trong các phương án chỉ có «tính độc đáo riêng» là đúng thuật ngữ của chế độ đăng ký.","vi":{"q":"Để được bảo hộ bằng kiểu dáng đã đăng ký, một sản phẩm phải...","o":["Có tính độc đáo riêng (individual character)","Nguyên gốc (original)","Không tầm thường (non-commonplace)","Mới (new)"]}},
{"id":"ipr-36","q":"Which of these statements is true about the general nature of passing off?","o":["The defendant must intend to cause loss","The misrepresentation must be intentional","There must be a false representation","There must be actual damages"],"a":[2],"m":"ipr","c":5,"n":36,"e":"Passing off đòi hỏi có sự trình bày sai sự thật (false representation) gây nhầm lẫn cho khách hàng. Không cần chứng minh ý định gây hại hay thiệt hại thực tế đã xảy ra.","vi":{"q":"Phát biểu nào sau đây đúng về bản chất chung của passing off?","o":["Bị đơn phải có ý định gây thiệt hại","Việc trình bày sai sự thật phải là cố ý","Phải có sự trình bày sai sự thật (false representation)","Phải có thiệt hại thực tế"]}},
{"id":"ipr-37","q":"Design right applies to:","o":["Drawings produced in an industrial context","Tangible three-dimensional Articles","Artistic drawings","Textbook on Design rights"],"a":[1],"m":"ipr","c":6,"n":37,"e":"Quyền kiểu dáng (design right) bảo hộ hình dáng ba chiều của sản phẩm hữu hình. Bản vẽ, tranh nghệ thuật hay sách thuộc bản quyền.","vi":{"q":"Quyền kiểu dáng (design right) áp dụng cho:","o":["Bản vẽ được tạo ra trong bối cảnh công nghiệp","Các sản phẩm ba chiều hữu hình","Bản vẽ nghệ thuật","Sách giáo trình về quyền kiểu dáng"]}},
{"id":"ipr-38","q":"Which of followings is correct?","o":["Passing off is an infringement of only unregistered trademark","Passing off is an infringement of only registered trademark","Passing off is an infringement of both unregistered and registered trademark","Passing off is an infringement of neither unregistered nor registered trademark"],"a":[2],"m":"ipr","c":5,"n":38,"e":"Theo đáp án của đề, passing off liên quan đến cả nhãn hiệu chưa đăng ký lẫn đã đăng ký. Cần lưu ý câu #178 chọn khác (xem cảnh báo).","vi":{"q":"Phát biểu nào sau đây đúng?","o":["Passing off chỉ là hành vi xâm phạm nhãn hiệu chưa đăng ký","Passing off chỉ là hành vi xâm phạm nhãn hiệu đã đăng ký","Passing off là hành vi xâm phạm cả nhãn hiệu chưa đăng ký lẫn đã đăng ký","Passing off không phải xâm phạm nhãn hiệu chưa đăng ký cũng không phải đã đăng ký"]},"k":"Câu #178 (cùng chủ đề) lại chọn «passing off chỉ liên quan nhãn hiệu chưa đăng ký». Hai câu của đề không thống nhất; theo luật Anh, passing off bảo vệ uy tín (goodwill) của nhãn hiệu chưa đăng ký, còn nhãn hiệu đã đăng ký được bảo vệ bằng quy định xâm phạm nhãn hiệu."},
{"id":"ipr-39","q":"Which is the principle of \"national treatment\" stipulated in Bern Convention?","o":["Works originating in one of the Contracting States must be given the same protection in each of the other Contracting States as the latter grants to the works of its own nationals","Protection must not be conditional upon compliance with any formality","Protection is independent of the existence of protection in the country of origin of the work","As to works, protection must include \"every production in the literary, scientific and artistic domain, whatever the mode or form of its expression\""],"a":[0],"m":"ipr","c":2,"n":39,"e":"Đối xử quốc gia (national treatment): tác phẩm từ một nước thành viên được bảo hộ ở nước thành viên khác như tác phẩm của công dân nước đó.","vi":{"q":"Đâu là nguyên tắc \"đối xử quốc gia\" (national treatment) được quy định trong Công ước Berne?","o":["Tác phẩm có nguồn gốc từ một nước thành viên phải được bảo hộ ở mỗi nước thành viên khác giống như nước đó bảo hộ tác phẩm của công dân mình","Việc bảo hộ không được phụ thuộc vào việc tuân thủ bất kỳ thủ tục nào","Việc bảo hộ độc lập với việc tác phẩm có được bảo hộ ở nước xuất xứ hay không","Đối với tác phẩm, sự bảo hộ phải bao gồm \"mọi sản phẩm trong lĩnh vực văn học, khoa học và nghệ thuật, bất kể phương thức hay hình thức thể hiện\""]}},
{"id":"ipr-40","q":"Company M subcontracts Company H to copy and make a product which owned by Company N with a clear instruction to manufacture the copy. Company H knows the product is owned by Company N. Which of the following is RIGHT?","o":["M has transferred the legal burden to H on the infringement of Design right.","His not responsible for the infringement","M is not responsible for the infringement as it is not the one drectily coppied and made the product.","Both H & M infringed N's Design right."],"a":[3],"m":"ipr","c":6,"n":40,"e":"H trực tiếp sao chép và biết đó là sản phẩm của N nên xâm phạm; M ra lệnh/ủy quyền sao chép cũng chịu trách nhiệm. Cả hai đều xâm phạm quyền kiểu dáng của N.","vi":{"q":"Công ty M thuê Công ty H sao chép và sản xuất một sản phẩm thuộc sở hữu của Công ty N, kèm chỉ dẫn rõ ràng là phải làm bản sao. Công ty H biết sản phẩm đó thuộc sở hữu của Công ty N. Phát biểu nào sau đây ĐÚNG?","o":["M đã chuyển trách nhiệm pháp lý về hành vi xâm phạm quyền kiểu dáng sang H.","H không chịu trách nhiệm về hành vi xâm phạm.","M không chịu trách nhiệm về hành vi xâm phạm vì M không trực tiếp sao chép và làm ra sản phẩm.","Cả H và M đều xâm phạm quyền kiểu dáng của N."]}},
{"id":"ipr-41","q":"What can be defined as \"fees\"?","o":["Post-calculated, recurring payments, the amount of which is determined under economic use or result (sales, profits).","A pre-calculated amount paid once or in installments","Compensation for services and assistance rendered by technical or professional experts.","Dividend or income from related operations: commission paid to licensor for his assistance in selling."],"a":[3],"m":"ipr","c":1,"n":41,"e":"Theo đáp án của đề, «phí» ứng với cổ tức/hoa hồng từ hoạt động liên quan. Cần lưu ý đây mâu thuẫn với phân loại ở câu #262–264 (xem cảnh báo).","vi":{"q":"Điều gì có thể được định nghĩa là \"phí\" (fees)?","o":["Các khoản thanh toán định kỳ tính sau, có số tiền xác định theo kết quả hoặc mức sử dụng kinh tế (doanh thu, lợi nhuận).","Một khoản tiền tính trước, trả một lần hoặc trả góp","Thù lao cho dịch vụ và sự hỗ trợ của các chuyên gia kỹ thuật hoặc chuyên môn.","Cổ tức hoặc thu nhập từ các hoạt động liên quan: hoa hồng trả cho bên cấp phép vì hỗ trợ bán hàng."]},"k":"Đề chọn {D}, nhưng theo cách phân loại ở các câu #262–264, {D} là thù lao gián tiếp còn «phí» (fees) là thù lao cho dịch vụ và hỗ trợ của chuyên gia ({C}). Nhiều khả năng bộ đề gốc gán nhầm; xem thêm câu #28."},
{"id":"ipr-42","q":"A salesman of a bags shop exhibited and sold a fake Chanel clutch for 1.000.000vnd (provided that the real Chanel clutch costs 20.000.000vnd). But he told clients that this clutch is fake. This is......","o":["A passing off","Not a passing off but an infringement of trademark","A passing off and an infringement of trademark","Neither a passing off nor infringement of trademark"],"a":[1],"m":"ipr","c":5,"n":42,"e":"Người bán nói rõ đây là hàng giả nên khách không bị nhầm lẫn về nguồn gốc, do đó không phải passing off (thiếu sự trình bày sai). Nhưng việc gắn dấu hiệu Chanel lên hàng giả vẫn xâm phạm nhãn hiệu.","vi":{"q":"Một nhân viên bán hàng ở cửa hàng túi xách trưng bày và bán một chiếc clutch Chanel giả với giá 1.000.000 đồng (trong khi hàng thật giá 20.000.000 đồng), nhưng anh ta nói rõ với khách rằng chiếc clutch này là hàng giả. Đây là ......","o":["Hành vi passing off","Không phải passing off mà là xâm phạm nhãn hiệu","Vừa là passing off vừa là xâm phạm nhãn hiệu","Không phải passing off cũng không phải xâm phạm nhãn hiệu"]}},
{"id":"ipr-43","q":"Which is considered as copying by adaption?","o":["Adapting a copyright work, which includes translating it.","Copying one line of a well-known song in a nontechnical context","The extraction or reutilization of a computer-stored database, whether the whole or a substantial part","A photocopy of a book, or a scanned-in digital copy of a photograph"],"a":[1],"m":"ipr","c":3,"n":43,"e":"Theo đáp án của đề, chọn {B}; tuy nhiên theo luật Anh chuyển thể gồm cả dịch tác phẩm (phương án {A}). Xem cảnh báo bên dưới.","vi":{"q":"Hành vi nào được coi là sao chép bằng cách chuyển thể (copying by adaptation)?","o":["Chuyển thể một tác phẩm có bản quyền, bao gồm cả việc dịch tác phẩm đó.","Sao chép một dòng của một bài hát nổi tiếng trong ngữ cảnh phi kỹ thuật","Trích xuất hoặc khai thác lại cơ sở dữ liệu lưu trên máy tính, dù toàn bộ hay một phần đáng kể","Bản photocopy một cuốn sách, hoặc bản sao kỹ thuật số quét từ một bức ảnh"]},"k":"Đáp án của đề là {B}, nhưng theo luật Anh (CDPA 1988, s.21), «chuyển thể» (adaptation) gồm cả việc dịch tác phẩm, tức phương án {A} mới sát nhất. Nhiều khả năng đề gốc nhầm."},
{"id":"ipr-44","q":"Collective trade mark means....","o":["There are many users of this trade mark","There are many owners of this trade mark","There is a collection of trademarks used by one company","There is a collection of products sharing this trademark"],"a":[0],"m":"ipr","c":4,"n":44,"e":"Nhãn hiệu tập thể (collective trade mark) do một tổ chức/hiệp hội sở hữu và nhiều thành viên được sử dụng.","vi":{"q":"Nhãn hiệu tập thể (collective trade mark) có nghĩa là....","o":["Có nhiều người sử dụng nhãn hiệu này","Có nhiều chủ sở hữu nhãn hiệu này","Có một bộ sưu tập nhiều nhãn hiệu do một công ty sử dụng","Có một bộ sưu tập sản phẩm dùng chung nhãn hiệu này"]}},
{"id":"ipr-45","q":"Which of the following form of a spoken word is NOT protected by copyright?","o":["A fully prepared text","A note","In shorthand, or on tape or disk","None of the answer is correct"],"a":[1],"m":"ipr","c":2,"n":45,"f":1,"e":"Lời nói chỉ được bảo hộ bản quyền khi được ghi lại (văn bản soạn sẵn, tốc ký, băng, đĩa). Một ghi chú (note) thô sơ không đạt mức bảo hộ.","vi":{"q":"Hình thức nào sau đây của lời nói KHÔNG được bảo hộ bản quyền?","o":["Một văn bản đã soạn đầy đủ","Một ghi chú","Dưới dạng tốc ký, hoặc trên băng hay đĩa","Không đáp án nào đúng"]}},
{"id":"ipr-46","q":"A trade mark being an invented word must......","o":["Be new","Be distinctive","Indicate the nature of the goods","Be meaningful"],"a":[1],"m":"ipr","c":4,"n":46,"e":"Từ tự đặt ra (invented word) chỉ cần có tính phân biệt. Nó không cần có nghĩa, và không được chỉ ra bản chất hàng hóa.","vi":{"q":"Một nhãn hiệu là từ do tự đặt ra (invented word) thì phải......","o":["Mới","Có tính phân biệt (distinctive)","Chỉ ra bản chất của hàng hóa","Có ý nghĩa"]}},
{"id":"ipr-47","q":"Which of the followings is not secondary infringement of copyrights?","o":["A copy is distributed either internally within a business or outside the company","A single copy of a computer program bought abroad, and brought it home for using in connection with professional engineering work.","Photocopying of a book","Showing a TV broadcast, cable programme, film or playing music to the public"],"a":[1],"m":"ipr","c":3,"n":47,"e":"Phân phối bản sao, chiếu chương trình truyền hình/phát nhạc trước công chúng là vi phạm thứ cấp (có liên quan đến bản sao vi phạm hoặc trình diễn). Đáp án của đề chọn {B} (một bản chương trình mua ở nước ngoài dùng cho công việc cá nhân).","vi":{"q":"Điều nào sau đây KHÔNG phải là vi phạm bản quyền thứ cấp (secondary infringement)?","o":["Một bản sao được phân phối trong nội bộ doanh nghiệp hoặc ra bên ngoài công ty","Một bản chương trình máy tính duy nhất mua ở nước ngoài, mang về nước để dùng cho công việc kỹ thuật chuyên môn.","Photocopy một cuốn sách","Chiếu chương trình truyền hình, chương trình cáp, phim hoặc phát nhạc cho công chúng"]},"k":"Phương án {C} (photocopy sách) thực chất là vi phạm trực tiếp (primary), cũng không phải thứ cấp nên câu này khá mập mờ."},
{"id":"ipr-48","q":"To protect Registered Design, an owner of Registered design needs to do:","o":["Show that there has been copying","Show that the same or a substantially similar design is being applied to a product.","Prove that the design was not created independently by the infringer","All of the above"],"a":[3],"m":"ipr","c":6,"n":48,"f":1,"e":"Với kiểu dáng đã đăng ký, chủ sở hữu có thể chứng minh qua việc có sao chép, thiết kế giống hoặc gần giống được áp dụng, và người vi phạm không tự sáng tạo độc lập. Đề tổng hợp cả ba nên chọn «tất cả».","vi":{"q":"Để bảo vệ kiểu dáng đã đăng ký, chủ sở hữu kiểu dáng đã đăng ký cần làm gì:","o":["Chứng minh đã có hành vi sao chép","Chứng minh cùng một thiết kế, hoặc thiết kế gần như tương tự, đang được áp dụng cho một sản phẩm.","Chứng minh rằng người vi phạm không tự sáng tạo ra thiết kế đó một cách độc lập","Tất cả các đáp án trên"]}},
{"id":"ipr-49","q":"Dennis has successfully registered his design (after 9 December 2001). After that, Mike, who with a similar design, applies to have the Dennis's registration invalidated on the grounds that the design was not new. Which of the following is RIGHT?","o":["Mike can do that only when Dennis design has not been registered","Mike can do that even after Dennis design has been successful registered","Mike cannot do that after Dennis design has been successful registered","Mike can do that after Dennis' design has been successful registered if Dennis design did not have individual character and was not new."],"a":[3],"m":"ipr","c":6,"n":49,"e":"Sau khi đăng ký, người khác vẫn có thể yêu cầu hủy hiệu lực nếu kiểu dáng thiếu tính mới hoặc tính độc đáo riêng.","vi":{"q":"Dennis đã đăng ký thành công kiểu dáng của mình (sau ngày 9/12/2001). Sau đó, Mike có kiểu dáng tương tự nộp đơn yêu cầu hủy hiệu lực đăng ký của Dennis với lý do kiểu dáng không mới. Phát biểu nào sau đây ĐÚNG?","o":["Mike chỉ có thể làm vậy khi kiểu dáng của Dennis chưa được đăng ký","Mike có thể làm vậy ngay cả sau khi kiểu dáng của Dennis đã được đăng ký thành công","Mike không thể làm vậy sau khi kiểu dáng của Dennis đã được đăng ký thành công","Mike có thể làm vậy sau khi kiểu dáng của Dennis đã được đăng ký nếu kiểu dáng của Dennis không có tính độc đáo riêng và không mới."]}},
{"id":"ipr-50","q":"Anders has created a triangle classes box. The box could have been protected by a registered design but no application was filed. What is the requirement if the box is protected by Design right?","o":["Novelty","Not commonplace","Individual character","All of the above"],"a":[1],"m":"ipr","c":6,"n":50,"f":1,"e":"Quyền kiểu dáng (không đăng ký) đòi hỏi thiết kế nguyên gốc và không tầm thường (not commonplace). Tính mới và tính độc đáo riêng là điều kiện của kiểu dáng đã đăng ký.","vi":{"q":"Anders đã tạo ra một chiếc hộp hình tam giác. Chiếc hộp có thể được bảo hộ bằng kiểu dáng đã đăng ký nhưng không có đơn nào được nộp. Điều kiện để chiếc hộp được bảo hộ bằng quyền kiểu dáng (design right) là gì?","o":["Tính mới","Không tầm thường (not commonplace)","Tính độc đáo riêng (individual character)","Tất cả các đáp án trên"]}},
{"id":"ipr-51","q":"Secondary copyright infringement is:","o":["Copying the material without permission.","Trading of those illegal copies","Rewriting the material without permission.","Scanning the material without permission."],"a":[1],"m":"ipr","c":3,"n":51,"e":"Vi phạm thứ cấp (secondary) liên quan đến buôn bán, kinh doanh các bản sao vi phạm. Sao chép, viết lại, quét là vi phạm trực tiếp.","vi":{"q":"Vi phạm bản quyền thứ cấp (secondary infringement) là:","o":["Sao chép tài liệu mà không được phép.","Kinh doanh, buôn bán các bản sao bất hợp pháp đó","Viết lại tài liệu mà không được phép.","Quét (scan) tài liệu mà không được phép."]}},
{"id":"ipr-52","q":"Primary copyright infringement is:","o":["Trading of those illegal copies","Copying the material without permission.","Rewriting the material with permission.","Both of A&C"],"a":[1],"m":"ipr","c":3,"n":52,"f":1,"e":"Vi phạm trực tiếp (primary) là hành vi sao chép tài liệu mà không được phép. Kinh doanh bản sao là thứ cấp.","vi":{"q":"Vi phạm bản quyền trực tiếp (primary infringement) là:","o":["Kinh doanh, buôn bán các bản sao bất hợp pháp","Sao chép tài liệu mà không được phép.","Viết lại tài liệu khi có sự cho phép.","Cả A và C"]}},
{"id":"ipr-53","q":"A technical drawing is prepared for use in manufacturing a television set, the drawing is protected by:","o":["Design right","Copyright","Registered design","Both of B&C"],"a":[3],"m":"ipr","c":1,"n":53,"f":1,"e":"Bản vẽ kỹ thuật là tác phẩm đồ họa được bảo hộ bản quyền; theo đáp án của đề còn được bảo hộ kiểu dáng đã đăng ký. Xem cảnh báo bên dưới về mâu thuẫn với câu #110.","vi":{"q":"Một bản vẽ kỹ thuật được lập để dùng cho việc sản xuất một chiếc ti vi. Bản vẽ này được bảo hộ bởi:","o":["Quyền kiểu dáng (design right)","Bản quyền","Kiểu dáng đã đăng ký","Cả B và C"]},"k":"Câu #110 (bản vẽ kỹ thuật được bảo hộ bởi...) lại chọn chỉ «bản quyền». Hai câu của đề không thống nhất."},
{"id":"ipr-54","q":"Regarding to Registration period for a registered design. Which of the following is WRONG?","o":["The initial registration period for a design last for 5 years from the application date.","The registration can be kept in force for four subsequent periods of 5 years (after the initial registration period), automatically, without fees.","The registration can be kept in force for four subsequent periods of 5 years, (after the initial registration period), if renewal fees are paid.","The registration period for a design last for 5 years only from the application date. After that period, the registration will not be extended if the owner does not pay the renewal fees"],"a":[1],"m":"ipr","c":6,"n":54,"e":"Gia hạn kiểu dáng đã đăng ký phải nộp phí, không tự động miễn phí; nên phát biểu «tự động, không mất phí» là sai.","vi":{"q":"Về thời hạn đăng ký kiểu dáng đã đăng ký, phát biểu nào sau đây SAI?","o":["Thời hạn đăng ký ban đầu của một kiểu dáng là 5 năm kể từ ngày nộp đơn.","Việc đăng ký có thể được duy trì hiệu lực thêm bốn kỳ tiếp theo, mỗi kỳ 5 năm (sau kỳ đăng ký ban đầu), một cách tự động, không mất phí.","Việc đăng ký có thể được duy trì hiệu lực thêm bốn kỳ tiếp theo, mỗi kỳ 5 năm (sau kỳ đăng ký ban đầu), nếu nộp phí gia hạn.","Thời hạn đăng ký kiểu dáng chỉ là 5 năm kể từ ngày nộp đơn. Sau thời gian đó, đăng ký sẽ không được gia hạn nếu chủ sở hữu không nộp phí gia hạn"]},"k":"Lưu ý: phương án {D} tự mâu thuẫn với {A}–{C} (nói «chỉ 5 năm» rồi lại nói gia hạn bằng phí). Đề chọn {B} vì «gia hạn tự động không mất phí» là sai rõ nhất."},
{"id":"ipr-55","q":"Which of the followings is protected by copyright","o":["A word","An idea","A legal document","An express of an idea"],"a":[3],"m":"ipr","c":2,"n":55,"e":"Bản quyền bảo hộ sự thể hiện (expression) của ý tưởng. Từ đơn lẻ và ý tưởng không được bảo hộ.","vi":{"q":"Điều nào sau đây được bảo hộ bản quyền?","o":["Một từ","Một ý tưởng","Một văn bản pháp lý","Sự thể hiện (expression) của một ý tưởng"]}},
{"id":"ipr-56","q":"Referring to a trade mark in news is.......","o":["A primary infringement of trade mark","A secondary infringement of trade mark","Not an infringement of trade mark","An infringement of copyright"],"a":[2],"m":"ipr","c":5,"n":56,"e":"Nhắc đến nhãn hiệu trong tin tức không phải sử dụng nhãn hiệu trong thương mại nên không xâm phạm.","vi":{"q":"Việc nhắc đến một nhãn hiệu trong tin tức là.......","o":["Vi phạm trực tiếp nhãn hiệu","Vi phạm thứ cấp nhãn hiệu","Không phải hành vi xâm phạm nhãn hiệu","Xâm phạm bản quyền"]}},
{"id":"ipr-57","q":"For the purpose of showing damage in a passing-off action, the owner must........","o":["Show actual loss","Demonstrate high risk of loss of business arising from the confusion","Calculate the number of clients before and after passing off occurs","Proving the activity of imitation"],"a":[1],"m":"ipr","c":5,"n":57,"e":"Để chứng minh thiệt hại trong passing off, chủ sở hữu chỉ cần chứng minh nguy cơ cao bị mất khách/kinh doanh do sự nhầm lẫn, không cần chứng minh tổn thất thực tế.","vi":{"q":"Để chứng minh thiệt hại trong vụ kiện passing off, chủ sở hữu phải........","o":["Chứng minh tổn thất thực tế","Chứng minh nguy cơ cao bị mất khách hàng do sự nhầm lẫn gây ra","Tính số lượng khách hàng trước và sau khi xảy ra passing off","Chứng minh hành vi bắt chước"]}},
{"id":"ipr-58","q":"Which of the following statements is true?","o":["Fair dealing means that only insubstantial part of a work may be used","Fair dealing with a work is permitted","Quoting from a work in criticism or review is permitted provided that the critic or review is fair","Developing a single part of a work is fair"],"a":[2],"m":"ipr","c":3,"n":58,"e":"Trích dẫn để phê bình, đánh giá là được phép nếu hợp lý. Fair dealing không bị giới hạn ở mức «không đáng kể» và không phải mọi cách dùng đều được phép.","vi":{"q":"Phát biểu nào sau đây đúng?","o":["Sử dụng hợp lý (fair dealing) nghĩa là chỉ được dùng một phần không đáng kể của tác phẩm","Việc sử dụng hợp lý một tác phẩm là được phép","Trích dẫn tác phẩm để phê bình hoặc đánh giá được phép, miễn là việc phê bình hoặc đánh giá đó hợp lý","Phát triển một phần duy nhất của tác phẩm là hợp lý"]}},
{"id":"ipr-59","q":"In case of copyright infringement, the copyright holder can use","o":["Only injunction","Only delivery-up","Only compensatory damages","Each of (a), (b), (c) or combination"],"a":[3],"m":"ipr","c":3,"n":59,"e":"Chủ sở hữu có thể dùng từng biện pháp (lệnh cấm, giao nộp hàng vi phạm, bồi thường) hoặc kết hợp chúng.","vi":{"q":"Trong trường hợp vi phạm bản quyền, chủ sở hữu bản quyền có thể sử dụng","o":["Chỉ lệnh cấm","Chỉ giao nộp hàng vi phạm","Chỉ bồi thường thiệt hại bù đắp","Từng biện pháp (a), (b), (c) hoặc kết hợp"]}},
{"id":"ipr-60","q":"What is sole license?","o":["the licensee will have no competition","the licensor will afford no licenses to other persons within the contractual territory","A and B are correct","A and B are incorrect"],"a":[1],"m":"ipr","c":1,"n":60,"f":1,"e":"Sole license: bên cấp phép không cấp phép cho người khác trong lãnh thổ nhưng vẫn có thể tự khai thác. Exclusive license mới là bên nhận không có đối thủ, kể cả bên cấp phép.","vi":{"q":"Giấy phép độc quyền riêng (sole license) là gì?","o":["bên được cấp phép sẽ không có đối thủ cạnh tranh","bên cấp phép sẽ không cấp phép cho bất kỳ người nào khác trong lãnh thổ theo hợp đồng","A và B đều đúng","A và B đều sai"]}},
{"id":"ipr-61","q":"Which of the following is NOT a copyright infringement?","o":["Someone copies without the copyright owner's permission","A photographer takes a photograph of a particular scenic view, even though the photograph is virtually indistinguishable to another person's photograph.","Someone creates a scene in a studio to reproduce a scene in someone else's photograph","One similarity drawing has had access to the material which has supposedly been copied"],"a":[1],"m":"ipr","c":3,"n":61,"e":"Hai nhiếp ảnh gia tự chụp độc lập cùng khung cảnh không phải sao chép nên không vi phạm. Các phương án còn lại là sao chép hoặc dựng lại.","vi":{"q":"Điều nào sau đây KHÔNG phải là vi phạm bản quyền?","o":["Ai đó sao chép mà không có sự cho phép của chủ sở hữu bản quyền","Một nhiếp ảnh gia chụp một khung cảnh thiên nhiên nhất định, dù bức ảnh gần như không thể phân biệt với ảnh của người khác.","Ai đó dựng lại một cảnh trong studio để tái tạo cảnh trong bức ảnh của người khác","Một bản vẽ tương tự đã tiếp cận được tài liệu được cho là đã bị sao chép"]}},
{"id":"ipr-62","q":"In the EU, marks registered by the Office for Harmonisation of the Internal Market (Trade Marks and Designs) and are called.....","o":["Community Trade Marks","Global Trade Marks","European Trade Marks","All are correct"],"a":[0],"m":"ipr","c":4,"n":62,"f":1,"e":"Nhãn hiệu đăng ký ở cơ quan EUIPO (trước là OHIM) gọi là Nhãn hiệu Cộng đồng (Community Trade Mark), nay là nhãn hiệu EU.","vi":{"q":"Ở EU, các nhãn hiệu đăng ký tại Cơ quan Hài hòa hóa Thị trường Nội khối (Nhãn hiệu và Kiểu dáng) được gọi là.....","o":["Nhãn hiệu Cộng đồng (Community Trade Marks)","Nhãn hiệu Toàn cầu","Nhãn hiệu Châu Âu","Tất cả đều đúng"]}},
{"id":"ipr-63","q":"Adding some words in a song without consent of author is an infringement of......","o":["Reproduction right","Public performance right","Integrity right (quyền bảo toàn toàn ven sản phẩm)","False attribution"],"a":[2],"m":"ipr","c":2,"n":63,"e":"Thêm lời vào bài hát làm thay đổi tác phẩm gốc, vi phạm quyền toàn vẹn (integrity right) thuộc quyền nhân thân.","vi":{"q":"Thêm một số từ vào bài hát mà không có sự đồng ý của tác giả là xâm phạm ......","o":["Quyền sao chép","Quyền biểu diễn trước công chúng","Quyền toàn vẹn tác phẩm (integrity right)","Việc gán sai tác giả (false attribution)"]}},
{"id":"ipr-64","q":"If the technical drawings of motorbike are copied, there is infringement of:","o":["Registered design","Design right","Copyright.","Both of A&B"],"a":[3],"m":"ipr","c":6,"n":64,"f":1,"e":"Theo đáp án của đề, sao chép bản vẽ kỹ thuật xâm phạm cả kiểu dáng đã đăng ký và quyền kiểu dáng. Xem cảnh báo bên dưới.","vi":{"q":"Nếu các bản vẽ kỹ thuật của một chiếc xe máy bị sao chép thì có hành vi xâm phạm:","o":["Kiểu dáng đã đăng ký","Quyền kiểu dáng (design right)","Bản quyền.","Cả A và B"]},"k":"Sao chép bản vẽ kỹ thuật thông thường là xâm phạm bản quyền (phương án {C}) và có thể cả quyền kiểu dáng; đề chọn {D}."},
{"id":"ipr-65","q":"Which of these rights is not generally regarded as part of design law?","o":["Registered designs","Design right","Trade mark right","Both registered designs and design right"],"a":[2],"m":"ipr","c":6,"n":65,"e":"Luật kiểu dáng gồm kiểu dáng đã đăng ký và quyền kiểu dáng; nhãn hiệu là chế độ khác.","vi":{"q":"Quyền nào sau đây thường không được coi là một phần của luật kiểu dáng?","o":["Kiểu dáng đã đăng ký","Quyền kiểu dáng (design right)","Quyền nhãn hiệu","Cả kiểu dáng đã đăng ký và quyền kiểu dáng"]}},
{"id":"ipr-66","q":"Which of the following actions may constitute an infringement?","o":["Using the descriptive sign of the goods in accordance with honest practice","Using a well-known trade mark in the course of a business","Using the geographical indications of the goods in accordance with honest practice","Using his own registered trademark"],"a":[1],"m":"ipr","c":5,"n":66,"e":"Dùng dấu hiệu mô tả, chỉ dẫn địa lý đúng thông lệ hay nhãn hiệu của chính mình là hợp pháp. Dùng nhãn hiệu nổi tiếng của người khác trong kinh doanh có thể xâm phạm.","vi":{"q":"Hành vi nào sau đây có thể cấu thành hành vi xâm phạm?","o":["Sử dụng dấu hiệu mô tả hàng hóa phù hợp với thông lệ trung thực","Sử dụng nhãn hiệu nổi tiếng trong hoạt động kinh doanh","Sử dụng chỉ dẫn địa lý của hàng hóa phù hợp với thông lệ trung thực","Sử dụng nhãn hiệu đã đăng ký của chính mình"]}},
{"id":"ipr-67","q":"In a dispute on design right, .........","o":["Alleged copyist must prove not copying.","The owner must prove copying","The Government must prove copying","Nobody is in charged of proving copying"],"a":[1],"m":"ipr","c":6,"n":67,"e":"Với quyền kiểu dáng (không đăng ký), chủ sở hữu phải chứng minh có sao chép.","vi":{"q":"Trong tranh chấp về quyền kiểu dáng (design right), .........","o":["Người bị cáo buộc sao chép phải chứng minh mình không sao chép.","Chủ sở hữu phải chứng minh có sự sao chép","Chính phủ phải chứng minh có sự sao chép","Không ai có trách nhiệm chứng minh sự sao chép"]}},
{"id":"ipr-68","q":"A false attribution as an author.....","o":["Is made if a reasonable reader of the work would think that claimant was the author","Is made where particular words are attributed to the claimant without consent","Is made if the name of author is not mentioned","Is made if the work is re-written"],"a":[0],"m":"ipr","c":2,"n":68,"e":"Gán sai tác giả xảy ra nếu một người đọc hợp lý sẽ nghĩ người khiếu nại là tác giả của tác phẩm.","vi":{"q":"Việc gán sai tác giả (false attribution as an author).....","o":["Xảy ra nếu một người đọc hợp lý của tác phẩm sẽ nghĩ rằng người khiếu nại là tác giả","Xảy ra khi những lời nói cụ thể bị gán cho người khiếu nại mà không có sự đồng ý","Xảy ra nếu không nêu tên tác giả","Xảy ra nếu tác phẩm bị viết lại"]}},
{"id":"ipr-69","q":"The article made by Company X does not exactly the same with the article owned by Company Y but this article is only slightly different from Y's article. Which of the following is RIGHT?","o":["The article made by X is already different slightly from Y's article. It is not an infringement of design right.","It is an infringement of design right. Y, as the owner, will prevent X from copying the design.","X does not have to obtain Y's permission before making the article","X does not have to compensate for Y's design right."],"a":[1],"m":"ipr","c":6,"n":69,"e":"Chỉ khác đôi chút không làm hết xâm phạm: hành vi sao chép thiết kế vẫn bị coi là xâm phạm quyền kiểu dáng.","vi":{"q":"Sản phẩm do Công ty X làm ra không giống hệt sản phẩm thuộc sở hữu của Công ty Y, mà chỉ hơi khác so với sản phẩm của Y. Phát biểu nào sau đây ĐÚNG?","o":["Sản phẩm của X đã khác một chút so với sản phẩm của Y. Đây không phải là xâm phạm quyền kiểu dáng.","Đây là hành vi xâm phạm quyền kiểu dáng. Y, với tư cách chủ sở hữu, sẽ ngăn X sao chép thiết kế.","X không cần xin phép Y trước khi làm sản phẩm đó","X không phải bồi thường về quyền kiểu dáng của Y."]}},
{"id":"ipr-70","q":"A writer has written a detective novel based on using a murder case's transcripts from court proceedings without the Court's consent. The Court is the publisher of the transcripts. Which of the following is RIGHT?","o":["The transcripts from court proceedings are protected by Copyright.","The writer has to compensate for the Court's copyright","Transcripts from court proceedings are in the public domain","The writer has infringed the Court's Copyright"],"a":[2],"m":"ipr","c":2,"n":70,"e":"Theo đáp án của đề, biên bản phiên tòa thuộc phạm vi công cộng nên nhà văn được dùng, không xâm phạm.","vi":{"q":"Một nhà văn viết tiểu thuyết trinh thám dựa trên biên bản các phiên tòa của một vụ án giết người mà không được Tòa án đồng ý. Tòa án là nhà xuất bản các biên bản đó. Phát biểu nào sau đây ĐÚNG?","o":["Biên bản các phiên tòa được bảo hộ bản quyền.","Nhà văn phải bồi thường về bản quyền của Tòa án","Biên bản các phiên tòa thuộc phạm vi công cộng (public domain)","Nhà văn đã xâm phạm bản quyền của Tòa án"]}},
{"id":"ipr-71","q":"To be protected, unregistered trade mark must........","o":["Have reputation","Be distinctive for the goods or services for which it has been used","Both be distinctive and have reputation","Be distinctive but do not have reputation"],"a":[2],"m":"ipr","c":5,"n":71,"e":"Nhãn hiệu chưa đăng ký chỉ được bảo hộ (qua passing off) khi vừa có tính phân biệt vừa có uy tín trên thị trường.","vi":{"q":"Để được bảo hộ, nhãn hiệu chưa đăng ký phải........","o":["Có uy tín (reputation)","Có tính phân biệt đối với hàng hóa hoặc dịch vụ mà nó đã được sử dụng","Vừa có tính phân biệt vừa có uy tín","Có tính phân biệt nhưng không cần có uy tín"]}},
{"id":"ipr-72","q":"A wooden chair is protected by registered design. After seeing this chair, a chocolate shop makes a chocolate bar with the design of this chair. Such act is.....","o":["A secondary infringement of registered design","A primary infringement of registered design","Not an infringement of registered design","An infringement of patent"],"a":[1],"m":"ipr","c":6,"n":72,"e":"Làm sản phẩm có hình dáng của kiểu dáng đã đăng ký (kể cả khác loại hàng) là vi phạm trực tiếp; kiểu dáng đã đăng ký bảo hộ hình dáng cho mọi sản phẩm.","vi":{"q":"Một chiếc ghế gỗ được bảo hộ bằng kiểu dáng đã đăng ký. Sau khi thấy chiếc ghế này, một cửa hàng sô-cô-la làm thanh sô-cô-la có hình dáng của chiếc ghế đó. Hành vi này là.....","o":["Vi phạm thứ cấp kiểu dáng đã đăng ký","Vi phạm trực tiếp kiểu dáng đã đăng ký","Không phải xâm phạm kiểu dáng đã đăng ký","Xâm phạm sáng chế"]}},
{"id":"ipr-73","q":"Anders is the copyright owner of Computer programs. Without Anders' permission, Tine has authorised Charlotte, the one working under contract with Tine, to make an copy of Anders' Computer programs with something added. The act of Tine is:","o":["A secondary infringement of Anders' Copyrights","A primary infringement of Anders' Copyrights","Not a copyright infringement","Both A&B"],"a":[0],"m":"ipr","c":3,"n":73,"f":1,"e":"Tine chỉ ủy quyền cho người khác sao chép (không tự tay sao chép) nên vi phạm thứ cấp (authorising infringement).","vi":{"q":"Anders là chủ sở hữu bản quyền chương trình máy tính. Không có sự cho phép của Anders, Tine đã ủy quyền cho Charlotte, người làm việc theo hợp đồng với Tine, sao chép chương trình máy tính của Anders và có bổ sung thêm một số nội dung. Hành vi của Tine là:","o":["Vi phạm thứ cấp bản quyền của Anders","Vi phạm trực tiếp bản quyền của Anders","Không phải vi phạm bản quyền","Cả A và B"]}},
{"id":"ipr-74","q":"Fair dealing means........","o":["Exception to IP rights infringement","Exception to copyright infringement","Exception to trademark infringement","Exception to patent infringement"],"a":[1],"m":"ipr","c":3,"n":74,"e":"Fair dealing là ngoại lệ đối với hành vi xâm phạm bản quyền.","vi":{"q":"Sử dụng hợp lý (fair dealing) có nghĩa là........","o":["Ngoại lệ đối với hành vi xâm phạm quyền sở hữu trí tuệ","Ngoại lệ đối với hành vi xâm phạm bản quyền","Ngoại lệ đối với hành vi xâm phạm nhãn hiệu","Ngoại lệ đối với hành vi xâm phạm sáng chế"]}},
{"id":"ipr-75","q":"Which of following is NOT passing-off?","o":["Selling used item as a new one","Copying an existing business names","Persuading clients of a well-known shop to try other goods or services","Using similar decoration of an existing business names"],"a":[2],"m":"ipr","c":5,"n":75,"e":"Thuyết phục khách của cửa hàng nổi tiếng thử hàng khác chỉ là cạnh tranh, không có sự trình bày sai nên không phải passing off.","vi":{"q":"Hành vi nào sau đây KHÔNG phải là passing off?","o":["Bán hàng đã qua sử dụng như hàng mới","Sao chép tên doanh nghiệp đang có","Thuyết phục khách hàng của một cửa hàng nổi tiếng dùng thử hàng hóa hoặc dịch vụ khác","Sử dụng cách trang trí tương tự tên doanh nghiệp đang có"]}},
{"id":"ipr-76","q":"The Fair use of copyrighted work is:","o":["The permission of copyright owner to others to use freely copyrighted material for certain uses.","The statutory permission granted expressly by the Copyright Act to the public to use copyrighted material for certain uses.","Both A&B","Not A&B"],"a":[1],"m":"ipr","c":3,"n":76,"f":1,"e":"Fair use là sự cho phép theo luật do Luật Bản quyền trao cho công chúng, không phải do chủ sở hữu tự cho.","vi":{"q":"Sử dụng hợp lý (fair use) tác phẩm có bản quyền là:","o":["Sự cho phép của chủ sở hữu bản quyền để người khác được tự do sử dụng tài liệu có bản quyền cho một số mục đích.","Sự cho phép theo luật do Luật Bản quyền trực tiếp trao cho công chúng để sử dụng tài liệu có bản quyền cho một số mục đích.","Cả A và B","Không phải A và B"]}},
{"id":"ipr-77","q":"Liability for infringement of copyright can be avoided if...","o":["It is taken negligently","It is taken intentionally","It is used for commercial purpose","It is used for educational purpose"],"a":[3],"m":"ipr","c":3,"n":77,"e":"Dùng cho mục đích giáo dục là một ngoại lệ (fair dealing) có thể tránh trách nhiệm; cẩu thả, cố ý hay thương mại thì không.","vi":{"q":"Có thể tránh trách nhiệm về hành vi xâm phạm bản quyền nếu...","o":["Hành vi được thực hiện do cẩu thả","Hành vi được thực hiện một cách cố ý","Được dùng cho mục đích thương mại","Được dùng cho mục đích giáo dục"]}},
{"id":"ipr-78","q":"If a famous signer sets up her own company to sell her own range of clothes, what type of intellectual property right can she use to show that the clothes are made by her company?","o":["Copyright","Trademarks","Registered designs","Patents"],"a":[1],"m":"ipr","c":4,"n":78,"e":"Nhãn hiệu cho biết hàng hóa do công ty của cô ca sĩ tạo ra (nguồn gốc thương mại).","vi":{"q":"Nếu một ca sĩ nổi tiếng lập công ty riêng để bán dòng quần áo của mình, cô ấy có thể dùng loại quyền sở hữu trí tuệ nào để thể hiện quần áo là do công ty của cô ấy làm ra?","o":["Bản quyền","Nhãn hiệu","Kiểu dáng đã đăng ký","Sáng chế"]}},
{"id":"ipr-79","q":"When: The mark could have been registered but the owner decided not to register it, and The mark is unregistrable because it does not meet the requirements of the law i.e Trade Marks Act 1994). In both cases, use of the mark generates what is known as","o":["Good hope","Goodwill","Good faith","Good use"],"a":[1],"m":"ipr","c":5,"n":79,"e":"Việc sử dụng nhãn hiệu (dù đăng ký được hay không) tạo ra uy tín thương mại (goodwill), nền tảng của passing off.","vi":{"q":"Khi: nhãn hiệu có thể đã được đăng ký nhưng chủ sở hữu quyết định không đăng ký, và nhãn hiệu không đăng ký được vì không đáp ứng yêu cầu của luật (ví dụ Đạo luật Nhãn hiệu 1994). Trong cả hai trường hợp, việc sử dụng nhãn hiệu tạo ra cái gọi là","o":["Good hope (niềm hy vọng tốt)","Goodwill (uy tín thương mại)","Good faith (thiện chí)","Good use (việc sử dụng tốt)"]}},
{"id":"ipr-80","q":"What can be deemed as an infringement of registered trade mark?","o":["Use the registered trade mark in relation to the goods/services specified in the registration;","Use the registered trade mark on the similar goods/services;","Use the similar mark on the registered or similar goods/services, so that the public is likely to be confused;","All are correct;"],"a":[3],"m":"ipr","c":5,"n":80,"f":1,"e":"Xâm phạm nhãn hiệu đã đăng ký gồm dùng cho hàng hóa đã đăng ký, hàng hóa tương tự, hoặc dùng dấu hiệu tương tự gây nhầm lẫn; nên chọn «tất cả».","vi":{"q":"Điều gì có thể bị coi là xâm phạm nhãn hiệu đã đăng ký?","o":["Sử dụng nhãn hiệu đã đăng ký cho hàng hóa/dịch vụ được nêu trong đăng ký;","Sử dụng nhãn hiệu đã đăng ký cho hàng hóa/dịch vụ tương tự;","Sử dụng nhãn hiệu tương tự cho hàng hóa/dịch vụ đã đăng ký hoặc tương tự, khiến công chúng có khả năng bị nhầm lẫn;","Tất cả đều đúng;"]}},
{"id":"ipr-81","q":"How do you think about this statement: In the UK, a mark can be used in business course without registration?","o":["This is correct. In the UK, a mark can be used without registering although it is recommended that registration is always needed for enjoying protection.","This is not correct. Once being used, a trade mark has already been registered.","This is not correct. Trade mark must be registered before using in the course of trade","None of the statements are correct."],"a":[0],"m":"ipr","c":4,"n":81,"f":1,"e":"Ở Anh, nhãn hiệu có thể được dùng mà không đăng ký, nhưng nên đăng ký để được bảo hộ đầy đủ.","vi":{"q":"Bạn nghĩ gì về nhận định sau: Ở Anh, một nhãn hiệu có thể được sử dụng trong hoạt động kinh doanh mà không cần đăng ký?","o":["Đúng. Ở Anh, nhãn hiệu có thể được sử dụng mà không cần đăng ký, dù nên luôn đăng ký để được hưởng bảo hộ.","Không đúng. Một khi đã được sử dụng thì nhãn hiệu coi như đã được đăng ký.","Không đúng. Nhãn hiệu phải được đăng ký trước khi sử dụng trong hoạt động thương mại","Không nhận định nào đúng."]}},
{"id":"ipr-82","q":"When is the best time to minimize the risk of being sued for infringement of a registered trade mark, for passing-off or even misuse of someone else's company name?","o":["a trade mark is selected in the last place.","a trade mark is selected in the first place.","a trade mark is newly created","a trade mark is communicated to the public"],"a":[1],"m":"ipr","c":5,"n":82,"e":"Thời điểm tốt nhất để tránh rủi ro kiện tụng là khi chọn nhãn hiệu ngay từ đầu (kiểm tra tra cứu trước).","vi":{"q":"Khi nào là thời điểm tốt nhất để giảm thiểu rủi ro bị kiện vì xâm phạm nhãn hiệu đã đăng ký, vì passing off, hay thậm chí vì lạm dụng tên công ty của người khác?","o":["khi nhãn hiệu được chọn sau cùng.","khi nhãn hiệu được chọn ngay từ đầu.","khi nhãn hiệu mới được tạo ra","khi nhãn hiệu được công bố cho công chúng"]}},
{"id":"ipr-83","q":"Which of the followings is secondary infringement of copyright?","o":["Possession of or dealings with infringing copies","Performing the work in public","Duplicating the work","Selling a work"],"a":[0],"m":"ipr","c":3,"n":83,"e":"Sở hữu hoặc kinh doanh bản sao vi phạm là vi phạm thứ cấp. Biểu diễn, sao chép, bán tác phẩm vi phạm trực tiếp.","vi":{"q":"Hành vi nào sau đây là vi phạm bản quyền thứ cấp (secondary infringement)?","o":["Sở hữu hoặc kinh doanh các bản sao vi phạm","Biểu diễn tác phẩm trước công chúng","Sao chép tác phẩm","Bán một tác phẩm"]}},
{"id":"ipr-84","q":"According to Madrid Agreement, the single application of trade mark must be made within how many months from the initial trade mark application?","o":["6","12","18","3"],"a":[0],"m":"ipr","c":4,"n":84,"e":"Theo thỏa ước Madrid, thời hạn ưu tiên để nộp đơn quốc tế là 6 tháng kể từ ngày nộp đơn nhãn hiệu đầu tiên.","vi":{"q":"Theo Thỏa ước Madrid, đơn đăng ký nhãn hiệu quốc tế duy nhất phải được nộp trong bao nhiêu tháng kể từ ngày nộp đơn nhãn hiệu đầu tiên?","o":["6","12","18","3"]}},
{"id":"ipr-85","q":"Computer programs can be protected by.........","o":["Design rights","Copyright","Trademark","Patent"],"a":[1],"m":"ipr","c":2,"n":85,"e":"Chương trình máy tính được bảo hộ bản quyền như tác phẩm văn học.","vi":{"q":"Chương trình máy tính có thể được bảo hộ bởi.........","o":["Quyền kiểu dáng","Bản quyền","Nhãn hiệu","Sáng chế"]}},
{"id":"ipr-86","q":"Which of the following is not a law governing intellectual property perspective?","o":["Copyright Act, 1957","Trademark Act, 1999","Patent Act, 1970","Design Act, 2000","Customs Act, 1962"],"a":[4],"m":"ipr","c":1,"n":86,"e":"Luật Hải quan 1962 (Customs Act) không phải luật sở hữu trí tuệ; các luật còn lại là luật bản quyền, nhãn hiệu, sáng chế, kiểu dáng.","vi":{"q":"Văn bản nào sau đây KHÔNG phải là luật điều chỉnh về sở hữu trí tuệ?","o":["Luật Bản quyền 1957","Luật Nhãn hiệu 1999","Luật Sáng chế 1970","Luật Kiểu dáng 2000","Luật Hải quan 1962"]}},
{"id":"ipr-87","q":"Which of the followings can NOT be a registrable trademark?","o":["A symbol","A smell","A single colour","A generic name of the goods"],"a":[3],"m":"ipr","c":4,"n":87,"e":"Tên gọi chung của hàng hóa (generic name) không có tính phân biệt nên không đăng ký được; biểu tượng, mùi, màu đơn có thể đăng ký nếu có tính phân biệt.","vi":{"q":"Điều nào sau đây KHÔNG thể là nhãn hiệu đăng ký được?","o":["Một biểu tượng","Một mùi","Một màu sắc đơn lẻ","Tên gọi chung (generic name) của hàng hóa"]}},
{"id":"ipr-88","q":"Who is not an author of the artistic work?","o":["A person who solely creates the artistic work","A person who fixes the picture on whatever medium.","A person who jointly provide significant contribution to create a copyrightable artistic work.","A person who merely provides ideas."],"a":[3],"m":"ipr","c":2,"n":88,"e":"Người chỉ đưa ra ý tưởng không phải tác giả vì ý tưởng không được bảo hộ; tác giả là người thể hiện hoặc đóng góp đáng kể.","vi":{"q":"Ai KHÔNG phải là tác giả của tác phẩm nghệ thuật?","o":["Người một mình tạo ra tác phẩm nghệ thuật","Người cố định (thể hiện) bức tranh lên bất kỳ phương tiện nào.","Người cùng đóng góp đáng kể để tạo ra tác phẩm nghệ thuật có thể được bảo hộ bản quyền.","Người chỉ đơn thuần đưa ra ý tưởng."]}},
{"id":"ipr-89","q":"Regarding applying for registration of a design in the UK, which of the following is RIGHT?","o":["Applying for registration of a design in the UK is free of charge","The application can be dealt with by a patent attorney who will be familiar with the formalities required","An examiner (at the UK Designs Registry) will check whether the design is new.","All of the above"],"a":[1],"m":"ipr","c":6,"n":89,"f":1,"e":"Đơn đăng ký kiểu dáng có thể do luật sư sáng chế (patent attorney) xử lý. Đăng ký không miễn phí và cơ quan chỉ xét hình thức, không kiểm tra tính mới.","vi":{"q":"Về việc đăng ký kiểu dáng ở Anh, phát biểu nào sau đây ĐÚNG?","o":["Đăng ký kiểu dáng ở Anh là miễn phí","Đơn có thể do một luật sư sáng chế (patent attorney) xử lý, người này quen thuộc với các thủ tục cần thiết","Một thẩm định viên (tại Cơ quan Đăng ký Kiểu dáng của Anh) sẽ kiểm tra xem kiểu dáng có mới hay không.","Tất cả các đáp án trên"]}},
{"id":"ipr-90","q":"The concept of design right was introduced into the UK in:","o":["The UK Trade Marks Act 1994","The UK Patents Act 1977","The UK Copyright, Designs and Patents Act 1988","None of the above"],"a":[2],"m":"ipr","c":6,"n":90,"f":1,"e":"Quyền kiểu dáng được đưa vào Anh bằng Đạo luật Bản quyền, Kiểu dáng và Sáng chế (CDPA) 1988.","vi":{"q":"Khái niệm quyền kiểu dáng (design right) được đưa vào Anh bằng:","o":["Đạo luật Nhãn hiệu Anh 1994","Đạo luật Sáng chế Anh 1977","Đạo luật Bản quyền, Kiểu dáng và Sáng chế Anh 1988","Không đáp án nào đúng"]}},
{"id":"ipr-91","q":"Registered design does not protect:","o":["A design on parts which are assembled into a complex product","A design on the whole or a part of a product","A design on handicraft item","A design on products such as vehicle spare parts which are not seen in normal use"],"a":[3],"m":"ipr","c":6,"n":91,"e":"Kiểu dáng đã đăng ký không bảo hộ các bộ phận không nhìn thấy trong sử dụng bình thường, ví dụ phụ tùng bên trong của xe.","vi":{"q":"Kiểu dáng đã đăng ký không bảo hộ:","o":["Một thiết kế trên các bộ phận được lắp ráp thành một sản phẩm phức hợp","Một thiết kế trên toàn bộ hoặc một phần của sản phẩm","Một thiết kế trên sản phẩm thủ công mỹ nghệ","Một thiết kế trên các sản phẩm như phụ tùng xe cộ mà không nhìn thấy được khi sử dụng bình thường"]}},
{"id":"ipr-92","q":"A is a movie-star. B takes a photograph of A and sells it to a magazine. C","o":["B infringes on A's copyright","B infringes A's privacy right","B does not infringe any IP right","B infringes A's trademark"],"a":[1],"m":"ipr","c":2,"n":92,"e":"Chụp ảnh người khác và bán là xâm phạm quyền riêng tư (privacy right) của người đó chứ không phải bản quyền hay nhãn hiệu của họ.","vi":{"q":"A là một ngôi sao điện ảnh. B chụp ảnh A và bán cho một tạp chí. C (đề gốc bị cắt cụt ở đây)","o":["B xâm phạm bản quyền của A","B xâm phạm quyền riêng tư của A","B không xâm phạm bất kỳ quyền sở hữu trí tuệ nào","B xâm phạm nhãn hiệu của A"]}},
{"id":"ipr-93","q":"Which of followings can NOT be patented?","o":["Discovery of scientific theory","New methodology of running a technique system","New way of operating an equipment","New application of scientific theory"],"a":[0],"m":"ipr","c":6,"n":93,"e":"Phát hiện lý thuyết khoa học không được cấp bằng sáng chế; phương pháp, cách vận hành, vật liệu và ứng dụng mới thì có thể.","vi":{"q":"Điều nào sau đây KHÔNG thể được cấp bằng sáng chế?","o":["Phát hiện một lý thuyết khoa học","Phương pháp mới để vận hành một hệ thống kỹ thuật","Cách thức mới để vận hành một thiết bị","Ứng dụng mới của một lý thuyết khoa học"]}},
{"id":"ipr-94","q":"In the UK law, what the owner of a trade mark must show while proving the damage?","o":["actual loss of business","loss of orders to the competitor","a high risk of loss of business arising from the confusion","the market loss"],"a":[2],"m":"ipr","c":5,"n":94,"e":"Chủ nhãn hiệu chỉ cần chứng minh nguy cơ cao bị mất hoạt động kinh doanh do nhầm lẫn, không phải tổn thất thực tế đã xảy ra.","vi":{"q":"Theo luật Anh, chủ sở hữu nhãn hiệu phải chứng minh điều gì khi chứng minh thiệt hại?","o":["tổn thất thực tế về hoạt động kinh doanh","mất đơn hàng vào tay đối thủ","nguy cơ cao bị mất hoạt động kinh doanh do sự nhầm lẫn gây ra","tổn thất thị trường"]}},
{"id":"ipr-95","q":"To be protected by registered design, the owner must.....","o":["Prove copying","Show the designs are the same or very similar","Publish the design one year earlier","Show an application of the design"],"a":[1],"m":"ipr","c":6,"n":95,"e":"Với kiểu dáng đã đăng ký, chủ sở hữu chỉ cần chứng minh thiết kế bị kiện giống hoặc rất giống thiết kế của mình; không cần chứng minh sao chép.","vi":{"q":"Để được bảo hộ bằng kiểu dáng đã đăng ký, chủ sở hữu phải.....","o":["Chứng minh có sự sao chép","Chứng minh các thiết kế giống nhau hoặc rất giống nhau","Công bố thiết kế sớm hơn một năm","Chứng minh có việc áp dụng thiết kế"]}},
{"id":"ipr-96","q":"In a case on Registered design dispute, if the defendant (the suspected infringer) can prove that the design was created independently by himself/herself, then:","o":["There is not infringement","There is an infringement","There is an infringement only when the owner shows that there has been copying.","All of others are correct"],"a":[2],"m":"ipr","c":6,"n":96,"f":1,"e":"Theo đáp án của đề, nếu bị đơn chứng minh được sáng tạo độc lập thì chỉ có xâm phạm khi chủ sở hữu chứng minh được có sao chép.","vi":{"q":"Trong vụ tranh chấp kiểu dáng đã đăng ký, nếu bị đơn (người bị nghi vi phạm) chứng minh được thiết kế do mình tự sáng tạo độc lập thì:","o":["Không có hành vi xâm phạm","Có hành vi xâm phạm","Chỉ có hành vi xâm phạm khi chủ sở hữu chứng minh được có sự sao chép.","Tất cả các đáp án còn lại đều đúng"]}},
{"id":"ipr-97","q":"An author of a song wants that people will refer to his name whenever they sing that song. What type of intellectual property right can he claim?","o":["Copyright","Trademarks","Registered designs","Patent"],"a":[0],"m":"ipr","c":2,"n":97,"e":"Quyền yêu cầu nêu tên tác giả (paternity right) là quyền nhân thân thuộc bản quyền.","vi":{"q":"Tác giả một bài hát muốn mọi người nhắc đến tên mình mỗi khi hát bài đó. Anh ta có thể yêu cầu loại quyền sở hữu trí tuệ nào?","o":["Bản quyền","Nhãn hiệu","Kiểu dáng đã đăng ký","Sáng chế"]}},
{"id":"ipr-98","q":"Duration of false attribution right according to UK law","o":["Lasts for the life of its creator plus a further 50 years.","Lasts for 70 years begins to run on the death of the last surviving creator if two or more authors were jointly involved in the work","Lasts for the life of its creator plus a further 20 years)","None of others is correct"],"a":[2],"m":"ipr","c":2,"n":98,"f":1,"e":"Quyền chống gán sai tác giả (false attribution) kéo dài suốt đời người sáng tạo và thêm 20 năm sau khi mất.","vi":{"q":"Thời hạn của quyền chống gán sai tác giả (false attribution) theo luật Anh","o":["Suốt đời người sáng tạo cộng thêm 50 năm.","70 năm, bắt đầu tính từ khi người sáng tạo cuối cùng qua đời nếu có hai hay nhiều tác giả cùng tham gia tạo ra tác phẩm","Suốt đời người sáng tạo cộng thêm 20 năm)","Không đáp án nào còn lại đúng"]}},
{"id":"ipr-99","q":"A company wishes to ensure that no one else can use their logo. Which IPR protects that right?","o":["Copyright","Trademark","Patent","Industrial design"],"a":[1],"m":"ipr","c":4,"n":99,"e":"Logo được bảo hộ làm dấu hiệu nhận diện thương mại bằng nhãn hiệu (trademark), giúp ngăn người khác dùng.","vi":{"q":"Một công ty muốn bảo đảm không ai khác được dùng logo của mình. Quyền sở hữu trí tuệ nào bảo hộ quyền đó?","o":["Bản quyền","Nhãn hiệu","Sáng chế","Kiểu dáng công nghiệp"]}},
{"id":"ipr-100","q":"While proving for the reputation of an unregistered mark, the owner need to:","o":["Prove that the unregistered mark or the get-up is distinctive","Prove that the unregistered mark is taken to show a trade connection with a particular bus","A and B are correct","A and B are incorrect"],"a":[2],"m":"ipr","c":5,"n":100,"f":1,"e":"Để chứng minh uy tín của nhãn hiệu chưa đăng ký, chủ phải chứng minh dấu hiệu có tính phân biệt và được dùng để thể hiện mối liên hệ thương mại với một doanh nghiệp cụ thể.","vi":{"q":"Khi chứng minh uy tín của một nhãn hiệu chưa đăng ký, chủ sở hữu cần:","o":["Chứng minh nhãn hiệu chưa đăng ký hoặc get-up có tính phân biệt","Chứng minh nhãn hiệu chưa đăng ký được dùng để thể hiện mối liên hệ thương mại với một doanh nghiệp cụ thể","A và B đều đúng","A và B đều sai"]}},
{"id":"ipr-101","q":"The public domain is referred to:","o":["Addresses in Web","Any works not protected by copyright","Public land","The works protected by copyright"],"a":[1],"m":"ipr","c":2,"n":101,"e":"Phạm vi công cộng (public domain) gồm các tác phẩm không (còn) được bảo hộ bản quyền, ai cũng được dùng.","vi":{"q":"Phạm vi công cộng (public domain) là:","o":["Các địa chỉ trên Web","Bất kỳ tác phẩm nào không được bảo hộ bản quyền","Đất công","Các tác phẩm được bảo hộ bản quyền"]}},
{"id":"ipr-102","q":"What protects the intellectual property created by artist?","o":["Trademarks","Copyright","Patents","Confidential information"],"a":[1],"m":"ipr","c":1,"n":102,"e":"Tác phẩm do nghệ sĩ tạo ra được bảo hộ bằng bản quyền.","vi":{"q":"Quyền nào bảo hộ tài sản trí tuệ do nghệ sĩ tạo ra?","o":["Nhãn hiệu","Bản quyền","Sáng chế","Thông tin bí mật"]}},
{"id":"ipr-103","q":"What is the intention of the UK government in recognising design right?","o":["To take technical drawings out of copyright protection","To take functional articles out of copyright protection","None of A&B","Both A&B"],"a":[3],"m":"ipr","c":6,"n":103,"f":1,"e":"Quyền kiểu dáng được đưa vào nhằm đưa bản vẽ kỹ thuật và sản phẩm mang tính chức năng ra khỏi phạm vi bảo hộ bản quyền (vụ British Leyland).","vi":{"q":"Mục đích của chính phủ Anh khi công nhận quyền kiểu dáng (design right) là gì?","o":["Đưa các bản vẽ kỹ thuật ra khỏi phạm vi bảo hộ bản quyền","Đưa các sản phẩm mang tính chức năng ra khỏi phạm vi bảo hộ bản quyền","Không phải A và B","Cả A và B"]}},
{"id":"ipr-104","q":"In the case that the registered design of goods has been copied. Which of the following is RIGHT?","o":["The person accused of infringement can prove his/her innocence","The person accused of infringement cannot prove his/her innocence","In protecting by registered design, the owner needs to prove copying","Both A&C"],"a":[3],"m":"ipr","c":6,"n":104,"f":1,"e":"Theo đáp án của đề, người bị cáo buộc có thể chứng minh mình vô can và chủ sở hữu phải chứng minh sao chép; xem cảnh báo bên dưới về mâu thuẫn với các câu khác.","vi":{"q":"Trong trường hợp kiểu dáng đã đăng ký của một loại hàng hóa bị sao chép, phát biểu nào sau đây ĐÚNG?","o":["Người bị cáo buộc xâm phạm có thể chứng minh mình vô can","Người bị cáo buộc xâm phạm không thể chứng minh mình vô can","Khi bảo vệ bằng kiểu dáng đã đăng ký, chủ sở hữu cần chứng minh có sự sao chép","Cả A và C"]},"k":"Câu này mâu thuẫn với câu #48 và #95 (kiểu dáng đã đăng ký: chủ sở hữu không cần chứng minh sao chép). Chọn theo đáp án của đề ({D})."},
{"id":"ipr-105","q":"Which of the following is NOT an example of literary work?","o":["A book","An engineer report or specification","A bus timetable","A legal document"],"a":[2],"m":"ipr","c":2,"n":105,"e":"Theo đáp án của đề, bảng giờ xe buýt không phải ví dụ về tác phẩm văn học; sách, báo cáo kỹ thuật và văn bản pháp lý là tác phẩm văn học.","vi":{"q":"Điều nào sau đây KHÔNG phải là ví dụ về tác phẩm văn học (literary work)?","o":["Một cuốn sách","Một báo cáo hoặc bản mô tả kỹ thuật của kỹ sư","Một bảng giờ xe buýt","Một văn bản pháp lý"]},"k":"Theo luật Anh, bảng giờ xe buýt thường vẫn được coi là tác phẩm văn học (dạng bảng/tập hợp dữ liệu). Đề chọn {C}."},
{"id":"ipr-106","q":"Case: Kastenholz, vs Office for Harmonisation in the Internal Market (OHIM), Qwatchme A/S [2013] T-68/11 (06 June 2013) What are the findings that the OHIM's third Board of Appeal dismissed the Kastenholz's application for a declaration of invalidity appeal?","o":["The contested design was different from the earlier designs","The contested design possessed individual character","The contested design could not be regarded as being a reproduction or an adaptation of the earlier works of art.","All of the above"],"a":[3],"m":"ipr","c":6,"n":106,"f":1,"e":"Trong vụ Kastenholz, Hội đồng kháng nghị bác đơn vì thiết kế bị tranh chấp khác các thiết kế trước, có tính độc đáo riêng và không phải bản sao hay chuyển thể tác phẩm nghệ thuật có trước; đề chọn «tất cả».","vi":{"q":"Vụ việc: Kastenholz kiện Cơ quan Hài hòa hóa Thị trường Nội khối (OHIM), Qwatchme A/S [2013] T-68/11 (ngày 06/06/2013). Hội đồng Kháng nghị thứ ba của OHIM đã bác đơn kháng nghị yêu cầu tuyên bố vô hiệu của Kastenholz dựa trên những kết luận nào?","o":["Kiểu dáng bị tranh chấp khác với các kiểu dáng trước đó","Kiểu dáng bị tranh chấp có tính độc đáo riêng (individual character)","Kiểu dáng bị tranh chấp không thể bị coi là bản sao chép hoặc chuyển thể từ các tác phẩm nghệ thuật có trước.","Tất cả các đáp án trên"]}},
{"id":"ipr-107","q":"The word \"Steel\" can be add in trademark of.......","o":["Only company producing steel","Only company not producing steel","Any company","All company"],"a":[2],"m":"ipr","c":4,"n":107,"e":"Từ «Steel» có thể nằm trong nhãn hiệu của bất kỳ công ty nào, vì nhãn hiệu có thể dùng từ thông thường nếu tổng thể vẫn có tính phân biệt.","vi":{"q":"Từ \"Steel\" (thép) có thể được thêm vào nhãn hiệu của.......","o":["Chỉ công ty sản xuất thép","Chỉ công ty không sản xuất thép","Bất kỳ công ty nào","Tất cả các công ty"]}},
{"id":"ipr-108","q":"A coffee mug having a textured surface created by Kevin, the surface decoration can be protected by:","o":["Registered designs","Design right.","Copyright","None of the above"],"a":[0],"m":"ipr","c":6,"n":108,"f":1,"e":"Trang trí bề mặt (surface decoration) bị loại khỏi quyền kiểu dáng nhưng có thể được bảo hộ bằng kiểu dáng đã đăng ký.","vi":{"q":"Một chiếc cốc cà phê có bề mặt gồ ghề do Kevin tạo ra; phần trang trí bề mặt có thể được bảo hộ bởi:","o":["Kiểu dáng đã đăng ký","Quyền kiểu dáng (design right).","Bản quyền","Không loại nào ở trên"]}},
{"id":"ipr-109","q":"Computer icon is protected by","o":["Copyright","Design right","Trademark","Registered design"],"a":[3],"m":"ipr","c":6,"n":109,"e":"Biểu tượng (icon) máy tính là hình thể hiện của sản phẩm/giao diện, được bảo hộ bằng kiểu dáng đã đăng ký.","vi":{"q":"Biểu tượng (icon) trên máy tính được bảo hộ bởi","o":["Bản quyền","Quyền kiểu dáng","Nhãn hiệu","Kiểu dáng đã đăng ký"]}},
{"id":"ipr-110","q":"A technical drawing is protected by..........","o":["Copyright","Registered designs","Both copyright and registered designs","Patent"],"a":[0],"m":"ipr","c":1,"n":110,"e":"Bản vẽ kỹ thuật được bảo hộ bằng bản quyền như tác phẩm đồ họa. Xem cảnh báo về mâu thuẫn với câu #53.","vi":{"q":"Một bản vẽ kỹ thuật được bảo hộ bởi..........","o":["Bản quyền","Kiểu dáng đã đăng ký","Cả bản quyền và kiểu dáng đã đăng ký","Sáng chế"]},"k":"Câu này đối lập với câu #53 (bản vẽ kỹ thuật của ti vi: đề chọn «bản quyền và kiểu dáng đã đăng ký»). Ở đây đề chọn chỉ bản quyền."},
{"id":"ipr-111","q":"Is it necessary to prove that those knowing the mark or get-up can identif he owner?","o":["No","Yes. It is necessary","Yes. This is a must to protect the original owner of the trade mark","Yes. It is important to know who is the first one registering for the trade mark"],"a":[0],"m":"ipr","c":5,"n":111,"e":"Không cần chứng minh rằng người biết nhãn hiệu/get-up nhận ra chủ sở hữu cụ thể; chỉ cần họ gắn nó với một nguồn gốc thương mại.","vi":{"q":"Có cần chứng minh rằng những người biết nhãn hiệu hoặc get-up có thể nhận ra chủ sở hữu không?","o":["Không","Có. Điều đó là cần thiết","Có. Điều này bắt buộc để bảo vệ chủ sở hữu ban đầu của nhãn hiệu","Có. Điều quan trọng là biết ai là người đầu tiên đăng ký nhãn hiệu"]}},
{"id":"ipr-112","q":"The owner of copyright of a book written on author's own is","o":["Its author","The publisher of the book","The person who prints it with consent of the author","The person who provide the ideas for this book"],"a":[0],"m":"ipr","c":2,"n":112,"e":"Tác giả tự viết sách là chủ sở hữu bản quyền ban đầu, trừ khi là nhân viên hoặc đã chuyển nhượng.","vi":{"q":"Chủ sở hữu bản quyền của một cuốn sách do tác giả tự viết là","o":["Chính tác giả","Nhà xuất bản cuốn sách","Người in sách với sự đồng ý của tác giả","Người cung cấp ý tưởng cho cuốn sách này"]}},
{"id":"ipr-113","q":"What can be used to make a copy of a design?","o":["Only the article itself","Only the design document of the article","Either the article itself or its design document","None of the article and its design document"],"a":[2],"m":"ipr","c":6,"n":113,"f":1,"e":"Có thể sao chép thiết kế thông qua chính sản phẩm hoặc thông qua tài liệu thiết kế của nó.","vi":{"q":"Có thể dùng cái gì để sao chép một thiết kế?","o":["Chỉ chính sản phẩm đó","Chỉ tài liệu thiết kế của sản phẩm","Hoặc chính sản phẩm, hoặc tài liệu thiết kế của nó","Không phải sản phẩm cũng không phải tài liệu thiết kế"]}},
{"id":"ipr-114","q":"An article with its exterior identical to a previous design but its internal feature which cannot be seen is different. This article is protected by:","o":["Design right.","Copyright","Confidential information","Trade secret"],"a":[0],"m":"ipr","c":6,"n":114,"e":"Quyền kiểu dáng bảo hộ cả đặc điểm bên trong sản phẩm (kể cả không nhìn thấy), khác với kiểu dáng đã đăng ký chỉ bảo hộ phần nhìn thấy.","vi":{"q":"Một sản phẩm có bề ngoài giống hệt một thiết kế trước đó nhưng đặc điểm bên trong (không nhìn thấy được) thì khác. Sản phẩm này được bảo hộ bởi:","o":["Quyền kiểu dáng (design right).","Bản quyền","Thông tin bí mật","Bí mật thương mại"]}},
{"id":"ipr-115","q":"According to Vietnam law, duration of a broadcast program related right","o":["Lasts for 50 years from the year it is released to the public","Lasts for the life of its creator plus a further 50 years.","Lasts for 70 years begins to run on the death of the last surviving creator if two or more authors were jointly involved in the work","Lasts forever"],"a":[0],"m":"ipr","c":2,"n":115,"e":"Theo luật Việt Nam, quyền liên quan đối với chương trình phát sóng có thời hạn 50 năm kể từ khi công bố.","vi":{"q":"Theo luật Việt Nam, thời hạn bảo hộ quyền liên quan đối với chương trình phát sóng","o":["Kéo dài 50 năm kể từ năm công bố ra công chúng","Suốt đời người sáng tạo cộng thêm 50 năm.","70 năm, bắt đầu tính từ khi người sáng tạo cuối cùng qua đời nếu có hai hay nhiều tác giả cùng tham gia tạo ra tác phẩm","Vĩnh viễn"]}},
{"id":"ipr-116","q":"An article is referred to without naming the author. This is an infringement of......","o":["Reproduction right","Paternity right","Integrity right","False attribution"],"a":[1],"m":"ipr","c":2,"n":116,"e":"Trích bài báo không nêu tên tác giả xâm phạm quyền được nhận là tác giả (paternity right).","vi":{"q":"Một bài báo được trích dẫn mà không nêu tên tác giả. Đây là xâm phạm ......","o":["Quyền sao chép","Quyền được nhận là tác giả (paternity right)","Quyền toàn vẹn tác phẩm","Việc gán sai tác giả (false attribution)"]}},
{"id":"ipr-117","q":"According to UK law, to be granted suspension of release by custom authorities, the applicant must","o":["Provide adequate evidence to prove that under the laws of the country of importation, there is prima facie an infringement of the right holder's intellectual property right","Supply a sufficiently detailed description of the goods to make them readily recognizable by the customs authorities","Provide a security or equivalent assurance sufficient to protect the defendant and the competent authorities and to prevent abuse","All of others are correct"],"a":[3],"m":"ipr","c":1,"n":117,"f":1,"e":"Để hải quan đình chỉ thông quan, người nộp đơn phải có bằng chứng ban đầu về xâm phạm, mô tả đủ chi tiết hàng hóa và đặt khoản bảo đảm; nên chọn «tất cả».","vi":{"q":"Theo luật Anh, để được cơ quan hải quan đình chỉ việc thông quan hàng hóa, người nộp đơn phải","o":["Cung cấp bằng chứng đầy đủ để chứng minh rằng, theo pháp luật của nước nhập khẩu, có dấu hiệu rõ ràng (prima facie) về hành vi xâm phạm quyền sở hữu trí tuệ của chủ sở hữu quyền","Cung cấp mô tả đủ chi tiết về hàng hóa để cơ quan hải quan dễ dàng nhận biết","Cung cấp khoản bảo đảm hoặc cam kết tương đương đủ để bảo vệ bị đơn và cơ quan có thẩm quyền, đồng thời ngăn ngừa lạm dụng","Tất cả các đáp án còn lại đều đúng"]}},
{"id":"ipr-118","q":"The civil remedies against copyright infringement include","o":["Final remedies, compensatory damages, criminal sanctions","Provisional measure, injunction, delivery-up, compensatory damages, punitive damages, account of profits","Injunction, compensatory damages, border measures","Account of profits, border measures, final remedies"],"a":[1],"m":"ipr","c":3,"n":118,"e":"Các biện pháp dân sự gồm biện pháp khẩn cấp tạm thời, lệnh cấm, giao nộp hàng vi phạm, bồi thường, bồi thường trừng phạt và truy thu lợi nhuận. Chế tài hình sự và biện pháp biên giới không thuộc nhóm này.","vi":{"q":"Các biện pháp dân sự chống hành vi xâm phạm bản quyền bao gồm","o":["Biện pháp cuối cùng (final remedies), bồi thường thiệt hại bù đắp, chế tài hình sự","Biện pháp khẩn cấp tạm thời, lệnh cấm, giao nộp hàng vi phạm, bồi thường thiệt hại bù đắp, bồi thường mang tính trừng phạt, truy thu lợi nhuận","Lệnh cấm, bồi thường thiệt hại bù đắp, biện pháp biên giới","Truy thu lợi nhuận, biện pháp biên giới, biện pháp cuối cùng"]}},
{"id":"ipr-119","q":"You can infringe a patent by............","o":["Making a product for your own personal use","Publishing drawings of the product on your website","Selling main components of the product, together with instruction how to assemble it using commonly available fastening components.","Talking about it"],"a":[2],"m":"ipr","c":6,"n":119,"e":"Bán các bộ phận chính kèm hướng dẫn lắp ráp là xâm phạm sáng chế gián tiếp (contributory). Dùng cá nhân (không thương mại), công bố bản vẽ hay nói về sáng chế thì không.","vi":{"q":"Bạn có thể xâm phạm sáng chế bằng cách............","o":["Làm ra sản phẩm để dùng cho cá nhân mình","Công bố bản vẽ sản phẩm trên trang web của bạn","Bán các bộ phận chính của sản phẩm kèm hướng dẫn cách lắp ráp bằng các chi tiết gắn kết thông dụng.","Nói về nó"]}},
{"id":"ipr-120","q":"According to TRIPS, after registration a mark must be used; if not, it can be cancelled after how many years?","o":["3","4","5","6"],"a":[0],"m":"ipr","c":4,"n":120,"e":"Theo TRIPS, nhãn hiệu phải được sử dụng; nếu không dùng liên tục ít nhất 3 năm thì có thể bị hủy.","vi":{"q":"Theo TRIPS, sau khi đăng ký nhãn hiệu phải được sử dụng; nếu không thì có thể bị hủy bỏ sau bao nhiêu năm?","o":["3","4","5","6"]}},
{"id":"ipr-121","q":"According to TRIPS, if registration of sounds or smells is allowed by countries?","o":["Yes. Provided that these are distinctive","No. Only invented words permitted","No. Only signs are permitted","No. Since sounds or smells are not distinctive."],"a":[0],"m":"ipr","c":4,"n":121,"e":"TRIPS cho phép đăng ký âm thanh hoặc mùi nếu chúng có tính phân biệt.","vi":{"q":"Theo TRIPS, các nước có được phép đăng ký âm thanh hoặc mùi không?","o":["Có. Với điều kiện chúng có tính phân biệt","Không. Chỉ cho phép từ do tự đặt ra","Không. Chỉ cho phép các dấu hiệu","Không. Vì âm thanh hoặc mùi không có tính phân biệt."]}},
{"id":"ipr-122","q":"Duration of economics right in films according to Vietnam law","o":["Lasts for 50 years from the year the film or record was made or, if it is released to the public, 50 years from its release","Lasts for the life of its creator plus a further 50 years.","Lasts for 70 years begins to run on the death of the last surviving creator if two or more authors were jointly involved in the work","Lasts for 75 years from the end of the year in which the film was created"],"a":[3],"m":"ipr","c":2,"n":122,"e":"Theo đáp án của đề, quyền kinh tế đối với phim theo luật Việt Nam kéo dài 75 năm.","vi":{"q":"Thời hạn bảo hộ quyền kinh tế đối với phim theo luật Việt Nam","o":["Kéo dài 50 năm kể từ năm phim hoặc bản ghi được tạo ra, hoặc nếu được công bố ra công chúng thì 50 năm kể từ khi công bố","Suốt đời người sáng tạo cộng thêm 50 năm.","70 năm, bắt đầu tính từ khi người sáng tạo cuối cùng qua đời nếu có hai hay nhiều tác giả cùng tham gia tạo ra tác phẩm","75 năm kể từ cuối năm mà bộ phim được tạo ra"]}},
{"id":"ipr-123","q":"When does the owner of a registered design have the right to start proceedings for infringement of her/his rights?","o":["When the registration is applied","When a certificate is issued and the registration is published","When the representation of the design is completed","When the owner of the registered design found out an infringement of her/his rights"],"a":[1],"m":"ipr","c":6,"n":123,"e":"Chủ sở hữu kiểu dáng đã đăng ký được khởi kiện khi giấy chứng nhận đã được cấp và đăng ký đã được công bố.","vi":{"q":"Khi nào chủ sở hữu kiểu dáng đã đăng ký có quyền khởi kiện về hành vi xâm phạm quyền của mình?","o":["Khi nộp đơn đăng ký","Khi giấy chứng nhận được cấp và đăng ký được công bố","Khi hình thể hiện của kiểu dáng hoàn thành","Khi chủ sở hữu kiểu dáng đã đăng ký phát hiện ra hành vi xâm phạm quyền của mình"]}},
{"id":"ipr-124","q":"Suspecting an infringement of his rights, Peter, the owner of a registered design has written to sue a suspected infringer. When can the threatened person sue Peter for making an unjustified threat?","o":["When there was no infringement","When there is an infringement","The person threatened cannot sue Peter in any cases","Both B&C"],"a":[0],"m":"ipr","c":6,"n":124,"f":1,"e":"Người bị đe dọa có thể kiện vì đe dọa không chính đáng khi thực tế không có hành vi xâm phạm.","vi":{"q":"Nghi ngờ quyền của mình bị xâm phạm, Peter, chủ sở hữu kiểu dáng đã đăng ký, đã gửi thư dọa kiện một người bị nghi là vi phạm. Khi nào người bị đe dọa có thể kiện Peter vì đe dọa kiện không chính đáng (unjustified threat)?","o":["Khi không có hành vi xâm phạm","Khi có hành vi xâm phạm","Người bị đe dọa không thể kiện Peter trong bất kỳ trường hợp nào","Cả B và C"]}},
{"id":"ipr-125","q":"ATM machine is protected...","o":["Only by design right","Only by patents","By both design right and patents","By trademark"],"a":[2],"m":"ipr","c":1,"n":125,"e":"Máy ATM có phần hình dáng (quyền kiểu dáng) và phần chức năng/kỹ thuật (sáng chế) nên được bảo hộ đồng thời cả hai.","vi":{"q":"Máy ATM được bảo hộ...","o":["Chỉ bằng quyền kiểu dáng","Chỉ bằng sáng chế","Bằng cả quyền kiểu dáng và sáng chế","Bằng nhãn hiệu"]}},
{"id":"ipr-126","q":"If a mark or get-up has been used long enough to have generated a reputation, the owner can stop a competitor from 'passing-off' goods or services as if they originated with the owner by use of identical or similar marks or get-ups. To do this the owner must show:","o":["there is a reputation in the mark or get-up","there has been confusion in the market place","the owner has suffered damage","All A+B+C must be proved together"],"a":[3],"m":"ipr","c":5,"n":126,"f":1,"e":"Passing off phải chứng minh đồng thời ba yếu tố: uy tín, nhầm lẫn và thiệt hại.","vi":{"q":"Nếu một nhãn hiệu hoặc get-up đã được sử dụng đủ lâu để tạo ra uy tín, chủ sở hữu có thể ngăn đối thủ \"passing-off\" hàng hóa hoặc dịch vụ như thể có nguồn gốc từ chủ sở hữu bằng cách dùng nhãn hiệu hoặc get-up giống hệt hoặc tương tự. Để làm vậy, chủ sở hữu phải chứng minh:","o":["có uy tín đối với nhãn hiệu hoặc get-up","đã có sự nhầm lẫn trên thị trường","chủ sở hữu đã bị thiệt hại","Phải chứng minh đồng thời cả A + B + C"]}},
{"id":"ipr-127","q":"Which of the following is NOT protected by an artistic copyright accordinato UK law?","o":["A fully prepared text, a note or in shorthand, on tape or disk","A recording of light or other radiation on any medium on which an image is produced or from which an image may by any means be produced","Technical drawings, photographs and to designs of buildings and other structures","Any drawing, diagram, map, chart or plan"],"a":[0],"m":"ipr","c":2,"n":127,"e":"Văn bản, ghi chú, tốc ký thuộc tác phẩm văn học, không phải tác phẩm nghệ thuật; còn ảnh, bản vẽ kỹ thuật, bản đồ, sơ đồ là tác phẩm nghệ thuật.","vi":{"q":"Điều nào sau đây KHÔNG được bảo hộ bản quyền tác phẩm nghệ thuật (artistic copyright) theo luật Anh?","o":["Một văn bản đã soạn đầy đủ, một ghi chú hoặc bản tốc ký, trên băng hay đĩa","Bản ghi ánh sáng hoặc bức xạ khác trên bất kỳ phương tiện nào mà trên đó hình ảnh được tạo ra hoặc từ đó có thể tạo ra hình ảnh bằng bất kỳ cách nào","Bản vẽ kỹ thuật, ảnh chụp và thiết kế của các tòa nhà và công trình khác","Bất kỳ bản vẽ, sơ đồ, bản đồ, biểu đồ hay kế hoạch nào"]}},
{"id":"ipr-128","q":"Singing a song in a party with friends is.","o":["Infringement of reproduction right","Infringement of public performance right","Infringement of false attribution right","Not an infringement of copyright"],"a":[3],"m":"ipr","c":3,"n":128,"e":"Hát cho bạn bè trong buổi tiệc là trình diễn riêng tư (không công khai) nên không xâm phạm bản quyền.","vi":{"q":"Hát một bài hát trong buổi tiệc với bạn bè là.","o":["Xâm phạm quyền sao chép","Xâm phạm quyền biểu diễn trước công chúng","Xâm phạm quyền chống gán sai tác giả","Không phải là hành vi xâm phạm bản quyền"]}},
{"id":"ipr-129","q":"What is licensing?","o":["The permission to perform one or more acts covered by exclusive rights of the owner of patented invention/IPRs within a specific area and for particular time.","The ownership of IPRs is transferred.","The supplier promises to deliver the know-how to another party (recipient) for the use by that party.","Owner gives up the ownership of his/her intellectual property"],"a":[0],"m":"ipr","c":1,"n":129,"e":"Cấp phép (licensing) là cho phép thực hiện một hoặc nhiều hành vi thuộc quyền độc quyền trong phạm vi và thời hạn nhất định; quyền sở hữu vẫn thuộc chủ.","vi":{"q":"Cấp phép sử dụng (licensing) là gì?","o":["Sự cho phép thực hiện một hoặc nhiều hành vi thuộc quyền độc quyền của chủ sở hữu sáng chế/quyền sở hữu trí tuệ trong một phạm vi cụ thể và trong một thời gian nhất định.","Quyền sở hữu quyền sở hữu trí tuệ được chuyển giao.","Bên cung cấp hứa chuyển giao bí quyết kỹ thuật (know-how) cho bên khác (bên nhận) để bên đó sử dụng.","Chủ sở hữu từ bỏ quyền sở hữu tài sản trí tuệ của mình"]}},
{"id":"ipr-130","q":"Which value of ideas and information that Intellectual Property Rights (IPR) protect?","o":["Ethical value","Moral value","Social value","Commercial value"],"a":[3],"m":"ipr","c":1,"n":130,"e":"Quyền sở hữu trí tuệ bảo hộ giá trị thương mại của ý tưởng và thông tin.","vi":{"q":"Quyền sở hữu trí tuệ (IPR) bảo hộ giá trị nào của ý tưởng và thông tin?","o":["Giá trị đạo đức (ethical)","Giá trị tinh thần (moral)","Giá trị xã hội","Giá trị thương mại"]}},
{"id":"ipr-131","q":"The term \"WIPO\" stands for:","o":["World Investment policy organization","World intellectual property organization","Wildlife Investigation and Policing organization","World institute for Prevention of organized crime"],"a":[1],"m":"ipr","c":1,"n":131,"e":"WIPO là World Intellectual Property Organization, Tổ chức Sở hữu Trí tuệ Thế giới.","vi":{"q":"Thuật ngữ \"WIPO\" là viết tắt của:","o":["Tổ chức Chính sách Đầu tư Thế giới","Tổ chức Sở hữu Trí tuệ Thế giới","Tổ chức Điều tra và Kiểm soát Động vật Hoang dã","Viện Thế giới Phòng chống Tội phạm có tổ chức"]}},
{"id":"ipr-132","q":"Which IPR DOES NOT protect a technical report or specification?","o":["Copyright","Patent","Confidential information","Design right"],"a":[3],"m":"ipr","c":1,"n":132,"e":"Quyền kiểu dáng bảo hộ hình dáng sản phẩm, không bảo hộ báo cáo hay bản mô tả kỹ thuật (bảo hộ bằng bản quyền, sáng chế, thông tin bí mật).","vi":{"q":"Quyền sở hữu trí tuệ nào KHÔNG bảo hộ một báo cáo hoặc bản mô tả kỹ thuật?","o":["Bản quyền","Sáng chế","Thông tin bí mật","Quyền kiểu dáng"]}},
{"id":"ipr-133","q":"An engineering drawing on paper is NOT protected by","o":["Copyright","Patent","Trademark","Design right"],"a":[2],"m":"ipr","c":1,"n":133,"e":"Bản vẽ kỹ thuật được bảo hộ bản quyền, có thể gắn với sáng chế và quyền kiểu dáng; nhãn hiệu không bảo hộ bản vẽ.","vi":{"q":"Một bản vẽ kỹ thuật trên giấy KHÔNG được bảo hộ bởi","o":["Bản quyền","Sáng chế","Nhãn hiệu","Quyền kiểu dáng"]}},
{"id":"ipr-134","q":"Electrical device (thiết bi điện) is protected by","o":["Copyright","Confidential information","Trademark","Design right"],"a":[3],"m":"ipr","c":1,"n":134,"e":"Thiết bị điện là sản phẩm ba chiều nên được bảo hộ bằng quyền kiểu dáng.","vi":{"q":"Thiết bị điện (thiết bị điện) được bảo hộ bởi","o":["Bản quyền","Thông tin bí mật","Nhãn hiệu","Quyền kiểu dáng"]}},
{"id":"ipr-135","q":"Computer program can be protected by","o":["Copyright, topography right, trademark","Confidential information, topography right, patent","Trademark, confidential information, copyright","Topography right, patent, confidential information, copyright"],"a":[3],"m":"ipr","c":1,"n":135,"e":"Chương trình máy tính có thể được bảo hộ đồng thời bằng quyền thiết kế bố trí, sáng chế, thông tin bí mật và bản quyền.","vi":{"q":"Chương trình máy tính có thể được bảo hộ bởi","o":["Bản quyền, quyền đối với thiết kế bố trí (topography right), nhãn hiệu","Thông tin bí mật, quyền đối với thiết kế bố trí, sáng chế","Nhãn hiệu, thông tin bí mật, bản quyền","Quyền đối với thiết kế bố trí, sáng chế, thông tin bí mật, bản quyền"]}},
{"id":"ipr-136","q":"Name of a product is protected by","o":["Copyright","Confidential information","Trademark","Topography right"],"a":[2],"m":"ipr","c":1,"n":136,"e":"Tên sản phẩm được bảo hộ bằng nhãn hiệu.","vi":{"q":"Tên của một sản phẩm được bảo hộ bởi","o":["Bản quyền","Thông tin bí mật","Nhãn hiệu","Quyền đối với thiết kế bố trí (topography right)"]}},
{"id":"ipr-137","q":"This IP right is associated with every literary, dramatic, musical or artistic work, to sound recordings, films, broadcasts and cable programmes. This right is:","o":["Copyright","Design right","Registered design","Confidential information"],"a":[0],"m":"ipr","c":2,"n":137,"e":"Bản quyền gắn với mọi tác phẩm văn học, kịch, âm nhạc, nghệ thuật, bản ghi âm, phim, chương trình phát sóng và truyền hình cáp.","vi":{"q":"Quyền sở hữu trí tuệ này gắn với mọi tác phẩm văn học, kịch, âm nhạc hay nghệ thuật, với bản ghi âm, phim, chương trình phát sóng và chương trình truyền hình cáp. Quyền này là:","o":["Bản quyền","Quyền kiểu dáng","Kiểu dáng đã đăng ký","Thông tin bí mật"]}},
{"id":"ipr-138","q":"Which of the following is protected by copyright?","o":["Idea","Concept","Expression (Biểu thức)","None of others is correct"],"a":[2],"m":"ipr","c":2,"n":138,"f":1,"e":"Bản quyền bảo hộ sự thể hiện (expression), không bảo hộ ý tưởng hay khái niệm.","vi":{"q":"Điều nào sau đây được bảo hộ bản quyền?","o":["Ý tưởng","Khái niệm","Sự thể hiện (expression)","Không đáp án nào còn lại đúng"]}},
{"id":"ipr-139","q":"Which of the following is NOT an infringment in coyright according to UK law?","o":["Copying in a different medium to the original work, such as a photocopy of a book, or a scanned-in digital copy of a photograph","Making a short-term or transient copy","Speaking words aloud without making a copy whether by shorthand or on tape","Making an object in three dimensions from a drawing of that object"],"a":[2],"m":"ipr","c":3,"n":139,"e":"Đọc to mà không tạo bản sao không phải sao chép nên không xâm phạm; photocopy, bản sao tạm thời, làm vật thể 3D từ bản vẽ đều là sao chép.","vi":{"q":"Điều nào sau đây KHÔNG phải là hành vi xâm phạm bản quyền theo luật Anh?","o":["Sao chép sang một phương tiện khác với tác phẩm gốc, như photocopy một cuốn sách hoặc bản sao kỹ thuật số quét từ một bức ảnh","Tạo ra một bản sao tạm thời hoặc ngắn hạn","Đọc to các từ mà không tạo bản sao, dù bằng tốc ký hay trên băng","Làm một vật thể ba chiều từ bản vẽ của chính vật thể đó"]}},
{"id":"ipr-140","q":"Which of the following is NOT an infringment in coyright?","o":["Someone copies without the copyright owner's permission","A photographer takes a photograph of a particular scenic view, even though the photograph is virtually indistinguishable to another person's photograph.","Someone creates a scene in a studio to reproduce a scene in someone else's photograph","One similarity drawing has had access to the material which has supposedly been copied"],"a":[1],"m":"ipr","c":3,"n":140,"e":"Hai nhiếp ảnh gia tự chụp độc lập cùng khung cảnh không phải sao chép nên không xâm phạm.","vi":{"q":"Điều nào sau đây KHÔNG phải là hành vi xâm phạm bản quyền?","o":["Ai đó sao chép mà không có sự cho phép của chủ sở hữu bản quyền","Một nhiếp ảnh gia chụp một khung cảnh thiên nhiên nhất định, dù bức ảnh gần như không thể phân biệt với ảnh của người khác.","Ai đó dựng lại một cảnh trong studio để tái tạo cảnh trong bức ảnh của người khác","Một bản vẽ tương tự đã tiếp cận được tài liệu được cho là đã bị sao chép"]}},
{"id":"ipr-141","q":"The main law applicable in the UK for copyright is","o":["The Copyright, Designs and Patents Act 1988 and its revision","A WIPO Treaty on Copyright","EU directives on e-commerce and digital copyright","The Patents Act 1977"],"a":[0],"m":"ipr","c":2,"n":141,"e":"Luật chính về bản quyền ở Anh là Đạo luật Bản quyền, Kiểu dáng và Sáng chế (CDPA) 1988 cùng các bản sửa đổi.","vi":{"q":"Luật chính áp dụng cho bản quyền ở Anh là","o":["Đạo luật Bản quyền, Kiểu dáng và Sáng chế 1988 và các bản sửa đổi","Một hiệp ước của WIPO về bản quyền","Các chỉ thị của EU về thương mại điện tử và bản quyền kỹ thuật số","Đạo luật Sáng chế 1977"]}},
{"id":"ipr-142","q":"Which is NOT right about \"literary copyright\" according to Act 88?","o":["A literary work is 'any work... which is written, spoken or sung'","Copyright applies from the instant the work is recorded and the law refers to this being 'in writing or otherwise'","The 88 Act is silent on quality or literary merit","The author's intention is relevant. An internal memo is legally protected to the same degree and the same value as a fully revised paper written for publication."],"a":[3],"m":"ipr","c":2,"n":142,"e":"Ý định của tác giả không liên quan: bản ghi nhớ nội bộ và bài báo đã chỉnh sửa đều được bảo hộ như nhau nếu đạt tính nguyên gốc; luật cũng không xét chất lượng, nên phát biểu {D} (không đúng) là đáp án.","vi":{"q":"Điều nào KHÔNG đúng về \"bản quyền văn học\" (literary copyright) theo Đạo luật 88?","o":["Tác phẩm văn học là 'bất kỳ tác phẩm nào... được viết, nói hoặc hát'","Bản quyền phát sinh ngay từ khi tác phẩm được ghi lại và luật gọi đó là 'bằng văn bản hoặc cách khác'","Đạo luật 88 không đề cập đến chất lượng hay giá trị văn học","Ý định của tác giả là có liên quan. Một bản ghi nhớ nội bộ được bảo hộ về mặt pháp lý ở mức độ và giá trị như một bài báo đã được chỉnh sửa hoàn chỉnh để xuất bản."]}},
{"id":"ipr-143","q":"Which is NOT right about \"literary copyright\" according to Act 88?","o":["One word is sufficient to be a copyright work, such as a company name","Titles of books and magazines, particularly when they consist of conventional words, are not copyright","A list of code words or shorthand symbols will also be protected by copyright","The only hint of a criterion is on length"],"a":[0],"m":"ipr","c":2,"n":143,"e":"Một từ đơn lẻ như tên công ty thường không đủ để thành tác phẩm có bản quyền, nên phát biểu {A} là sai.","vi":{"q":"Điều nào KHÔNG đúng về \"bản quyền văn học\" (literary copyright) theo Đạo luật 88?","o":["Một từ là đủ để trở thành tác phẩm có bản quyền, chẳng hạn tên một công ty","Tiêu đề sách và tạp chí, đặc biệt khi gồm những từ thông thường, không được bảo hộ bản quyền","Một danh sách các từ mã hoặc ký hiệu tốc ký cũng được bảo hộ bản quyền","Dấu hiệu duy nhất về tiêu chí là độ dài"]}},
{"id":"ipr-144","q":"Which of the following is NOT right about Copyright in computer programs according to UK law?","o":["are classified as literary works","as 'any form of notation or code, whether by hand or otherwise and regardless of the method by which, or medium in or on which, it is recorded'","enough for electronic copyright","The 88 Act does not define 'computer program' or even 'computer' to ensure that the law will still apply even when technology moves on and new types of machine are developed which are not recognisable as computers, or new methods of instructing hardware are devised."],"a":[2],"m":"ipr","c":2,"n":144,"e":"Việc «đủ để có bản quyền điện tử» không phải nội dung của luật; chương trình máy tính là tác phẩm văn học, luật không định nghĩa chặt «máy tính».","vi":{"q":"Điều nào sau đây KHÔNG đúng về bản quyền chương trình máy tính theo luật Anh?","o":["được xếp vào loại tác phẩm văn học","là 'bất kỳ hình thức ký hiệu hay mã nào, dù bằng tay hay cách khác, bất kể phương pháp hay phương tiện ghi lại'","đủ để có bản quyền điện tử","Đạo luật 88 không định nghĩa 'chương trình máy tính' hay thậm chí 'máy tính' để bảo đảm luật vẫn áp dụng khi công nghệ phát triển, xuất hiện loại máy mới không còn giống máy tính hoặc các phương pháp chỉ huy phần cứng mới."]}},
{"id":"ipr-145","q":"Part of an Internet address, such as cengage.com → Domain name","o":["True","False"],"a":[0],"m":"ipr","c":5,"n":145,"e":"Một phần của địa chỉ Internet, như cengage.com, là tên miền (domain name): ghép đúng.","vi":{"q":"Một phần của địa chỉ Internet, ví dụ cengage.com → Tên miền (Domain name)","o":["Đúng","Sai"]}},
{"id":"ipr-146","q":"The exclusive right of an offer or originator of a literary or artistic production to publish, print, sell, or otherwise use that production for a statutory period of time → Patent","o":["True","False"],"a":[0],"m":"ipr","c":1,"n":146,"e":"Theo đáp án của đề, ghép được xem là đúng. Tuy nhiên định nghĩa nêu là của bản quyền; xem cảnh báo bên dưới.","vi":{"q":"Quyền độc quyền của người đưa ra hoặc người khởi tạo một sản phẩm văn học hay nghệ thuật được xuất bản, in, bán hoặc sử dụng sản phẩm đó trong một thời hạn theo luật định → Sáng chế (Patent)","o":["Đúng","Sai"]},"k":"Định nghĩa nêu trong câu mô tả BẢN QUYỀN (copyright), không phải sáng chế. Nhiều khả năng khẳng định này phải là «Sai», nhưng đề gốc ghi «Đúng»."},
{"id":"ipr-147","q":"The Mark used by one or more persons, other than the owner, to certify the region, materials, mode of manufacture, quality, or other characteristic of specific goods or services → Certification Mark","o":["True","False"],"a":[0],"m":"ipr","c":4,"n":147,"e":"Dấu hiệu do người không phải chủ sở hữu sử dụng để chứng nhận khu vực, nguyên liệu, chất lượng... là nhãn hiệu chứng nhận (certification mark): ghép đúng.","vi":{"q":"Dấu hiệu được một hoặc nhiều người không phải chủ sở hữu sử dụng để chứng nhận khu vực, nguyên liệu, phương thức sản xuất, chất lượng hoặc đặc tính khác của hàng hóa hay dịch vụ cụ thể → Nhãn hiệu chứng nhận (Certification Mark)","o":["Đúng","Sai"]}},
{"id":"ipr-148","q":"A patent application has been updated after it has been filed to incorporate new features.","o":["True","False"],"a":[1],"m":"ipr","c":6,"n":148,"e":"Đơn sáng chế sau khi nộp không được bổ sung tính năng mới (chỉ được sửa trong phạm vi đã bộc lộ), nên phát biểu là sai.","vi":{"q":"Đơn đăng ký sáng chế được cập nhật sau khi nộp để bổ sung các tính năng mới.","o":["Đúng","Sai"]}},
{"id":"ipr-149","q":"Before disclosing your graphic work which you have just created to any person, you","o":["(i) make an agreement with him/her thereby he/she promises not to disclose or misuse the graphic work without your permission","(ii) make sure you are not in infringement of any third person's IPRs if disclosing the graphic work","Neither (i) nor (ii)","Both (i) and (ii)"],"a":[3],"m":"ipr","c":1,"n":149,"f":1,"e":"Trước khi tiết lộ tác phẩm, cần có thỏa thuận bảo mật với người nhận và bảo đảm việc tiết lộ không xâm phạm quyền sở hữu trí tuệ của bên thứ ba; cả hai đều đúng.","vi":{"q":"Trước khi tiết lộ tác phẩm đồ họa bạn vừa tạo ra cho bất kỳ ai, bạn","o":["(i) lập thỏa thuận để người đó cam kết không tiết lộ hoặc lạm dụng tác phẩm đồ họa khi chưa có sự cho phép của bạn","(ii) bảo đảm rằng khi tiết lộ tác phẩm đồ họa, bạn không xâm phạm quyền sở hữu trí tuệ của bất kỳ bên thứ ba nào","Không phải (i) cũng không phải (ii)","Cả (i) và (ii)"]}},
{"id":"ipr-150","q":"Which of the following is not true","o":["Your friend gives you a copy of a drawing and you have reason to know that that copy has been taken without the copyright owner's consent. You bring this copy to UK. In this case, you commit secondary infringement of copyright","You import copies of cartoons into UK for your professional purpose and you have reason to know that those copies have been taken without copyright owner's permission. In this case, you commit secondary infringement of copyright","You import copies of cartoons into UK for your private collection and have reason to know that those copies have been taken without copyright owner's permission. In this case, you do not commit secondary infringement of copyright","You import copies of cartoons into UK for your private collection but you have no reason to believe that those copies have been taken without copyright owner's permission. In this case, you do not"],"a":[0],"m":"ipr","c":3,"n":150,"e":"Theo đáp án của đề, chọn {A} là phát biểu không đúng; xem cảnh báo bên dưới.","vi":{"q":"Điều nào sau đây không đúng?","o":["Bạn của bạn đưa cho bạn một bản sao bản vẽ và bạn có lý do để biết rằng bản sao đó được làm ra khi chưa có sự đồng ý của chủ sở hữu bản quyền. Bạn mang bản sao này vào Anh. Trong trường hợp này, bạn phạm tội vi phạm bản quyền thứ cấp","Bạn nhập khẩu các bản sao truyện tranh vào Anh cho mục đích chuyên môn và bạn có lý do để biết các bản sao đó được làm ra khi chưa có sự cho phép của chủ sở hữu bản quyền. Trong trường hợp này, bạn vi phạm bản quyền thứ cấp","Bạn nhập khẩu các bản sao truyện tranh vào Anh cho bộ sưu tập cá nhân và có lý do để biết các bản sao đó được làm ra khi chưa có sự cho phép của chủ sở hữu bản quyền. Trong trường hợp này, bạn không vi phạm bản quyền thứ cấp","Bạn nhập khẩu các bản sao truyện tranh vào Anh cho bộ sưu tập cá nhân nhưng không có lý do để tin rằng các bản sao đó được làm ra khi chưa có sự cho phép của chủ sở hữu bản quyền. Trong trường hợp này, bạn không"]},"k":"Đề gốc chọn {A}, nhưng theo luật Anh, mang bản sao vi phạm vào nước (không kinh doanh) là vi phạm thứ cấp nếu biết/có lý do biết (CDPA s.22–23); chỉ có {C} là phát biểu đáng ngờ."},
{"id":"ipr-151","q":"Under Berne Convention, in most cases, the copyright shall last for","o":["The author's life plus 70 years","The author's life","The author's life plus 50 years","70 years"],"a":[2],"m":"ipr","c":2,"n":151,"e":"Theo Công ước Berne, bản quyền thông thường kéo dài suốt đời tác giả cộng thêm 50 năm (mức tối thiểu).","vi":{"q":"Theo Công ước Berne, trong hầu hết các trường hợp, bản quyền kéo dài","o":["Suốt đời tác giả cộng thêm 70 năm","Suốt đời tác giả","Suốt đời tác giả cộng thêm 50 năm","70 năm"]}},
{"id":"ipr-152","q":"Which one of the followings is incorrect","o":["Injunction and delivery-up can be applied even in case the plaintiff suffers no damage.","Courts may apply provisional measures where any delay is likely to cause irreparable harm to the right holder.","Provisional measurers are applicable if there is a demonstrable risk of evidence being destroyed.","The combination of injunction and delivery-up is not available if there is no damage incurred to the plaintiff. -- applicable"],"a":[3],"m":"ipr","c":1,"n":152,"e":"Lệnh cấm và giao nộp hàng vi phạm có thể kết hợp ngay cả khi nguyên đơn không có thiệt hại, nên phát biểu {D} là không đúng.","vi":{"q":"Điều nào sau đây không đúng","o":["Lệnh cấm (injunction) và giao nộp hàng vi phạm (delivery-up) có thể áp dụng ngay cả khi nguyên đơn không bị thiệt hại.","Tòa án có thể áp dụng biện pháp khẩn cấp tạm thời khi sự chậm trễ có khả năng gây thiệt hại không thể khắc phục cho chủ sở hữu quyền.","Biện pháp khẩn cấp tạm thời được áp dụng nếu có nguy cơ rõ ràng là chứng cứ sẽ bị tiêu hủy.","Không thể kết hợp lệnh cấm và giao nộp hàng vi phạm nếu nguyên đơn không bị thiệt hại. -- áp dụng được"]}},
{"id":"ipr-153","q":"Regarding the novelty, relevant date may be (i) Filing date; (ii) Priority date","o":["(i) or (ii)","(i) and (ii)","Only (i)","Only (ii)"],"a":[0],"m":"ipr","c":6,"n":153,"f":1,"e":"Ngày liên quan để xét tính mới có thể là ngày nộp đơn hoặc ngày ưu tiên (nếu có yêu cầu ưu tiên).","vi":{"q":"Về tính mới (novelty), ngày liên quan có thể là (i) Ngày nộp đơn; (ii) Ngày ưu tiên","o":["(i) hoặc (ii)","(i) và (ii)","Chỉ (i)","Chỉ (ii)"]}},
{"id":"ipr-154","q":"Which one of the followings is not correct","o":["A part or parts of an article which connect it to another article shall not be protected by design right","Anyone can make exhaust system for a car","The fuse holder can be copied without permission","A method of construction is not protected by design right"],"a":[2],"m":"ipr","c":6,"n":154,"e":"Các bộ phận nối với sản phẩm khác (must-fit) bị loại khỏi quyền kiểu dáng; nên phát biểu «cả đế cầu chì có thể sao chép tự do» là không đúng.","vi":{"q":"Điều nào sau đây không đúng","o":["Một hoặc nhiều bộ phận của sản phẩm dùng để kết nối với sản phẩm khác sẽ không được bảo hộ bằng quyền kiểu dáng","Bất kỳ ai cũng có thể làm hệ thống ống xả cho ô tô","Có thể sao chép đế cầu chì mà không cần xin phép","Một phương pháp chế tạo không được bảo hộ bằng quyền kiểu dáng"]}},
{"id":"ipr-155","q":"Which of the followings is not correct?","o":["The applicant must list goods/services for which the trademarks to be used","The trademark which is registered in UK is automatically protected in Vietnam","Under Nice Agreement, goods are divided into 34 classes","The registration must be renewed by paying fee"],"a":[1],"m":"ipr","c":4,"n":155,"e":"Nhãn hiệu đăng ký ở Anh không tự động được bảo hộ ở Việt Nam, vì quyền sở hữu công nghiệp mang tính lãnh thổ.","vi":{"q":"Điều nào sau đây không đúng?","o":["Người nộp đơn phải liệt kê hàng hóa/dịch vụ sẽ sử dụng nhãn hiệu","Nhãn hiệu đã đăng ký ở Anh tự động được bảo hộ ở Việt Nam","Theo Thỏa ước Nice, hàng hóa được chia thành 34 nhóm","Việc đăng ký phải được gia hạn bằng cách nộp phí"]}},
{"id":"ipr-156","q":"In which case the designer owns rights in a registered design","o":["The designer created the design in the course of employment","The designer created the design under commission","The designer created the design at his own expenses for his own purpose","The designer assigns his registered design to another person"],"a":[2],"m":"ipr","c":6,"n":156,"e":"Theo đáp án của đề, nhà thiết kế sở hữu kiểu dáng khi tự thiết kế bằng chi phí của mình cho mục đích riêng.","vi":{"q":"Trong trường hợp nào nhà thiết kế sở hữu quyền đối với kiểu dáng đã đăng ký","o":["Nhà thiết kế tạo ra thiết kế trong quá trình làm việc theo hợp đồng lao động","Nhà thiết kế tạo ra thiết kế theo đơn đặt hàng","Nhà thiết kế tạo ra thiết kế bằng chi phí của mình cho mục đích riêng","Nhà thiết kế chuyển nhượng kiểu dáng đã đăng ký của mình cho người khác"]}},
{"id":"ipr-157","q":"Which of the followings is not true","o":["\"Flowers\" are not accepted to be registered for flowers","Distinctiveness must be evaluated in connection with the goods to which the trademark is applied","Common words cannot be used as distinctive signs","If a sign is not distinguishable, it cannot be treated as a trademark"],"a":[2],"m":"ipr","c":4,"n":157,"e":"Từ thông dụng vẫn có thể là dấu hiệu phân biệt nếu dùng cho hàng hóa không liên quan, ví dụ «Apple» cho máy tính; nên phát biểu {C} là sai.","vi":{"q":"Điều nào sau đây không đúng","o":["\"Flowers\" (hoa) không được chấp nhận đăng ký cho mặt hàng hoa","Tính phân biệt phải được đánh giá trong mối liên hệ với hàng hóa mà nhãn hiệu được áp dụng","Từ thông dụng không thể được dùng làm dấu hiệu phân biệt","Nếu một dấu hiệu không có khả năng phân biệt thì không thể được coi là nhãn hiệu"]}},
{"id":"ipr-158","q":"Article 50 of TRIPs requires courts or equivalent judicial authority to grant a provisional measure order accordingly the applicant's request (with out any request)","o":["True","False"],"a":[1],"m":"ipr","c":1,"n":158,"e":"Điều 50 TRIPS cho phép (chứ không bắt buộc) tòa án ra biện pháp khẩn cấp tạm thời, kể cả khi chưa nghe bên kia.","vi":{"q":"Điều 50 của TRIPS yêu cầu tòa án hoặc cơ quan tư pháp tương đương phải ban hành lệnh biện pháp khẩn cấp tạm thời theo yêu cầu của người nộp đơn (kể cả không có yêu cầu)","o":["Đúng","Sai"]}},
{"id":"ipr-159","q":"The author reserves the right to object any changes to his original work which would be prejudice to his honor or reputation.","o":["True","False"],"a":[0],"m":"ipr","c":2,"n":159,"e":"Đây là quyền toàn vẹn tác phẩm: tác giả được phản đối thay đổi gây hại danh dự, uy tín.","vi":{"q":"Tác giả bảo lưu quyền phản đối mọi sự thay đổi tác phẩm gốc của mình gây phương hại đến danh dự hoặc uy tín của họ.","o":["Đúng","Sai"]}},
{"id":"ipr-160","q":"Which of the followings may be distinctive","o":["A natural shape of a good","A single color","A new cartoon & a non-descriptive invented word","A functional shape"],"a":[2],"m":"ipr","c":4,"n":160,"e":"Nhân vật hoạt hình mới và từ tự đặt ra không mô tả có tính phân biệt; hình dạng tự nhiên, màu đơn, hình dạng chức năng thường không.","vi":{"q":"Điều nào sau đây có thể có tính phân biệt","o":["Hình dạng tự nhiên của hàng hóa","Một màu sắc đơn lẻ","Một nhân vật hoạt hình mới và một từ tự đặt ra không mang tính mô tả","Một hình dạng mang tính chức năng"]}},
{"id":"ipr-161","q":"If the design is put to practical use that means that the articles are made and sold, hired or advertised","o":["Its legal protection shall last for 10 years from the end of the year in which the articles are sold, hired or advertised","Its legal protection shall last for 05 years from the end of the year in which the articles are sold, hired or advertised","Its legal protection shall last for 15 years from the end of the year in which the articles are sold, hired or advertised","Its legal protection shall last for 20 years from the end of the year in which the articles are sold, hired or advertised"],"a":[0],"m":"ipr","c":6,"n":161,"e":"Khi thiết kế đã đưa vào sử dụng thực tế (bán, cho thuê, quảng cáo), quyền kiểu dáng kéo dài 10 năm kể từ cuối năm đó.","vi":{"q":"Nếu thiết kế được đưa vào sử dụng thực tế, nghĩa là sản phẩm được sản xuất và bán, cho thuê hoặc quảng cáo","o":["Sự bảo hộ pháp lý kéo dài 10 năm kể từ cuối năm mà sản phẩm được bán, cho thuê hoặc quảng cáo","Sự bảo hộ pháp lý kéo dài 05 năm kể từ cuối năm mà sản phẩm được bán, cho thuê hoặc quảng cáo","Sự bảo hộ pháp lý kéo dài 15 năm kể từ cuối năm mà sản phẩm được bán, cho thuê hoặc quảng cáo","Sự bảo hộ pháp lý kéo dài 20 năm kể từ cuối năm mà sản phẩm được bán, cho thuê hoặc quảng cáo"]}},
{"id":"ipr-162","q":"Surface decoration shall not be protected by any type of IPR.","o":["True","False"],"a":[1],"m":"ipr","c":6,"n":162,"e":"Phát biểu sai: trang trí bề mặt vẫn có thể được bảo hộ (bản quyền, kiểu dáng đã đăng ký) dù không thuộc quyền kiểu dáng.","vi":{"q":"Trang trí bề mặt không được bảo hộ bởi bất kỳ loại quyền sở hữu trí tuệ nào.","o":["Đúng","Sai"]}},
{"id":"ipr-163","q":"A registered design can not be protected by.........","o":["Copyright","Design right","Patent","Registered design"],"a":[1],"m":"ipr","c":1,"n":163,"e":"Kiểu dáng đã đăng ký và quyền kiểu dáng (không đăng ký) loại trừ nhau, nên kiểu dáng đã đăng ký không được bảo hộ đồng thời bằng quyền kiểu dáng.","vi":{"q":"Một kiểu dáng đã đăng ký không thể được bảo hộ bởi.........","o":["Bản quyền","Quyền kiểu dáng (design right)","Sáng chế","Kiểu dáng đã đăng ký"]}},
{"id":"ipr-164","q":"Copyright is protected............","o":["Everywhere in the world","By being registered","When the works in question is created","Only in the country where it is registered"],"a":[2],"m":"ipr","c":2,"n":164,"e":"Bản quyền phát sinh tự động khi tác phẩm được tạo ra, không cần đăng ký.","vi":{"q":"Bản quyền được bảo hộ............","o":["Ở mọi nơi trên thế giới","Bằng cách đăng ký","Khi tác phẩm được tạo ra","Chỉ ở quốc gia nơi nó được đăng ký"]}},
{"id":"ipr-165","q":"Simplifying a written story without consent of author is..........","o":["Infringement of copyright","Plagiarism","Passing off","False attribution"],"a":[0],"m":"ipr","c":3,"n":165,"e":"Rút gọn câu chuyện là chuyển thể tác phẩm, hành vi thuộc quyền độc quyền nên xâm phạm bản quyền.","vi":{"q":"Rút gọn một câu chuyện đã viết mà không có sự đồng ý của tác giả là..........","o":["Xâm phạm bản quyền","Đạo văn (plagiarism)","Passing off","Gán sai tác giả"]}},
{"id":"ipr-166","q":"The owner of copyright of a music sound recording is the...........","o":["Author","Singer","Producer","Recorder"],"a":[2],"m":"ipr","c":2,"n":166,"e":"Chủ sở hữu bản quyền bản ghi âm là nhà sản xuất (người sắp xếp để thực hiện bản ghi).","vi":{"q":"Chủ sở hữu bản quyền của một bản ghi âm nhạc là...........","o":["Tác giả","Ca sĩ","Nhà sản xuất","Người ghi âm"]}},
{"id":"ipr-167","q":"The author of copyright of a writing is.......","o":["The person who provides ideas for this writing","The person who expresses this writing","Both the person who provide ideas for and express this writing","The person who copying this writing"],"a":[1],"m":"ipr","c":2,"n":167,"e":"Tác giả là người thể hiện (viết ra) tác phẩm, không phải người chỉ cung cấp ý tưởng.","vi":{"q":"Tác giả của một tác phẩm viết là.......","o":["Người cung cấp ý tưởng cho tác phẩm này","Người thể hiện (viết ra) tác phẩm này","Cả người cung cấp ý tưởng lẫn người thể hiện tác phẩm này","Người sao chép tác phẩm này"]}},
{"id":"ipr-168","q":"To apply for a patent, an inventor must......","o":["File an application at a patent office which must comply with formal and technical requirements","Demonstrate that their invention works","State the date on which the invention was first \"reduced to practice\"","Apply it"],"a":[0],"m":"ipr","c":6,"n":168,"e":"Muốn có bằng sáng chế phải nộp đơn tại cơ quan sáng chế và đáp ứng các yêu cầu về hình thức và kỹ thuật.","vi":{"q":"Để xin cấp bằng sáng chế, nhà sáng chế phải......","o":["Nộp đơn tại cơ quan sáng chế, đơn phải tuân thủ các yêu cầu về hình thức và kỹ thuật","Chứng minh rằng sáng chế của mình hoạt động được","Nêu ngày sáng chế lần đầu được \"đưa vào thực tiễn\" (reduced to practice)","Áp dụng nó"]}},
{"id":"ipr-169","q":"A design has individual character if","o":["It appeals to the eye of the ordinary consumer","It gives a different overall impression, when compared with prior designs, to someone who is an interested consumer for the products in question","The difference over previous designs are not trivial","Every one can find the difference between this design and others"],"a":[1],"m":"ipr","c":6,"n":169,"e":"Tính độc đáo riêng nghĩa là thiết kế tạo ấn tượng tổng thể khác biệt đối với người dùng am hiểu khi so với thiết kế có trước.","vi":{"q":"Một thiết kế có tính độc đáo riêng (individual character) nếu","o":["Nó hấp dẫn thị giác của người tiêu dùng bình thường","Nó tạo ra ấn tượng tổng thể khác biệt khi so với các thiết kế có trước, đối với người tiêu dùng quan tâm đến sản phẩm đó","Những khác biệt so với thiết kế trước đó không đáng kể","Ai cũng có thể thấy sự khác biệt giữa thiết kế này và các thiết kế khác"]}},
{"id":"ipr-170","q":"Design right.......","o":["Can arise however the design is created and regardless of whether or not any copyright arises","Apply to the individual elements of a design","Only protects the visible parts of designs","Is only applied upon registration"],"a":[0],"m":"ipr","c":6,"n":170,"e":"Quyền kiểu dáng phát sinh tự động khi tạo ra thiết kế, không cần đăng ký và không phụ thuộc việc có bản quyền hay không.","vi":{"q":"Quyền kiểu dáng (design right).......","o":["Có thể phát sinh dù thiết kế được tạo ra theo cách nào và bất kể có phát sinh bản quyền hay không","Áp dụng cho từng yếu tố riêng lẻ của thiết kế","Chỉ bảo hộ các phần nhìn thấy được của thiết kế","Chỉ được áp dụng khi đã đăng ký"]}},
{"id":"ipr-171","q":"Which of these events potentially triggers the right of attribution","o":["Broadcasting a recording of a song on the radio","Uploading a song to a file-sharing website","Broadcasting a recitation of a poem on the radio","Using a song in a film"],"a":[2],"m":"ipr","c":2,"n":171,"e":"Quyền được nhận là tác giả được kích hoạt khi tác phẩm văn học (bài thơ) được phát thanh công khai.","vi":{"q":"Sự kiện nào sau đây có thể kích hoạt quyền được nhận là tác giả (right of attribution)","o":["Phát một bản ghi bài hát trên đài phát thanh","Tải một bài hát lên trang web chia sẻ tệp","Phát thanh một bài ngâm thơ trên đài","Sử dụng một bài hát trong phim"]}},
{"id":"ipr-172","q":"Which of the followings is not a category of copyright?","o":["Literary works","Sculpture","Furniture","Computer progammes"],"a":[2],"m":"ipr","c":2,"n":172,"e":"Đồ nội thất (nói chung) không phải loại tác phẩm bản quyền; tác phẩm văn học, điêu khắc và chương trình máy tính thì phải.","vi":{"q":"Điều nào sau đây không phải là một loại tác phẩm được bảo hộ bản quyền?","o":["Tác phẩm văn học","Điêu khắc","Đồ nội thất","Chương trình máy tính"]}},
{"id":"ipr-173","q":"Which of the following is not \"use in the course of trade\"?","o":["Fixing the sign to goods","Fixing the sign to the business paper","Presenting the sign for teaching purpose","Selling the goods under the sign"],"a":[2],"m":"ipr","c":4,"n":173,"e":"Dùng dấu hiệu cho mục đích giảng dạy không phải sử dụng trong hoạt động thương mại.","vi":{"q":"Điều nào sau đây không phải là \"sử dụng trong hoạt động thương mại\" (use in the course of trade)?","o":["Gắn dấu hiệu lên hàng hóa","Gắn dấu hiệu lên giấy tờ kinh doanh","Trình bày dấu hiệu cho mục đích giảng dạy","Bán hàng hóa dưới dấu hiệu đó"]}},
{"id":"ipr-174","q":"What is the correct statement about 'originality'?","o":["Originality means 'not copied' and nothing more","Originality requires creative effort","Originality means that the creator does not copy others' work and has contributed skill or labour.","Originality means being totally new"],"a":[2],"m":"ipr","c":2,"n":174,"e":"Tính nguyên gốc nghĩa là không sao chép và có đóng góp kỹ năng hoặc công sức lao động, không đòi hỏi hoàn toàn mới.","vi":{"q":"Phát biểu nào đúng về tính nguyên gốc (originality)?","o":["Tính nguyên gốc nghĩa là 'không sao chép' và không hơn","Tính nguyên gốc đòi hỏi nỗ lực sáng tạo","Tính nguyên gốc nghĩa là người sáng tạo không sao chép tác phẩm của người khác và đã đóng góp kỹ năng hoặc công sức lao động.","Tính nguyên gốc nghĩa là hoàn toàn mới"]}},
{"id":"ipr-175","q":"Which of the followings is NOT a requirement for passing off?","o":["Confusion","Within geographical area","Damages","Providing similar product"],"a":[1],"m":"ipr","c":5,"n":175,"e":"Passing off cần nhầm lẫn, thiệt hại và uy tín; không bắt buộc có giới hạn địa lý cụ thể.","vi":{"q":"Điều nào sau đây KHÔNG phải là yếu tố bắt buộc của passing off?","o":["Sự nhầm lẫn","Trong phạm vi khu vực địa lý","Thiệt hại","Cung cấp sản phẩm tương tự"]}},
{"id":"ipr-176","q":"The requirement of proof of reputation is applied for the protection of......","o":["Registered trade mark","Unregistered trade mark","Both registered and unregistered trade mark","Any trademark"],"a":[1],"m":"ipr","c":5,"n":176,"e":"Yêu cầu chứng minh uy tín áp dụng khi bảo hộ nhãn hiệu chưa đăng ký (nhãn hiệu đã đăng ký được bảo hộ nhờ đăng ký).","vi":{"q":"Yêu cầu chứng minh uy tín được áp dụng để bảo hộ......","o":["Nhãn hiệu đã đăng ký","Nhãn hiệu chưa đăng ký","Cả nhãn hiệu đã đăng ký lẫn chưa đăng ký","Bất kỳ nhãn hiệu nào"]}},
{"id":"ipr-177","q":"Unregistered trade mark..........","o":["Can not be protected by IP law","Can be protected by IP law upon the satisfaction of requirements","Can be protected by IP law in all cases","Can be protected by IP law in limited area"],"a":[1],"m":"ipr","c":5,"n":177,"e":"Nhãn hiệu chưa đăng ký có thể được bảo hộ (qua passing off) nếu đáp ứng điều kiện.","vi":{"q":"Nhãn hiệu chưa đăng ký..........","o":["Không thể được bảo hộ bởi luật sở hữu trí tuệ","Có thể được bảo hộ bởi luật sở hữu trí tuệ khi đáp ứng các điều kiện","Có thể được bảo hộ bởi luật sở hữu trí tuệ trong mọi trường hợp","Có thể được bảo hộ bởi luật sở hữu trí tuệ trong phạm vi khu vực hạn chế"]}},
{"id":"ipr-178","q":"Passing off refers to infringement of......","o":["Registered trade mark","Unregistered trade mark","Both registered and unregistered trademark","Neither registered nor unregistered trademark"],"a":[1],"m":"ipr","c":5,"n":178,"e":"Theo đáp án của đề, passing off liên quan đến nhãn hiệu chưa đăng ký; nhãn hiệu đã đăng ký được bảo vệ bằng quy định xâm phạm nhãn hiệu.","vi":{"q":"Passing off là hành vi xâm phạm......","o":["Nhãn hiệu đã đăng ký","Nhãn hiệu chưa đăng ký","Cả nhãn hiệu đã đăng ký lẫn chưa đăng ký","Không phải nhãn hiệu đã đăng ký cũng không phải chưa đăng ký"]}},
{"id":"ipr-179","q":"What is NOT \"get-up\" of a well-known bakery shop?","o":["Client","Packaging","Decoration style","Name"],"a":[0],"m":"ipr","c":5,"n":179,"e":"Get-up là diện mạo thương mại gồm bao bì, phong cách trang trí, tên...; khách hàng không thuộc get-up.","vi":{"q":"Điều nào KHÔNG phải là \"get-up\" (diện mạo thương mại) của một tiệm bánh nổi tiếng?","o":["Khách hàng","Bao bì","Phong cách trang trí","Tên"]}},
{"id":"ipr-180","q":"Protected trade marks include....","o":["Registered trade marks","Unregistered trademarks","Both registered and unregistered trademark","All marks in the market of one specific country"],"a":[2],"m":"ipr","c":5,"n":180,"e":"Nhãn hiệu được bảo hộ gồm cả nhãn hiệu đã đăng ký và chưa đăng ký (đáp ứng điều kiện).","vi":{"q":"Các nhãn hiệu được bảo hộ gồm....","o":["Nhãn hiệu đã đăng ký","Nhãn hiệu chưa đăng ký","Cả nhãn hiệu đã đăng ký lẫn chưa đăng ký","Tất cả các nhãn hiệu trên thị trường của một quốc gia cụ thể"]}},
{"id":"ipr-181","q":"Trade mark includes......","o":["Only registered trade mark","Only unregistered trade mark","Both registered and unregistered trademark","Neither registered nor unregistered trademark"],"a":[2],"m":"ipr","c":5,"n":181,"e":"Khái niệm nhãn hiệu bao gồm cả nhãn hiệu đã đăng ký và chưa đăng ký.","vi":{"q":"Nhãn hiệu bao gồm......","o":["Chỉ nhãn hiệu đã đăng ký","Chỉ nhãn hiệu chưa đăng ký","Cả nhãn hiệu đã đăng ký lẫn chưa đăng ký","Không phải nhãn hiệu đã đăng ký cũng không phải chưa đăng ký"]}},
{"id":"ipr-182","q":"Using a trade mark in a different writing style is...........","o":["An infringement of trade mark","Not a primary infringement of trade mark","Not a secondary infringement of trade mark","An infringement of copyright"],"a":[0],"m":"ipr","c":5,"n":182,"e":"Đổi kiểu chữ không làm hết sự giống nhau gây nhầm lẫn nên vẫn xâm phạm nhãn hiệu.","vi":{"q":"Sử dụng một nhãn hiệu với kiểu chữ khác là...........","o":["Hành vi xâm phạm nhãn hiệu","Không phải vi phạm trực tiếp nhãn hiệu","Không phải vi phạm thứ cấp nhãn hiệu","Xâm phạm bản quyền"]}},
{"id":"ipr-183","q":"A tool kit can not be protected by.........","o":["Copyright","Patent","Design right","Registered design"],"a":[0],"m":"ipr","c":1,"n":183,"e":"Bộ dụng cụ là sản phẩm kỹ thuật, không phải tác phẩm văn học/nghệ thuật nên không được bảo hộ bản quyền; có thể được bảo hộ bằng sáng chế, kiểu dáng.","vi":{"q":"Một bộ dụng cụ (tool kit) không thể được bảo hộ bởi.........","o":["Bản quyền","Sáng chế","Quyền kiểu dáng","Kiểu dáng đã đăng ký"]}},
{"id":"ipr-184","q":"In case \"Apple\" is registered as trade mark of Apple Inc., the trade mark \"Apple\".......","o":["Can not be used by a company producing computer and phone","Can not be printed in a T-shirt","Can not be used by a company selling apple","Can not be used by any company"],"a":[0],"m":"ipr","c":4,"n":184,"e":"«Apple» đã đăng ký cho máy tính/điện thoại thì công ty khác cùng loại hàng hóa không được dùng; công ty bán táo hay in áo thun thì khác lĩnh vực.","vi":{"q":"Trong trường hợp \"Apple\" đã được đăng ký làm nhãn hiệu của Apple Inc., nhãn hiệu \"Apple\".......","o":["Không thể được dùng bởi công ty sản xuất máy tính và điện thoại","Không thể được in lên áo thun","Không thể được dùng bởi công ty bán táo","Không thể được dùng bởi bất kỳ công ty nào"]}},
{"id":"ipr-185","q":"A registered trade mark of one goods.........","o":["Can not be registered as trade mark of other goods in different classes","Can not be registered as trade mark of services","Can not be registered as trademark of other goods in the same class","Can not be registered as trade mark of any service and goods"],"a":[2],"m":"ipr","c":4,"n":185,"e":"Nhãn hiệu đã đăng ký cho hàng hóa trong một nhóm thì không đăng ký lại làm nhãn hiệu cho hàng hóa khác trong cùng nhóm.","vi":{"q":"Một nhãn hiệu đã đăng ký cho một loại hàng hóa.........","o":["Không thể được đăng ký làm nhãn hiệu cho hàng hóa khác thuộc nhóm khác","Không thể được đăng ký làm nhãn hiệu cho dịch vụ","Không thể được đăng ký làm nhãn hiệu cho hàng hóa khác trong cùng nhóm","Không thể được đăng ký làm nhãn hiệu cho bất kỳ dịch vụ và hàng hóa nào"]}},
{"id":"ipr-186","q":"To be registered as a trade mark, a term must......","o":["Be distinctive","Not indicate the type, quality, purpose or geographical origin of the goods","Both distinctive and indicate the type, quality, purpose or geographical origin of the goods","Be meaningful"],"a":[2],"m":"ipr","c":4,"n":186,"e":"Theo đáp án của đề chọn {C}. Thực ra luật yêu cầu nhãn hiệu có tính phân biệt VÀ không chỉ ra loại, chất lượng, mục đích, nguồn gốc hàng hóa; xem cảnh báo bên dưới.","vi":{"q":"Để được đăng ký làm nhãn hiệu, một thuật ngữ phải......","o":["Có tính phân biệt","Không chỉ ra loại, chất lượng, mục đích hoặc nguồn gốc địa lý của hàng hóa","Vừa có tính phân biệt vừa chỉ ra loại, chất lượng, mục đích hoặc nguồn gốc địa lý của hàng hóa","Có ý nghĩa"]},"k":"Phương án {C} tự mâu thuẫn với {B} (nhãn hiệu KHÔNG được chỉ ra loại, chất lượng, mục đích, nguồn gốc địa lý của hàng hóa). Ý đúng của luật là {A} + {B} cùng lúc; nhiều khả năng đề gốc gõ nhầm chữ «indicate»."},
{"id":"ipr-187","q":"A trade mark can be........","o":["A word","A symbol","A smell","An invented word, a symbol and a smell"],"a":[3],"m":"ipr","c":4,"n":187,"e":"Nhãn hiệu có thể là từ, biểu tượng, mùi, hoặc từ tự đặt ra; đề chọn đáp án gộp tất cả.","vi":{"q":"Một nhãn hiệu có thể là........","o":["Một từ","Một biểu tượng","Một mùi","Một từ tự đặt ra, một biểu tượng và một mùi"]}},
{"id":"ipr-188","q":"The term \"Gala Apple\" could be refused to be a trade mark because.....","o":["It is not pronounceable","It indicates the nature of one type of apple","It is an invented word","It is not clear"],"a":[1],"m":"ipr","c":4,"n":188,"e":"«Gala Apple» chỉ ra bản chất một giống táo (mô tả hàng hóa) nên có thể bị từ chối.","vi":{"q":"Thuật ngữ \"Gala Apple\" có thể bị từ chối làm nhãn hiệu vì.....","o":["Nó không phát âm được","Nó chỉ ra bản chất của một loại táo","Nó là từ tự đặt ra","Nó không rõ ràng"]}},
{"id":"ipr-189","q":"Which of the followings is correct?","o":["Trade mark must be a word in English","Trade mark must be an invented word","Trade mark could be a symbol","Trade mark must be pronounceable"],"a":[2],"m":"ipr","c":4,"n":189,"e":"Nhãn hiệu có thể là biểu tượng; không bắt buộc là từ tiếng Anh, từ tự đặt ra hay phát âm được.","vi":{"q":"Điều nào sau đây đúng?","o":["Nhãn hiệu phải là một từ tiếng Anh","Nhãn hiệu phải là một từ tự đặt ra","Nhãn hiệu có thể là một biểu tượng","Nhãn hiệu phải phát âm được"]}},
{"id":"ipr-190","q":"As the term \"BM Apple\" as registered as a trade mark of a company selling apples, the term \"BN Apple\".........","o":["Can not be registered as a trade mark of a company selling apples","Still can be registered as a trade mark of a company selling apples","Can be registered as a trademark of all company","Can not be registered as a trademark of any company"],"a":[0],"m":"ipr","c":4,"n":190,"e":"«BN Apple» quá giống «BM Apple» đã đăng ký cho cùng loại hàng (táo), có nguy cơ gây nhầm lẫn nên không đăng ký được.","vi":{"q":"Vì thuật ngữ \"BM Apple\" đã được đăng ký làm nhãn hiệu của một công ty bán táo, thuật ngữ \"BN Apple\".........","o":["Không thể được đăng ký làm nhãn hiệu của một công ty bán táo","Vẫn có thể được đăng ký làm nhãn hiệu của một công ty bán táo","Có thể được đăng ký làm nhãn hiệu của mọi công ty","Không thể được đăng ký làm nhãn hiệu của bất kỳ công ty nào"]}},
{"id":"ipr-191","q":"The term \"Apple\" can NOT be a trade mark of........","o":["Any business","Any business selling apples","Any business selling smartphones","Any business selling computers"],"a":[1],"m":"ipr","c":4,"n":191,"e":"«Apple» là từ mô tả khi dùng cho táo nên không thể là nhãn hiệu của doanh nghiệp bán táo; nhưng dùng cho điện thoại, máy tính thì được.","vi":{"q":"Thuật ngữ \"Apple\" KHÔNG thể là nhãn hiệu của........","o":["Bất kỳ doanh nghiệp nào","Bất kỳ doanh nghiệp nào bán táo","Bất kỳ doanh nghiệp nào bán điện thoại thông minh","Bất kỳ doanh nghiệp nào bán máy tính"]}},
{"id":"ipr-192","q":"An unregistered trade mark shall be.....","o":["Fully protected","Partly protected","Not protected","Full protected within limited period"],"a":[1],"m":"ipr","c":5,"n":192,"e":"Nhãn hiệu chưa đăng ký chỉ được bảo hộ một phần, thông qua passing off và khi chứng minh được uy tín.","vi":{"q":"Nhãn hiệu chưa đăng ký sẽ được.....","o":["Bảo hộ đầy đủ","Bảo hộ một phần","Không được bảo hộ","Bảo hộ đầy đủ trong một thời hạn giới hạn"]}},
{"id":"ipr-193","q":"Business methods are.......","o":["patentable in the US but not patentable in the UK","not patentable in both UK and US","patentable in both UK and US","Not patentable anywhere"],"a":[0],"m":"ipr","c":6,"n":193,"e":"Phương pháp kinh doanh có thể được cấp bằng sáng chế ở Mỹ nhưng không ở Anh (bị loại trừ).","vi":{"q":"Phương pháp kinh doanh (business methods) là.......","o":["có thể được cấp bằng sáng chế ở Mỹ nhưng không thể ở Anh","không thể được cấp bằng sáng chế ở cả Anh lẫn Mỹ","có thể được cấp bằng sáng chế ở cả Anh lẫn Mỹ","Không thể được cấp bằng sáng chế ở bất cứ đâu"]}},
{"id":"ipr-194","q":"An exception to patent infringement is......","o":["Using the patented invention on behalf of the government","Selling a patented product for non-commercial use","Copying that patent for personal use","Using that patent for public use"],"a":[0],"m":"ipr","c":6,"n":194,"e":"Sử dụng sáng chế thay mặt chính phủ (Crown use) là ngoại lệ đối với xâm phạm sáng chế.","vi":{"q":"Một ngoại lệ đối với hành vi xâm phạm sáng chế là......","o":["Sử dụng sáng chế đã được cấp bằng thay mặt chính phủ","Bán sản phẩm được cấp bằng sáng chế cho mục đích phi thương mại","Sao chép sáng chế đó để dùng cho cá nhân","Sử dụng sáng chế đó cho mục đích công cộng"]}},
{"id":"ipr-195","q":"A patent is infringed..........","o":["Only when every feature within at least one claim is used in the allegedly infringing article or process","When some features are used in the allegedly infringing article or process","The allegedly infringing article or process looks like the patented one","The allegedly infringing article or process is developed from the patented one with consent of"],"a":[0],"m":"ipr","c":6,"n":195,"e":"Sáng chế bị xâm phạm chỉ khi mọi đặc điểm trong ít nhất một điểm yêu cầu bảo hộ (claim) đều được dùng trong sản phẩm hoặc quy trình bị kiện.","vi":{"q":"Một sáng chế bị xâm phạm..........","o":["Chỉ khi mọi đặc điểm trong ít nhất một điểm yêu cầu bảo hộ (claim) đều được sử dụng trong sản phẩm hoặc quy trình bị cho là xâm phạm","Khi một số đặc điểm được sử dụng trong sản phẩm hoặc quy trình bị cho là xâm phạm","Sản phẩm hoặc quy trình bị cho là xâm phạm trông giống sản phẩm được cấp bằng","Sản phẩm hoặc quy trình bị cho là xâm phạm được phát triển từ sản phẩm được cấp bằng với sự đồng ý của"]}},
{"id":"ipr-196","q":"Manufacturing an article protected only by a UK granted patent in China is.......","o":["A secondary infringement","A primary infringement","Not an infringement of patent","An infringement of IP rights"],"a":[2],"m":"ipr","c":6,"n":196,"e":"Sáng chế do Anh cấp chỉ có hiệu lực ở Anh (tính lãnh thổ), nên sản xuất ở Trung Quốc không xâm phạm.","vi":{"q":"Sản xuất ở Trung Quốc một sản phẩm chỉ được bảo hộ bởi bằng sáng chế do Anh cấp là.......","o":["Vi phạm thứ cấp","Vi phạm trực tiếp","Không phải xâm phạm sáng chế","Xâm phạm quyền sở hữu trí tuệ"]}},
{"id":"ipr-197","q":"A patent granted in the one country has legal effect.......","o":["Worldwide","only in the country of registration","in the European Union","in country of nationality of the owner"],"a":[1],"m":"ipr","c":6,"n":197,"e":"Sáng chế được cấp ở một quốc gia chỉ có hiệu lực pháp lý tại quốc gia đó.","vi":{"q":"Bằng sáng chế được cấp ở một quốc gia có hiệu lực pháp lý.......","o":["Trên toàn thế giới","chỉ ở quốc gia đăng ký","trong Liên minh châu Âu","ở quốc gia mang quốc tịch của chủ sở hữu"]}},
{"id":"ipr-198","q":"One of the requirements for an invention to be patented is.......","o":["Having individual character","Not being obvious","Being artistic","Being original"],"a":[1],"m":"ipr","c":6,"n":198,"e":"Sáng chế phải mới, có trình độ sáng tạo (không hiển nhiên) và có khả năng áp dụng công nghiệp.","vi":{"q":"Một trong các điều kiện để một sáng chế được cấp bằng là.......","o":["Có tính độc đáo riêng (individual character)","Không hiển nhiên (có trình độ sáng tạo)","Mang tính nghệ thuật","Mang tính nguyên gốc"]}},
{"id":"ipr-199","q":"Which of the followings can be patented?","o":["Mathematical method","Presentation of information","New materials","Scientific theory"],"a":[2],"m":"ipr","c":6,"n":199,"e":"Vật liệu mới có thể được cấp bằng sáng chế; phương pháp toán học, cách trình bày thông tin, lý thuyết khoa học thì bị loại trừ.","vi":{"q":"Điều nào sau đây có thể được cấp bằng sáng chế?","o":["Phương pháp toán học","Cách trình bày thông tin","Vật liệu mới","Lý thuyết khoa học"]}},
{"id":"ipr-200","q":"When a machine is protected by registered design, the drawing of this machine is.....","o":["Also protected by registered design","Not protected by IP rights","protected by copyright","Protected by patent"],"a":[2],"m":"ipr","c":6,"n":200,"e":"Bản vẽ của cỗ máy là tác phẩm đồ họa nên được bảo hộ bản quyền, khác với bản thân cỗ máy.","vi":{"q":"Khi một cỗ máy được bảo hộ bằng kiểu dáng đã đăng ký, bản vẽ của cỗ máy này.....","o":["Cũng được bảo hộ bằng kiểu dáng đã đăng ký","Không được bảo hộ bởi quyền sở hữu trí tuệ","được bảo hộ bằng bản quyền","Được bảo hộ bằng sáng chế"]}},
{"id":"ipr-201","q":"Once a design is registered in the UK, it will be protected.....","o":["worldwide","Only in the UK","In any country where such registration is applied","Outside of the UK"],"a":[2],"m":"ipr","c":6,"n":201,"e":"Theo đáp án của đề, kiểu dáng được bảo hộ ở bất kỳ nước nào có nộp đơn đăng ký tương ứng; xem cảnh báo bên dưới về tính lãnh thổ.","vi":{"q":"Khi một kiểu dáng đã được đăng ký ở Anh, nó sẽ được bảo hộ.....","o":["trên toàn thế giới","Chỉ ở Anh","Ở bất kỳ quốc gia nào có nộp đơn đăng ký tương ứng","Bên ngoài nước Anh"]},"k":"Quyền kiểu dáng đã đăng ký mang tính lãnh thổ: đăng ký ở Anh chỉ có hiệu lực ở Anh (như câu #197 về sáng chế), nên phương án {B} nghe hợp lý hơn. Đề chọn {C} (hiểu là «ở mỗi nước đã nộp đơn đăng ký tương ứng»)."},
{"id":"ipr-202","q":"To be protected by design right, an article must NOT.....","o":["Be original","Be non-commonplace","Have an individual character","be original and non-commonplace"],"a":[2],"m":"ipr","c":6,"n":202,"e":"Quyền kiểu dáng yêu cầu thiết kế nguyên gốc và không tầm thường; «tính độc đáo riêng» là điều kiện của kiểu dáng đã đăng ký.","vi":{"q":"Để được bảo hộ bằng quyền kiểu dáng (design right), một sản phẩm KHÔNG cần.....","o":["Nguyên gốc (original)","Không tầm thường (non-commonplace)","Có tính độc đáo riêng (individual character)","nguyên gốc và không tầm thường"]}},
{"id":"ipr-203","q":"The protection of design right is applied..........","o":["To all original and non-commonplace articles","To only registered articles","To only some technical objects","To only some artistic works"],"a":[0],"m":"ipr","c":6,"n":203,"e":"Quyền kiểu dáng áp dụng cho mọi sản phẩm nguyên gốc và không tầm thường, không cần đăng ký.","vi":{"q":"Sự bảo hộ của quyền kiểu dáng được áp dụng..........","o":["Cho mọi sản phẩm nguyên gốc và không tầm thường","Chỉ cho các sản phẩm đã đăng ký","Chỉ cho một số đối tượng kỹ thuật","Chỉ cho một số tác phẩm nghệ thuật"]}},
{"id":"ipr-204","q":"An article of company X was designed by its employee.- Mr. Y. Two years later, X transfers design right of this article to other company without consent of Y. Such transfer is.....","o":["A secondary infringement of design right","A primary infringement of design right","Not an infringement of design right","An infringement of copyright"],"a":[2],"m":"ipr","c":6,"n":204,"e":"Thiết kế do nhân viên tạo ra trong công việc thuộc về nhà tuyển dụng, nên công ty X chuyển nhượng không cần sự đồng ý của nhân viên và không xâm phạm.","vi":{"q":"Một sản phẩm của Công ty X do nhân viên của công ty là ông Y thiết kế. Hai năm sau, X chuyển nhượng quyền kiểu dáng của sản phẩm này cho công ty khác mà không có sự đồng ý của Y. Việc chuyển nhượng đó là.....","o":["Vi phạm thứ cấp quyền kiểu dáng","Vi phạm trực tiếp quyền kiểu dáng","Không phải xâm phạm quyền kiểu dáng","Xâm phạm bản quyền"]}},
{"id":"ipr-205","q":"Buying a toy car being protected by registered design is.......","o":["A secondary infringement of design right","A primary infringement of design right","Not an infringement of design right","An infringement of copyright"],"a":[2],"m":"ipr","c":6,"n":205,"e":"Mua một chiếc ô tô đồ chơi đã được làm ra hợp pháp là hành vi của người tiêu dùng, không phải xâm phạm.","vi":{"q":"Mua một chiếc ô tô đồ chơi được bảo hộ bằng kiểu dáng đã đăng ký là.......","o":["Vi phạm thứ cấp quyền kiểu dáng","Vi phạm trực tiếp quyền kiểu dáng","Không phải xâm phạm quyền kiểu dáng","Xâm phạm bản quyền"]}},
{"id":"ipr-206","q":"Infringement of design right occurs when.......","o":["It exists two similar designs","It is shown that the alleged copyist had access to the design in question","The activity of copying is proven","The design in concerned is registered"],"a":[1],"m":"ipr","c":6,"n":206,"e":"Theo đáp án của đề, chọn «chứng minh người sao chép đã tiếp cận thiết kế»; xem cảnh báo bên dưới.","vi":{"q":"Xâm phạm quyền kiểu dáng xảy ra khi.......","o":["Tồn tại hai thiết kế tương tự nhau","Chứng minh được rằng người bị cáo buộc sao chép đã có cơ hội tiếp cận thiết kế đang xét","Hành vi sao chép được chứng minh","Thiết kế đang xét đã được đăng ký"]},"k":"Đề chọn {B} (đã tiếp cận thiết kế). Tuy nhiên yếu tố then chốt của xâm phạm quyền kiểu dáng là có hành vi sao chép (phương án {C}, xem thêm #67); tiếp cận chỉ là bằng chứng để suy ra sao chép."},
{"id":"ipr-207","q":"A machine with artificial intelligence created a 3D sculpture. The owner of design right of this sculpture is......","o":["This machine","The person by whom the arrangements necessary for the creation of the design are undertaken","Nobody","Public"],"a":[1],"m":"ipr","c":6,"n":207,"e":"Với thiết kế do máy tính tạo ra, chủ sở hữu là người thực hiện các sắp đặt cần thiết cho việc tạo ra thiết kế.","vi":{"q":"Một cỗ máy có trí tuệ nhân tạo đã tạo ra một tác phẩm điêu khắc 3D. Chủ sở hữu quyền kiểu dáng của tác phẩm điêu khắc này là......","o":["Chính cỗ máy này","Người đã thực hiện các sắp đặt cần thiết cho việc tạo ra thiết kế","Không ai cả","Công chúng"]}},
{"id":"ipr-208","q":"Design right applies when......","o":["The design is recorded","The design is registered","The design is published","The design is showed"],"a":[0],"m":"ipr","c":6,"n":208,"e":"Quyền kiểu dáng phát sinh ngay khi thiết kế được ghi lại (recorded) bằng bản vẽ hoặc tạo ra sản phẩm mẫu.","vi":{"q":"Quyền kiểu dáng (design right) phát sinh khi......","o":["Thiết kế được ghi lại (recorded)","Thiết kế được đăng ký","Thiết kế được công bố","Thiết kế được trưng bày"]}},
{"id":"ipr-209","q":"The design of contact lenses can..........","o":["Be protected by design rights","Not be protected by design rights","Be protected by patent","Not be protected by patent"],"a":[1],"m":"ipr","c":6,"n":209,"e":"Thiết kế kính áp tròng không được bảo hộ bằng quyền kiểu dáng theo đáp án của đề.","vi":{"q":"Thiết kế của kính áp tròng có thể..........","o":["Được bảo hộ bằng quyền kiểu dáng","Không được bảo hộ bằng quyền kiểu dáng","Được bảo hộ bằng sáng chế","Không được bảo hộ bằng sáng chế"]}},
{"id":"ipr-210","q":"A triangle eyeglasses box can be protected by............","o":["Design rights","Copyright","Patent","Trademark"],"a":[0],"m":"ipr","c":6,"n":210,"e":"Hộp đựng kính hình tam giác là vật thể ba chiều nên được bảo hộ bằng quyền kiểu dáng.","vi":{"q":"Một chiếc hộp đựng kính mắt hình tam giác có thể được bảo hộ bởi............","o":["Quyền kiểu dáng","Bản quyền","Sáng chế","Nhãn hiệu"]}},
{"id":"ipr-211","q":"Computer programmes can be protected by.........","o":["Design rights","Copyright","Trademark","Patent"],"a":[1],"m":"ipr","c":2,"n":211,"e":"Chương trình máy tính được bảo hộ bản quyền như tác phẩm văn học.","vi":{"q":"Chương trình máy tính có thể được bảo hộ bởi.........","o":["Quyền kiểu dáng","Bản quyền","Nhãn hiệu","Sáng chế"]}},
{"id":"ipr-212","q":"To be protected by copyright, a creative work must be......","o":["Fixed in a tangible medium","original","both original and fixed in a tangible medium","Spoken"],"a":[2],"m":"ipr","c":2,"n":212,"e":"Tác phẩm phải nguyên gốc và được cố định trên một phương tiện hữu hình mới được bảo hộ bản quyền.","vi":{"q":"Để được bảo hộ bản quyền, một tác phẩm sáng tạo phải......","o":["Được cố định trên phương tiện hữu hình","nguyên gốc (original)","vừa nguyên gốc vừa được cố định trên phương tiện hữu hình","Được nói ra"]}},
{"id":"ipr-213","q":"Which of the followings is NOT primary infringement of copyright?","o":["Copying part of a work without consent of author","Importing infringing copies","Translating a work without consent of author","Adapting a work without consent of author"],"a":[1],"m":"ipr","c":3,"n":213,"e":"Nhập khẩu bản sao vi phạm là vi phạm thứ cấp. Sao chép, dịch, chuyển thể không có phép là vi phạm trực tiếp.","vi":{"q":"Điều nào sau đây KHÔNG phải là vi phạm bản quyền trực tiếp (primary infringement)?","o":["Sao chép một phần tác phẩm mà không có sự đồng ý của tác giả","Nhập khẩu các bản sao vi phạm","Dịch một tác phẩm mà không có sự đồng ý của tác giả","Chuyển thể một tác phẩm mà không có sự đồng ý của tác giả"]}},
{"id":"ipr-214","q":"Duration of database right according to UK law","o":["Lasts for the life of its creator plus a further 70 years.","Lasts for 70 years begins to run on the death of the last surviving creator if two or more authors were jointly involved in the work","For the works generated before 1 January 1996 the duration of database right is life plus 50 years.","Lasts for 15 years from the end of the year the database was created or made accessible to the public"],"a":[3],"m":"ipr","c":6,"n":214,"e":"Quyền cơ sở dữ liệu của Anh có thời hạn 15 năm kể từ cuối năm cơ sở dữ liệu được tạo ra hoặc công bố.","vi":{"q":"Thời hạn của quyền đối với cơ sở dữ liệu (database right) theo luật Anh","o":["Suốt đời người sáng tạo cộng thêm 70 năm.","70 năm, bắt đầu tính từ khi người sáng tạo cuối cùng qua đời nếu có hai hay nhiều tác giả cùng tham gia tạo ra tác phẩm","Với tác phẩm được tạo ra trước ngày 1/1/1996, thời hạn quyền cơ sở dữ liệu là suốt đời cộng thêm 50 năm.","15 năm kể từ cuối năm cơ sở dữ liệu được tạo ra hoặc được công bố cho công chúng truy cập"]}},
{"id":"ipr-215","q":"Copyright can be applied to","o":["Music, plays and conventional artistic works including paintings and sculptures.","Works of artistic craftsmanship such as individually designed items of furniture.","Typefaces and to typographical editions, that is, the way a literary work is laid out on a page.","All of others are correct"],"a":[3],"m":"ipr","c":2,"n":215,"f":1,"e":"Bản quyền áp dụng cho âm nhạc, kịch, tranh, điêu khắc, tác phẩm thủ công mỹ nghệ nghệ thuật, kiểu chữ và ấn bản trình bày; đề chọn «tất cả».","vi":{"q":"Bản quyền có thể áp dụng cho","o":["Âm nhạc, kịch và các tác phẩm nghệ thuật truyền thống gồm tranh vẽ và điêu khắc.","Các tác phẩm thủ công mỹ nghệ nghệ thuật như đồ nội thất được thiết kế riêng.","Kiểu chữ (typeface) và ấn bản trình bày, tức là cách một tác phẩm văn học được bố cục trên trang giấy.","Tất cả các đáp án còn lại đều đúng"]}},
{"id":"ipr-216","q":"Duration of copyright in sound recordings or films according to UK law","o":["Lasts for 50 years from the year the film or record was made or, if it is released to the public, 50 years from its release","Lasts for the life of its creator plus a further 50 years.","Lasts for 70 years begins to run on the death of the last surviving creator if two or more authors were jointly involved in the work","The copyright lasts for 70 years from the end of the year in which the copyright material was created"],"a":[0],"m":"ipr","c":2,"n":216,"e":"Bản ghi âm và phim theo luật Anh (như đề nêu) có thời hạn 50 năm kể từ khi tạo ra hoặc kể từ khi công bố.","vi":{"q":"Thời hạn bản quyền đối với bản ghi âm hoặc phim theo luật Anh","o":["Kéo dài 50 năm kể từ năm phim hoặc bản ghi được tạo ra, hoặc nếu được công bố ra công chúng thì 50 năm kể từ khi công bố","Suốt đời người sáng tạo cộng thêm 50 năm.","70 năm, bắt đầu tính từ khi người sáng tạo cuối cùng qua đời nếu có hai hay nhiều tác giả cùng tham gia tạo ra tác phẩm","Bản quyền kéo dài 70 năm kể từ cuối năm mà tài liệu có bản quyền được tạo ra"]}},
{"id":"ipr-217","q":"Integrity right applied to","o":["Computer programs, works created for newspapers or magazines or multi-authored works, such as encyclopaedias","Copyright material created before the 88 Act came into force on 1 August 1989, provided the creator was alive on that day and had not assigned or licensed the copyright.","Films created before 1 August 1989","None of others is correct"],"a":[1],"m":"ipr","c":2,"n":217,"f":1,"e":"Quyền toàn vẹn áp dụng cho tài liệu có bản quyền được tạo trước khi Đạo luật 88 có hiệu lực (1/8/1989), nếu người sáng tạo còn sống vào ngày đó và chưa chuyển nhượng hoặc cấp phép.","vi":{"q":"Quyền toàn vẹn tác phẩm (integrity right) áp dụng cho","o":["Chương trình máy tính, tác phẩm tạo ra cho báo hoặc tạp chí, hoặc tác phẩm nhiều tác giả như bách khoa toàn thư","Tài liệu có bản quyền được tạo ra trước khi Đạo luật 88 có hiệu lực ngày 1/8/1989, với điều kiện người sáng tạo còn sống vào ngày đó và chưa chuyển nhượng hoặc cấp phép bản quyền.","Các bộ phim được tạo ra trước ngày 1/8/1989","Không đáp án nào còn lại đúng"]}},
{"id":"ipr-218","q":"What is privacy right?","o":["The right not to be wrongly named, that is, not to have a work falsely attributed to a creator","Relates to photographs taken under a commission (i.e. for payment) for private purposes","The author's right to object to a distortion or mutilation of a work when it is published, or to changes made which are considered to be prejudicial to the honour or reputation of the creator","The right for the creator of a literary, artistic, dramatic or musical copyright work and the director of a film (unless he or she is an employee) to be named as author or director in certain circumstances"],"a":[1],"m":"ipr","c":2,"n":218,"e":"Quyền riêng tư (privacy right) liên quan đến ảnh chụp theo đơn đặt hàng, trả tiền, cho mục đích riêng tư.","vi":{"q":"Quyền riêng tư (privacy right) là gì?","o":["Quyền không bị gọi tên sai, tức là không bị gán sai một tác phẩm cho người sáng tạo","Liên quan đến những bức ảnh chụp theo đơn đặt hàng (tức là có trả tiền) cho mục đích riêng tư","Quyền của tác giả được phản đối việc bóp méo hoặc cắt xén tác phẩm khi xuất bản, hoặc những thay đổi bị coi là gây phương hại đến danh dự hoặc uy tín của người sáng tạo","Quyền của người sáng tạo tác phẩm văn học, nghệ thuật, kịch hoặc âm nhạc có bản quyền và đạo diễn phim (trừ khi là nhân viên) được nêu tên là tác giả hoặc đạo diễn trong một số trường hợp"]}},
{"id":"ipr-219","q":"Which of the following is NOT a source of international copyright law?","o":["Bern convention","Paris convention","TRIPS - Trade-Related aspects of Intellectual Property Rights","WIPO Copyright Treaty"],"a":[1],"m":"ipr","c":2,"n":219,"e":"Công ước Paris điều chỉnh sở hữu công nghiệp, không phải nguồn của luật bản quyền quốc tế. Berne, TRIPS và WCT là nguồn của luật bản quyền.","vi":{"q":"Điều nào sau đây KHÔNG phải là nguồn của luật bản quyền quốc tế?","o":["Công ước Berne","Công ước Paris","TRIPS – Hiệp định về các khía cạnh liên quan đến thương mại của quyền sở hữu trí tuệ","Hiệp ước Bản quyền của WIPO (WCT)"]}},
{"id":"ipr-220","q":"Which country is NOT a member of Bern convention before 2022?","o":["Vietnam","Singapore","Laos","Indonesia"],"a":[2],"m":"ipr","c":2,"n":220,"e":"Theo đáp án của đề, chọn Lào; xem cảnh báo bên dưới.","vi":{"q":"Quốc gia nào KHÔNG phải là thành viên của Công ước Berne trước năm 2022?","o":["Việt Nam","Singapore","Lào","Indonesia"]},"k":"Theo danh sách thành viên của WIPO, cả 4 nước này đều đã tham gia Công ước Berne trước 2022 (Lào gia nhập năm 2012). Đề gốc chọn {C} (Lào)"},
{"id":"ipr-221","q":"Until 2022, Vietnam has not been a contracting party of:","o":["WIPO Copyright Treaty","Bern Convention","Paris Convention","Hague Agreement"],"a":[0],"m":"ipr","c":1,"n":221,"e":"Cho đến 2022, Việt Nam chưa là thành viên của Hiệp ước Bản quyền WIPO (WCT); Berne và Paris thì đã gia nhập.","vi":{"q":"Cho đến năm 2022, Việt Nam chưa là thành viên của:","o":["Hiệp ước Bản quyền của WIPO (WCT)","Công ước Berne","Công ước Paris","Thỏa ước La Hay"]}},
{"id":"ipr-222","q":"You and your co-worker are employees of a design company. Both of you are assigned to create a company logo for a client. In this case","o":["Only you reserve the right of paternity","Both you and your friend reserve the right of paternity","Only your company reserves the right of paternity","Your company, you and your friend all reserve the right of paternity"],"a":[1],"m":"ipr","c":2,"n":222,"e":"Quyền được nhận là tác giả (paternity right) thuộc về cá nhân tác giả, nên cả hai nhân viên cùng giữ quyền này; công ty không có quyền nhân thân.","vi":{"q":"Bạn và đồng nghiệp là nhân viên của một công ty thiết kế. Cả hai được giao tạo logo cho một khách hàng. Trong trường hợp này","o":["Chỉ mình bạn có quyền được nhận là tác giả (paternity right)","Cả bạn và đồng nghiệp đều có quyền được nhận là tác giả","Chỉ công ty của bạn có quyền được nhận là tác giả","Cả công ty, bạn và đồng nghiệp đều có quyền được nhận là tác giả"]}},
{"id":"ipr-223","q":"Moral rights include:","o":["Integrity right, reproduction right and false attribution right","Economic right, public performance right","Paternity right, integrity right, alse attribution right and privacy right","Paternity right, distribution right and privacy right"],"a":[2],"m":"ipr","c":2,"n":223,"e":"Quyền nhân thân gồm quyền được nhận là tác giả, quyền toàn vẹn, quyền chống gán sai tác giả và quyền riêng tư.","vi":{"q":"Quyền nhân thân (moral rights) bao gồm:","o":["Quyền toàn vẹn tác phẩm, quyền sao chép và quyền chống gán sai tác giả","Quyền kinh tế, quyền biểu diễn trước công chúng","Quyền được nhận là tác giả, quyền toàn vẹn tác phẩm, quyền chống gán sai tác giả và quyền riêng tư","Quyền được nhận là tác giả, quyền phân phối và quyền riêng tư"]}},
{"id":"ipr-224","q":"Which one of the followings is correct?","o":["Under Berne Convention, authors shall not reserve moral rights upon they transfer their works to other persons.","Under Berne Convention, authors shall reserve the right to claim authorship of their work but not the right to object any changes to their work upon they transfer their work.","Under Berne Convention, authors are not allowed to accept any changes to his original works upon they transfer such works to other persons.","Under Berne Convention, authors shall reserve moral rights upon they transfer their work to other persons."],"a":[3],"m":"ipr","c":2,"n":224,"e":"Theo Công ước Berne, tác giả vẫn giữ quyền nhân thân sau khi chuyển nhượng tác phẩm.","vi":{"q":"Điều nào sau đây đúng?","o":["Theo Công ước Berne, tác giả không còn giữ quyền nhân thân sau khi chuyển nhượng tác phẩm cho người khác.","Theo Công ước Berne, tác giả giữ quyền đòi được nhận là tác giả của tác phẩm nhưng không giữ quyền phản đối mọi thay đổi đối với tác phẩm sau khi chuyển nhượng.","Theo Công ước Berne, tác giả không được phép chấp nhận bất kỳ thay đổi nào đối với tác phẩm gốc của mình sau khi chuyển nhượng tác phẩm đó cho người khác.","Theo Công ước Berne, tác giả vẫn giữ quyền nhân thân sau khi chuyển nhượng tác phẩm cho người khác."]}},
{"id":"ipr-225","q":"To be granted a provisional measure order, the applicant must","o":["Provide any reasonable evidence to prove that he/she is the right holder of copyright","Provide any reasonable evidence to prove that his/her rights are being infringed or that such infringement is imminent.","Provide security","All of others are correct"],"a":[3],"m":"ipr","c":1,"n":225,"f":1,"e":"Để có lệnh khẩn cấp tạm thời cần chứng minh mình là chủ sở hữu, quyền đang bị xâm phạm hoặc sắp bị xâm phạm và cung cấp khoản bảo đảm.","vi":{"q":"Để được cấp lệnh biện pháp khẩn cấp tạm thời, người nộp đơn phải","o":["Cung cấp bất kỳ bằng chứng hợp lý nào chứng minh mình là chủ sở hữu bản quyền","Cung cấp bất kỳ bằng chứng hợp lý nào chứng minh quyền của mình đang bị xâm phạm hoặc sắp bị xâm phạm.","Cung cấp khoản bảo đảm","Tất cả các đáp án còn lại đều đúng"]}},
{"id":"ipr-226","q":"Which is NOT considered as copying part of a work?","o":["Uses a 'substantial part' of a work.","Copying one line of a well-known song in a nontechnical context,","Copying one frame from a film","A photocopy of a book, or a scanned-in digital copy of a photograph"],"a":[3],"m":"ipr","c":3,"n":226,"e":"Theo đáp án của đề, photocopy toàn bộ cuốn sách hay quét bản sao kỹ thuật số là sao chép cả tác phẩm, không phải «một phần».","vi":{"q":"Điều nào KHÔNG được coi là sao chép một phần của tác phẩm?","o":["Sử dụng một 'phần đáng kể' của tác phẩm.","Sao chép một dòng của một bài hát nổi tiếng trong ngữ cảnh phi kỹ thuật,","Sao chép một khung hình từ một bộ phim","Bản photocopy một cuốn sách, hoặc bản sao kỹ thuật số quét từ một bức ảnh"]}},
{"id":"ipr-227","q":"Which is considered as copying part of a work according to UK law?","o":["Adapting a copyright work, which includes translating it.","Copying one line of a well-known song in a nontechnical context","The extraction or reutilisation of a computer-stored database, whether the whole or a substantial part","A photocopy of a book, or a scanned-in digital copy of a photograph"],"a":[1],"m":"ipr","c":3,"n":227,"e":"Sao chép một dòng của bài hát nổi tiếng có thể coi là sao chép một phần đáng kể của tác phẩm.","vi":{"q":"Điều nào được coi là sao chép một phần của tác phẩm theo luật Anh?","o":["Chuyển thể một tác phẩm có bản quyền, bao gồm cả việc dịch tác phẩm đó.","Sao chép một dòng của một bài hát nổi tiếng trong ngữ cảnh phi kỹ thuật","Trích xuất hoặc khai thác lại cơ sở dữ liệu lưu trên máy tính, dù toàn bộ hay một phần đáng kể","Bản photocopy một cuốn sách, hoặc bản sao kỹ thuật số quét từ một bức ảnh"]}},
{"id":"ipr-228","q":"Which is considered as infringing a broadcast program copyright?","o":["Adapting a copyright work, which includes translating it.","Copying one line of a well-known song in a nontechnical context","Re-broadcast it or include it in another cable programme","The extraction or reutilisation of a computer-stored database, whether the whole or a substantial part"],"a":[2],"m":"ipr","c":3,"n":228,"e":"Phát sóng lại chương trình phát sóng hoặc đưa vào chương trình cáp khác xâm phạm bản quyền chương trình phát sóng.","vi":{"q":"Hành vi nào được coi là xâm phạm bản quyền chương trình phát sóng?","o":["Chuyển thể một tác phẩm có bản quyền, bao gồm cả việc dịch tác phẩm đó.","Sao chép một dòng của một bài hát nổi tiếng trong ngữ cảnh phi kỹ thuật","Phát sóng lại hoặc đưa nó vào một chương trình truyền hình cáp khác","Trích xuất hoặc khai thác lại cơ sở dữ liệu lưu trên máy tính, dù toàn bộ hay một phần đáng kể"]}},
{"id":"ipr-229","q":"Which is NOT right about copying computer programs?","o":["Conventional translation of a program from English into a foreign language","When an applications program on a disk is loaded onto a personal computer (PC), a copy is made in a different medium","When hardware is running software, parts of the software code are copied internally, for example, from a read-only memory into an instruction register","Computer programs cannot be used without an act of copying, it is legally essential for the copyright owner to give permission for the copying."],"a":[0],"m":"ipr","c":3,"n":229,"e":"Dịch thông thường chương trình sang ngôn ngữ khác là chuyển thể (adaptation), không phải ví dụ về sao chép; các phương án khác đều là sao chép ngầm khi chạy chương trình.","vi":{"q":"Điều nào KHÔNG đúng về việc sao chép chương trình máy tính?","o":["Việc dịch thông thường một chương trình từ tiếng Anh sang một ngôn ngữ khác","Khi một chương trình ứng dụng trên đĩa được nạp vào máy tính cá nhân (PC), một bản sao được tạo ra trên một phương tiện khác","Khi phần cứng chạy phần mềm, một phần mã phần mềm được sao chép nội bộ, ví dụ từ bộ nhớ chỉ đọc vào thanh ghi lệnh","Chương trình máy tính không thể được sử dụng mà không có hành vi sao chép, nên về mặt pháp lý chủ sở hữu bản quyền bắt buộc phải cho phép việc sao chép."]}},
{"id":"ipr-230","q":"' Apple' for computers is an example of","o":["Invented words used as a trade mark","Words used out of context as a trade mark","Symbols used as a trade mark","Shapes used as a trade mark"],"a":[1],"m":"ipr","c":4,"n":230,"e":"«Apple» cho máy tính là từ thông thường dùng ngoài ngữ cảnh gốc (words used out of context).","vi":{"q":"'Apple' cho máy tính là ví dụ về","o":["Từ tự đặt ra dùng làm nhãn hiệu","Từ dùng ngoài ngữ cảnh (không liên quan) làm nhãn hiệu","Biểu tượng dùng làm nhãn hiệu","Hình dạng dùng làm nhãn hiệu"]}},
{"id":"ipr-231","q":"Registration of a trade mark is","o":["automatic","subject to an approval process through the designated authoritative body","dependent upon a corporation using a priori means to establish an original mark.","dependent upon whether the mark has been established as being diluted."],"a":[1],"m":"ipr","c":4,"n":231,"e":"Đăng ký nhãn hiệu phải qua quy trình thẩm định, phê duyệt của cơ quan có thẩm quyền, không tự động.","vi":{"q":"Việc đăng ký nhãn hiệu","o":["là tự động","phải qua quy trình phê duyệt của cơ quan có thẩm quyền được chỉ định","phụ thuộc vào việc công ty dùng phương tiện tiên nghiệm (a priori) để xác lập một nhãn hiệu nguyên gốc.","phụ thuộc vào việc nhãn hiệu đã được xác lập là bị pha loãng (diluted) hay chưa."]}},
{"id":"ipr-232","q":"A trade mark can be any of the following except a","o":["Word","Symbol","Formula","Phrase"],"a":[2],"m":"ipr","c":4,"n":232,"e":"Nhãn hiệu có thể là từ, biểu tượng, cụm từ nhưng công thức (formula) thì không.","vi":{"q":"Một nhãn hiệu có thể là bất kỳ thứ nào sau đây ngoại trừ","o":["Từ","Biểu tượng","Công thức","Cụm từ"]}},
{"id":"ipr-233","q":"Which of the following is not eligible for immediate trade mark protection?","o":["fanciful trade marks","descriptive trade marks","arbitrary trade marks","suggestive trade marks"],"a":[1],"m":"ipr","c":4,"n":233,"e":"Nhãn hiệu mô tả (descriptive) không được bảo hộ ngay vì thiếu tính phân biệt; tưởng tượng, tùy ý, gợi ý thì được.","vi":{"q":"Loại nhãn hiệu nào sau đây không đủ điều kiện được bảo hộ ngay lập tức?","o":["nhãn hiệu tưởng tượng (fanciful)","nhãn hiệu mô tả (descriptive)","nhãn hiệu tùy ý (arbitrary)","nhãn hiệu gợi ý (suggestive)"]}},
{"id":"ipr-234","q":"Which of the following is an example of a suggestive trade mark?","o":["Fruit of the Loom","Victoria's Secret","eBay","Netflix"],"a":[3],"m":"ipr","c":4,"n":234,"e":"Netflix gợi ý dịch vụ chiếu phim qua mạng nên là nhãn hiệu gợi ý; xem cảnh báo bên dưới về cách phân loại.","vi":{"q":"Ví dụ nào sau đây là nhãn hiệu gợi ý (suggestive)?","o":["Fruit of the Loom","Victoria's Secret","eBay","Netflix"]},"k":"Theo cách phân loại phổ biến của Mỹ: Netflix là nhãn hiệu gợi ý; Fruit of the Loom và Victoria's Secret là nhãn hiệu tùy ý (arbitrary); eBay là nhãn hiệu tưởng tượng (fanciful)."},
{"id":"ipr-235","q":"In the UK, a trade mark is used without registering is permitted.","o":["This is correct. A marked can be used without registering although it is recommended that registration is always needed for enjoying protection.","This is not correct. Once being used, a trade mark has already been registered.","This is not correct. Trade mark must be registered before using in the course of trade","None of the statements are correct."],"a":[0],"m":"ipr","c":4,"n":235,"f":1,"e":"Ở Anh, nhãn hiệu có thể được dùng mà không đăng ký, nhưng nên đăng ký để được bảo hộ.","vi":{"q":"Ở Anh, việc sử dụng nhãn hiệu mà không đăng ký là được phép.","o":["Đúng. Nhãn hiệu có thể được sử dụng mà không cần đăng ký, dù nên luôn đăng ký để được hưởng bảo hộ.","Không đúng. Một khi đã được sử dụng thì nhãn hiệu coi như đã được đăng ký.","Không đúng. Nhãn hiệu phải được đăng ký trước khi sử dụng trong hoạt động thương mại","Không nhận định nào đúng."]}},
{"id":"ipr-236","q":"In the UK trade mark law, when is \"goodwill\" generated by the use of the mark?","o":["When the mark could have been registered but the owner decided not to register it","When the mark is unregistrable because it does not meet the requirements of the Trade Marks Act 1994","A and B are correct","A and B are incorrect"],"a":[2],"m":"ipr","c":5,"n":236,"f":1,"e":"Uy tín (goodwill) phát sinh từ việc dùng nhãn hiệu, cả khi nhãn hiệu có thể đăng ký mà chủ chưa đăng ký lẫn khi nhãn hiệu không đăng ký được.","vi":{"q":"Theo luật nhãn hiệu Anh, khi nào \"uy tín thương mại\" (goodwill) được tạo ra từ việc sử dụng nhãn hiệu?","o":["Khi nhãn hiệu có thể đã được đăng ký nhưng chủ sở hữu quyết định không đăng ký","Khi nhãn hiệu không đăng ký được vì không đáp ứng yêu cầu của Đạo luật Nhãn hiệu 1994","A và B đều đúng","A và B đều sai"]}},
{"id":"ipr-237","q":"After a sufficient use, a mark which is unregistrable may become registrable because","o":["Its reputation can be used as proof that the mark has become distinctive for the goods or service for which it has been used.","This can not be happened. The mark should be registered through an official process as stated by the laws.","The mark is automatically registered","None of the answer is correct"],"a":[0],"m":"ipr","c":5,"n":237,"f":1,"e":"Sau thời gian sử dụng đủ lâu, uy tín có thể chứng minh nhãn hiệu đã đạt tính phân biệt (secondary meaning) nên có thể đăng ký.","vi":{"q":"Sau khi được sử dụng đủ lâu, một nhãn hiệu vốn không đăng ký được có thể trở thành đăng ký được vì","o":["Uy tín của nó có thể được dùng làm bằng chứng rằng nhãn hiệu đã trở nên có tính phân biệt đối với hàng hóa hoặc dịch vụ mà nó đã được sử dụng.","Điều này không thể xảy ra. Nhãn hiệu phải được đăng ký qua thủ tục chính thức theo quy định của luật.","Nhãn hiệu được đăng ký tự động","Không đáp án nào đúng"]}},
{"id":"ipr-238","q":"Get-up includes","o":["the colour of packaging and the type of lettering used on a label","a slogan used for broadcast or printed advertising","visual impression of business premises, such as the style of fascia board and the colour of shop fittings","All are correct"],"a":[3],"m":"ipr","c":5,"n":238,"f":1,"e":"Get-up gồm màu bao bì, kiểu chữ, khẩu hiệu quảng cáo, ấn tượng thị giác của cơ sở kinh doanh; chọn «tất cả».","vi":{"q":"Get-up (diện mạo thương mại) bao gồm","o":["màu sắc bao bì và kiểu chữ dùng trên nhãn","khẩu hiệu dùng trong quảng cáo phát sóng hoặc in ấn","ấn tượng thị giác của cơ sở kinh doanh, như kiểu bảng hiệu cửa hàng và màu sắc đồ đạc trong cửa hàng","Tất cả đều đúng"]}},
{"id":"ipr-239","q":"Confusion can be caused by a competitor using the most memorable part of the trade mark.","o":["Yes. The use of the most memorable part will be sufficient to generate the confusion.","No. The confusion happens when the competitor uses an identical or very similar trade mark or get-up.","No. The confusion happens only in the case of using identical marks for identical goods or services","None of the abovementioned statement is correct"],"a":[0],"m":"ipr","c":5,"n":239,"f":1,"e":"Chỉ cần dùng phần dễ nhớ nhất của nhãn hiệu cũng có thể đủ gây nhầm lẫn.","vi":{"q":"Sự nhầm lẫn có thể bị gây ra bởi việc đối thủ sử dụng phần dễ nhớ nhất của nhãn hiệu.","o":["Có. Chỉ cần sử dụng phần dễ nhớ nhất là đủ gây nhầm lẫn.","Không. Sự nhầm lẫn xảy ra khi đối thủ sử dụng nhãn hiệu hoặc get-up giống hệt hoặc rất giống.","Không. Sự nhầm lẫn chỉ xảy ra trong trường hợp dùng nhãn hiệu giống hệt cho hàng hóa hoặc dịch vụ giống hệt","Không có nhận định nào ở trên đúng"]}},
{"id":"ipr-240","q":"What is the definition of a domain name?","o":["A domain name is an anonymous string that defines a realm of administrative autonomy, authority or control within the Internet.","A domain name is an identification string that defines a realm of administrative autonomy, authority or control within a geographic area.","A domain name is an identification string that defines a realm of administrative autonomy, authority or control within the Internet.","A domain name is an identification string that defines a person, authority or control within the Internet."],"a":[2],"m":"ipr","c":5,"n":240,"e":"Tên miền là chuỗi định danh xác định một phạm vi tự quản trị, thẩm quyền hoặc kiểm soát trong Internet.","vi":{"q":"Định nghĩa của tên miền (domain name) là gì?","o":["Tên miền là một chuỗi ẩn danh xác định một phạm vi tự quản trị, thẩm quyền hoặc kiểm soát trong Internet.","Tên miền là một chuỗi định danh xác định một phạm vi tự quản trị, thẩm quyền hoặc kiểm soát trong một khu vực địa lý.","Tên miền là một chuỗi định danh xác định một phạm vi tự quản trị, thẩm quyền hoặc kiểm soát trong Internet.","Tên miền là một chuỗi định danh xác định một con người, thẩm quyền hoặc kiểm soát trong Internet."]}},
{"id":"ipr-241","q":"Domain names are registered by the principle of","o":["Peer-reviewed","censorship","Resources restriction","first-come first-served"],"a":[3],"m":"ipr","c":5,"n":241,"e":"Tên miền được đăng ký theo nguyên tắc ai đến trước được trước (first-come first-served).","vi":{"q":"Tên miền được đăng ký theo nguyên tắc","o":["Đánh giá đồng cấp (peer-reviewed)","kiểm duyệt","Hạn chế tài nguyên","ai đến trước được trước (first-come first-served)"]}},
{"id":"ipr-242","q":"A registration of domain names usually lasts for.... year(s), and if not renewed, can be allocated to another owner.","o":["1","2","3","4"],"a":[1],"m":"ipr","c":5,"n":242,"e":"Theo đáp án của đề, đăng ký tên miền thường kéo dài 2 năm; nếu không gia hạn có thể được cấp cho người khác.","vi":{"q":"Việc đăng ký tên miền thường kéo dài.... năm, và nếu không gia hạn thì có thể được cấp cho chủ sở hữu khác.","o":["1","2","3","4"]}},
{"id":"ipr-243","q":"Comparative advertising does not infringe trade mark use unless","o":["it is for the company's advantages","it is not in accordance with honest business practices.","it serves customers with information","All trade mark uses in comparative advertising contribute the infringement to trade mark protection"],"a":[1],"m":"ipr","c":5,"n":243,"e":"Quảng cáo so sánh chỉ xâm phạm nhãn hiệu nếu không phù hợp với thông lệ kinh doanh trung thực.","vi":{"q":"Quảng cáo so sánh không xâm phạm quyền sử dụng nhãn hiệu trừ khi","o":["nó có lợi cho công ty","nó không phù hợp với thông lệ kinh doanh trung thực.","nó cung cấp thông tin cho khách hàng","Mọi hành vi sử dụng nhãn hiệu trong quảng cáo so sánh đều gây ra xâm phạm bảo hộ nhãn hiệu"]}},
{"id":"ipr-244","q":"When you use the similar mark on the registered or similar goods/services is an infringement","o":["Yes. This is enough to conclude that there is an infringement","No. This will be an infringement when the use likely causes public to be confused.","Yes. This is an infringement since it can devalue goods or services.","Yes. This is an infringement because it offers more choices for customers."],"a":[1],"m":"ipr","c":5,"n":244,"e":"Dùng nhãn hiệu tương tự cho hàng hóa tương tự chỉ là xâm phạm khi có khả năng gây nhầm lẫn cho công chúng.","vi":{"q":"Khi bạn dùng nhãn hiệu tương tự cho hàng hóa/dịch vụ đã đăng ký hoặc tương tự thì có là xâm phạm không","o":["Có. Chỉ vậy là đủ để kết luận có hành vi xâm phạm","Không. Đó sẽ là xâm phạm khi việc sử dụng có khả năng khiến công chúng nhầm lẫn.","Có. Đó là xâm phạm vì nó có thể làm giảm giá trị hàng hóa hoặc dịch vụ.","Có. Đó là xâm phạm vì nó đem lại nhiều lựa chọn hơn cho khách hàng."]}},
{"id":"ipr-245","q":"When you use the registered trade mark in relation to the goods/services specified in the registration, there is an infringement.","o":["True.","It depends.","False. Besides what mentioned, the infringement must be caused with confusion.","False. Because the use of registered trade mark in relation to the goods/services specified in the registrati"],"a":[0],"m":"ipr","c":5,"n":245,"e":"Theo đáp án của đề, dùng nhãn hiệu đã đăng ký đúng hàng hóa/dịch vụ đã đăng ký (bởi người không phải chủ) là xâm phạm.","vi":{"q":"Khi bạn sử dụng nhãn hiệu đã đăng ký cho hàng hóa/dịch vụ được nêu trong đăng ký, thì có hành vi xâm phạm.","o":["Đúng.","Tùy trường hợp.","Sai. Ngoài các điều nêu trên, hành vi xâm phạm còn phải gây ra nhầm lẫn.","Sai. Vì việc sử dụng nhãn hiệu đã đăng ký cho hàng hóa/dịch vụ được nêu trong đăng ký"]}},
{"id":"ipr-246","q":"What does Trade libel means?","o":["Misleading advertisements and false indications of the origin of goods and services","The original information about the quality of products or services","An injunction against counterfeit","A piece of information identified the products or services on mass communication"],"a":[0],"m":"ipr","c":5,"n":246,"e":"Trade libel là quảng cáo gây hiểu lầm và chỉ dẫn sai về nguồn gốc hàng hóa, dịch vụ.","vi":{"q":"Trade libel (phỉ báng thương mại) nghĩa là gì?","o":["Quảng cáo gây hiểu lầm và chỉ dẫn sai về nguồn gốc của hàng hóa và dịch vụ","Thông tin gốc về chất lượng sản phẩm hoặc dịch vụ","Một lệnh cấm đối với hàng giả","Một thông tin xác định sản phẩm hoặc dịch vụ trên phương tiện truyền thông đại chúng"]}},
{"id":"ipr-247","q":"Dealing with trading counterfeit goods is an international problem due to major differences in national laws, particularly in the Far East. In these countries, what measure prevails as a viable way for this problem?","o":["Enacting a new international mechanism","International lobbying on a long-term basis.","Enhancing more international observations","Do nothing, since this is a domestic problem of a country"],"a":[1],"m":"ipr","c":1,"n":247,"e":"Do khác biệt về luật quốc gia, giải pháp khả thi là vận động quốc tế trong dài hạn.","vi":{"q":"Việc buôn bán hàng giả là vấn đề quốc tế do sự khác biệt lớn giữa luật pháp các nước, đặc biệt ở Viễn Đông. Ở những nước này, biện pháp nào được cho là khả thi để giải quyết vấn đề?","o":["Ban hành một cơ chế quốc tế mới","Vận động quốc tế trong dài hạn.","Tăng cường giám sát quốc tế","Không làm gì cả, vì đây là vấn đề nội bộ của mỗi quốc gia"]}},
{"id":"ipr-248","q":"In the UK, it is a _____ offence to apply a mark identical to (or likely to be mistaken for) a registered trade mark to goods, labels, packaging or advertising materials intended for use in relation to goods without the proprietor's permission.","o":["Civil","Moral","Criminal","Ethical"],"a":[2],"m":"ipr","c":5,"n":248,"e":"Ở Anh, gắn dấu hiệu giống nhãn hiệu đã đăng ký lên hàng hóa, nhãn, bao bì hoặc tài liệu quảng cáo mà không được phép là tội hình sự.","vi":{"q":"Ở Anh, việc gắn một dấu hiệu giống hệt (hoặc có thể bị nhầm với) nhãn hiệu đã đăng ký lên hàng hóa, nhãn, bao bì hoặc tài liệu quảng cáo dành cho hàng hóa mà không có sự cho phép của chủ nhãn hiệu là một tội _____.","o":["Dân sự","Đạo đức (moral)","Hình sự","Đạo đức (ethical)"]}},
{"id":"ipr-249","q":"In the UK, if you want to search for registering of trade marks, who have all information to help you?","o":["a trade mark agent","patent attorney","a commercial searching organization","All are correct"],"a":[3],"m":"ipr","c":4,"n":249,"f":1,"e":"Đại diện nhãn hiệu, luật sư sáng chế và tổ chức tra cứu thương mại đều có thể giúp tra cứu đăng ký nhãn hiệu.","vi":{"q":"Ở Anh, nếu bạn muốn tra cứu việc đăng ký nhãn hiệu, ai có đầy đủ thông tin để giúp bạn?","o":["một đại diện nhãn hiệu (trade mark agent)","luật sư sáng chế (patent attorney)","một tổ chức tra cứu thương mại","Tất cả đều đúng"]}},
{"id":"ipr-250","q":"In the UK, there are criminal provisions relating to misuse of trade marks and relate only to","o":["Registered trade marks","Unregistered trade marks","Get-up","All are correct"],"a":[0],"m":"ipr","c":5,"n":250,"f":1,"e":"Quy định hình sự về lạm dụng nhãn hiệu chỉ liên quan đến nhãn hiệu đã đăng ký.","vi":{"q":"Ở Anh, có các quy định hình sự về việc lạm dụng nhãn hiệu và chỉ liên quan đến","o":["Nhãn hiệu đã đăng ký","Nhãn hiệu chưa đăng ký","Get-up","Tất cả đều đúng"]}},
{"id":"ipr-251","q":"A Community Trade Marks (CTM) is valid in ___","o":["All member countries of the WTO","All member countries of the EU","All member countries of the WIPO","All member countries of the UN"],"a":[1],"m":"ipr","c":4,"n":251,"e":"Nhãn hiệu Cộng đồng (CTM) có hiệu lực ở tất cả các nước thành viên EU.","vi":{"q":"Nhãn hiệu Cộng đồng (CTM) có hiệu lực ở ___","o":["Tất cả các nước thành viên WTO","Tất cả các nước thành viên EU","Tất cả các nước thành viên WIPO","Tất cả các nước thành viên Liên hợp quốc"]}},
{"id":"ipr-252","q":"The registration of a Community Trade Mark can be renewed every....... years.","o":["CTM cannot be renewed","5 years, for 4 consecutive times after the first registration","5 years","10 years"],"a":[3],"m":"ipr","c":4,"n":252,"e":"Đăng ký CTM được gia hạn cứ sau 10 năm.","vi":{"q":"Đăng ký Nhãn hiệu Cộng đồng có thể được gia hạn cứ sau....... năm.","o":["CTM không thể gia hạn","5 năm, 4 lần liên tiếp sau lần đăng ký đầu tiên","5 năm","10 năm"]}},
{"id":"ipr-253","q":"What trade marks international system allows anyone with a trade mark registration in one member country to make a single application covering all, or a selected number, of other member countries?","o":["Hauge Agreement","Madrid Agreement","Paris Convention","Berne Convention"],"a":[1],"m":"ipr","c":4,"n":253,"e":"Thỏa ước Madrid cho phép người có đăng ký nhãn hiệu ở một nước thành viên nộp một đơn duy nhất đăng ký ở các nước thành viên khác.","vi":{"q":"Hệ thống nhãn hiệu quốc tế nào cho phép bất kỳ ai có đăng ký nhãn hiệu ở một nước thành viên nộp một đơn duy nhất bao trùm tất cả hoặc một số nước thành viên khác được chọn?","o":["Thỏa ước La Hay","Thỏa ước Madrid","Công ước Paris","Công ước Berne"]}},
{"id":"ipr-254","q":"According to TRIPS, what a registered mark must give the owner?","o":["Exclusive right to prevent use by a third party in the course of trade of an identical or similar sign for identical or similar goods","Exclusive right to prevent use by a third party in the course of trade of an identical or similar sign for identical or similar services","Exclusive right to prevent use by a third party in the course of trade of an identical or similar sign for identical or similar goods and services","Exclusive right to prevent use by a third party in the course of trade of an identical or similar sign for different goods"],"a":[0],"m":"ipr","c":4,"n":254,"e":"Theo đáp án của đề, nhãn hiệu đã đăng ký cho quyền ngăn bên thứ ba dùng dấu hiệu giống/tương tự cho hàng hóa giống/tương tự; xem cảnh báo bên dưới.","vi":{"q":"Theo TRIPS, nhãn hiệu đã đăng ký phải trao cho chủ sở hữu quyền gì?","o":["Quyền độc quyền ngăn bên thứ ba sử dụng trong hoạt động thương mại một dấu hiệu giống hệt hoặc tương tự cho hàng hóa giống hệt hoặc tương tự","Quyền độc quyền ngăn bên thứ ba sử dụng trong hoạt động thương mại một dấu hiệu giống hệt hoặc tương tự cho dịch vụ giống hệt hoặc tương tự","Quyền độc quyền ngăn bên thứ ba sử dụng trong hoạt động thương mại một dấu hiệu giống hệt hoặc tương tự cho hàng hóa và dịch vụ giống hệt hoặc tương tự","Quyền độc quyền ngăn bên thứ ba sử dụng trong hoạt động thương mại một dấu hiệu giống hệt hoặc tương tự cho hàng hóa khác nhau"]},"k":"Điều 16 TRIPS nói về hàng hóa HOẶC dịch vụ giống hệt/tương tự, nên phương án {C} đầy đủ hơn {A} (xem câu #300 cùng nội dung nhưng đề chọn {C}). Câu này đề chọn {A}."},
{"id":"ipr-255","q":"Why do owners need to commercialize IPRs?","o":["IPRs owner should translate IPRs into money for reinvestment and profit","IPRs owner may not have enough resources to exploit IPRs.","IPRs owner should commercialize IPRs by means of assignment or license.","All are correct"],"a":[3],"m":"ipr","c":1,"n":255,"f":1,"e":"Chủ sở hữu thương mại hóa quyền để kiếm tiền tái đầu tư, vì có thể thiếu nguồn lực tự khai thác, bằng cách chuyển nhượng hoặc cấp phép.","vi":{"q":"Vì sao chủ sở hữu cần thương mại hóa quyền sở hữu trí tuệ?","o":["Chủ sở hữu quyền sở hữu trí tuệ nên chuyển quyền sở hữu trí tuệ thành tiền để tái đầu tư và thu lợi nhuận","Chủ sở hữu quyền sở hữu trí tuệ có thể không đủ nguồn lực để khai thác quyền.","Chủ sở hữu quyền sở hữu trí tuệ nên thương mại hóa quyền bằng cách chuyển nhượng hoặc cấp phép.","Tất cả đều đúng"]}},
{"id":"ipr-256","q":"What intellectual property right can be licensed?","o":["Any IPR","Copyright only","Registered design only","Trade mark only"],"a":[0],"m":"ipr","c":1,"n":256,"e":"Bất kỳ quyền sở hữu trí tuệ nào cũng có thể được cấp phép.","vi":{"q":"Quyền sở hữu trí tuệ nào có thể được cấp phép sử dụng?","o":["Bất kỳ quyền sở hữu trí tuệ nào","Chỉ bản quyền","Chỉ kiểu dáng đã đăng ký","Chỉ nhãn hiệu"]}},
{"id":"ipr-257","q":"How to acquire IPRs?","o":["Assignment","Licensing","Know-how contract","All are correct"],"a":[3],"m":"ipr","c":1,"n":257,"f":1,"e":"Có thể có quyền sở hữu trí tuệ thông qua chuyển nhượng, cấp phép hoặc hợp đồng bí quyết.","vi":{"q":"Làm thế nào để có được quyền sở hữu trí tuệ?","o":["Chuyển nhượng (assignment)","Cấp phép (licensing)","Hợp đồng bí quyết (know-how)","Tất cả đều đúng"]}},
{"id":"ipr-258","q":"What is an assignment?","o":["The ownership of IPRs is transferred from the assignor to the assignee. Upon assignment, the assignee becomes the owner of the rights.","The ownership of IPRs is transferred from the assignee to the assignor. Upon assignment, the assignor becomes the owner of the rights.","The ownership of IPRs is transferred from the assignor to the other assignee. Upon assignment, the assignor remains the owner of the rights.","None of the above definitions is correct"],"a":[0],"m":"ipr","c":1,"n":258,"f":1,"e":"Chuyển nhượng là chuyển quyền sở hữu từ bên chuyển nhượng sang bên nhận; sau đó bên nhận trở thành chủ sở hữu.","vi":{"q":"Chuyển nhượng (assignment) là gì?","o":["Quyền sở hữu quyền sở hữu trí tuệ được chuyển từ bên chuyển nhượng sang bên nhận chuyển nhượng. Sau khi chuyển nhượng, bên nhận chuyển nhượng trở thành chủ sở hữu của quyền.","Quyền sở hữu quyền sở hữu trí tuệ được chuyển từ bên nhận chuyển nhượng sang bên chuyển nhượng. Sau khi chuyển nhượng, bên chuyển nhượng trở thành chủ sở hữu của quyền.","Quyền sở hữu quyền sở hữu trí tuệ được chuyển từ bên chuyển nhượng sang một bên nhận chuyển nhượng khác. Sau khi chuyển nhượng, bên chuyển nhượng vẫn là chủ sở hữu của quyền.","Không định nghĩa nào ở trên đúng"]}},
{"id":"ipr-259","q":"The assignment and licensing agreement shall be registered by the competent authority as required by law.","o":["No. Only the licensing is needed","Yes. They can be registered upon the requirement of the law","No. Only the assignment agreement is needed","No. They can never be registered"],"a":[1],"m":"ipr","c":1,"n":259,"e":"Hợp đồng chuyển nhượng và cấp phép có thể phải đăng ký khi luật yêu cầu.","vi":{"q":"Hợp đồng chuyển nhượng và cấp phép phải được cơ quan có thẩm quyền đăng ký theo yêu cầu của luật.","o":["Không. Chỉ cần đăng ký hợp đồng cấp phép","Có. Chúng có thể được đăng ký khi luật yêu cầu","Không. Chỉ cần đăng ký hợp đồng chuyển nhượng","Không. Chúng không bao giờ có thể được đăng ký"]}},
{"id":"ipr-260","q":"The know-how may be delivered in the forms of","o":["documents only","None is correct","technical service and other intangible forms only","the tangible forms or intangible forms"],"a":[3],"m":"ipr","c":1,"n":260,"f":1,"e":"Bí quyết (know-how) có thể được chuyển giao dưới hình thức hữu hình hoặc phi vật thể.","vi":{"q":"Bí quyết kỹ thuật (know-how) có thể được chuyển giao dưới các hình thức","o":["chỉ là tài liệu","Không đáp án nào đúng","chỉ là dịch vụ kỹ thuật và các hình thức phi vật thể khác","hình thức hữu hình hoặc phi vật thể"]}},
{"id":"ipr-261","q":"Know-how contract can be existed under a form of relevant transaction such as joint-venture.","o":["True. Know-how contract can be existed under a form of relevant transaction such as joint-venture besides other forms.","False. Know-how contract can be existed only under a form of apprenticeship.","False. Know-how contract can be existed only under a form of franchising.","False. Know-how contract can be existed only under a form of supporting agreement."],"a":[0],"m":"ipr","c":1,"n":261,"e":"Hợp đồng know-how có thể tồn tại dưới nhiều hình thức giao dịch liên quan, như liên doanh.","vi":{"q":"Hợp đồng know-how có thể tồn tại dưới hình thức một giao dịch liên quan như liên doanh.","o":["Đúng. Hợp đồng know-how có thể tồn tại dưới hình thức một giao dịch liên quan như liên doanh, bên cạnh các hình thức khác.","Sai. Hợp đồng know-how chỉ có thể tồn tại dưới hình thức học nghề.","Sai. Hợp đồng know-how chỉ có thể tồn tại dưới hình thức nhượng quyền thương mại (franchising).","Sai. Hợp đồng know-how chỉ có thể tồn tại dưới hình thức thỏa thuận hỗ trợ."]}},
{"id":"ipr-262","q":"What does royalty mean?","o":["post-calculated, recurring payments, the amount of which is determined under economic use or result (sales, profits).","a pre-calculated amount paid once or in installments","compensation for services and assistance rendered by technical or professional experts.","dividend or income from related operations: commission paid to licensor for his assistance in selling."],"a":[0],"m":"ipr","c":1,"n":262,"e":"Royalty là các khoản thanh toán định kỳ tính sau, theo mức sử dụng hoặc kết quả kinh tế như doanh thu, lợi nhuận.","vi":{"q":"Tiền bản quyền (royalty) nghĩa là gì?","o":["các khoản thanh toán định kỳ tính sau, có số tiền xác định theo mức sử dụng hoặc kết quả kinh tế (doanh thu, lợi nhuận).","một khoản tiền tính trước, trả một lần hoặc trả góp","thù lao cho dịch vụ và sự hỗ trợ của các chuyên gia kỹ thuật hoặc chuyên môn.","cổ tức hoặc thu nhập từ các hoạt động liên quan: hoa hồng trả cho bên cấp phép vì hỗ trợ bán hàng."]}},
{"id":"ipr-263","q":"Lump-sum payment is","o":["post-calculated, recurring payments, the amount of which is determined under economic use or result (sales, profits).","a pre-calculated amount paid once or in installments","compensation for services and assistance rendered by technical or professional experts.","dividend or income from related operations: commission paid to licensor for his assistance in selling."],"a":[1],"m":"ipr","c":1,"n":263,"e":"Thanh toán trọn gói (lump-sum) là khoản tiền tính trước, trả một lần hoặc trả góp.","vi":{"q":"Thanh toán trọn gói (lump-sum payment) là","o":["các khoản thanh toán định kỳ tính sau, có số tiền xác định theo mức sử dụng hoặc kết quả kinh tế (doanh thu, lợi nhuận).","một khoản tiền tính trước, trả một lần hoặc trả góp","thù lao cho dịch vụ và sự hỗ trợ của các chuyên gia kỹ thuật hoặc chuyên môn.","cổ tức hoặc thu nhập từ các hoạt động liên quan: hoa hồng trả cho bên cấp phép vì hỗ trợ bán hàng."]}},
{"id":"ipr-264","q":"Indirect compensation includes","o":["post-calculated, recurring payments, the amount of which is determined under economic use or result (sales, profits).","a pre-calculated amount paid once or in installments","compensation for services and assistance rendered by technical or professional experts.","dividend or income from related operations: commission paid to licensor for his assistance in selling."],"a":[3],"m":"ipr","c":1,"n":264,"e":"Thù lao gián tiếp gồm cổ tức hoặc thu nhập từ hoạt động liên quan, hoa hồng trả cho bên cấp phép vì hỗ trợ bán hàng.","vi":{"q":"Thù lao gián tiếp (indirect compensation) bao gồm","o":["các khoản thanh toán định kỳ tính sau, có số tiền xác định theo mức sử dụng hoặc kết quả kinh tế (doanh thu, lợi nhuận).","một khoản tiền tính trước, trả một lần hoặc trả góp","thù lao cho dịch vụ và sự hỗ trợ của các chuyên gia kỹ thuật hoặc chuyên môn.","cổ tức hoặc thu nhập từ các hoạt động liên quan: hoa hồng trả cho bên cấp phép vì hỗ trợ bán hàng."]}},
{"id":"ipr-265","q":"Exclusive license is","o":["the licensee will have no competition","the licensor will afford no licenses to other persons within the contractual territory","A and B are correct","A and B are incorrect"],"a":[0],"m":"ipr","c":1,"n":265,"f":1,"e":"Giấy phép độc quyền (exclusive license): bên được cấp phép không có đối thủ cạnh tranh (kể cả bên cấp phép).","vi":{"q":"Giấy phép độc quyền (exclusive license) là","o":["bên được cấp phép sẽ không có đối thủ cạnh tranh","bên cấp phép sẽ không cấp phép cho bất kỳ người nào khác trong lãnh thổ theo hợp đồng","A và B đều đúng","A và B đều sai"]}},
{"id":"ipr-266","q":"Sole license is","o":["the licensee will have no competition","the licensor will afford no licenses to other persons within the contractual territory","A and B are correct","A and B are incorrect"],"a":[1],"m":"ipr","c":1,"n":266,"f":1,"e":"Giấy phép sole: bên cấp phép không cấp phép cho người khác trong lãnh thổ.","vi":{"q":"Giấy phép độc quyền riêng (sole license) là","o":["bên được cấp phép sẽ không có đối thủ cạnh tranh","bên cấp phép sẽ không cấp phép cho bất kỳ người nào khác trong lãnh thổ theo hợp đồng","A và B đều đúng","A và B đều sai"]}},
{"id":"ipr-267","q":"Copyright license can only be made in writing","o":["True. Since the IP license can be granted only in written forms.","False. An IP license can be also granted orally but it is highly preferable if the agreement is in written form.","False. An IP license can only be made orally","None of the given statements are correct"],"a":[1],"m":"ipr","c":1,"n":267,"f":1,"e":"Giấy phép bản quyền có thể bằng lời nói nhưng nên lập thành văn bản.","vi":{"q":"Giấy phép bản quyền chỉ có thể được lập bằng văn bản","o":["Đúng. Vì giấy phép sở hữu trí tuệ chỉ có thể được cấp bằng văn bản.","Sai. Giấy phép sở hữu trí tuệ cũng có thể được cấp bằng lời nói nhưng rất nên lập thành văn bản.","Sai. Giấy phép sở hữu trí tuệ chỉ có thể được lập bằng lời nói","Không phát biểu nào ở trên đúng."]}},
{"id":"ipr-268","q":"The color or shape of an item, if distinctive, is","o":["a trade mark.","trade dress.","a copyright.","a patent."],"a":[1],"m":"ipr","c":5,"n":268,"e":"Màu sắc hoặc hình dạng của món đồ, nếu có tính phân biệt, là trade dress.","vi":{"q":"Màu sắc hoặc hình dạng của một món đồ, nếu có tính phân biệt, là","o":["một nhãn hiệu.","trade dress (diện mạo thương mại).","một bản quyền.","một sáng chế."]}},
{"id":"ipr-269","q":"Each of the following is considered trade dress except","o":["The white linen tablecloths at the Four Seasons Restaurant in New York City.","The font and size of print used in a national store's print advertising.","The brown uniforms and trucks at UPS.","The costume worn by your school's mascot at sporting and other events."],"a":[0],"m":"ipr","c":5,"n":269,"e":"Theo đáp án của đề, khăn trải bàn ở nhà hàng không phải trade dress (chỉ là trang trí chung); các phương án còn lại là yếu tố nhận diện thương hiệu.","vi":{"q":"Mỗi điều sau đây đều được coi là trade dress, ngoại trừ","o":["Khăn trải bàn bằng vải lanh trắng ở nhà hàng Four Seasons tại thành phố New York.","Phông chữ và cỡ chữ in dùng trong quảng cáo in của một chuỗi cửa hàng quốc gia.","Đồng phục và xe tải màu nâu của UPS.","Bộ trang phục do linh vật của trường bạn mặc trong các sự kiện thể thao và sự kiện khác."]}},
{"id":"ipr-270","q":"When a trade mark has become representative of a broad type of products as opposed to being descriptive of a particular brand, the trade mark has become........ and the holder has lost the right to enforce the mark against competitors.","o":["limited","authentic","original","generic"],"a":[3],"m":"ipr","c":4,"n":270,"e":"Khi nhãn hiệu trở thành tên chung của loại sản phẩm, nó trở thành generic và chủ mất quyền thực thi.","vi":{"q":"Khi một nhãn hiệu đã trở thành đại diện cho một loại sản phẩm nói chung thay vì mô tả một thương hiệu cụ thể, nhãn hiệu đó đã trở nên........ và chủ sở hữu mất quyền thực thi nhãn hiệu đó đối với đối thủ cạnh tranh.","o":["bị giới hạn (limited)","xác thực (authentic)","nguyên gốc (original)","chung chung (generic)"]}},
{"id":"ipr-271","q":"Trade marks indicate a specific producer.","o":["True","False"],"a":[0],"m":"ipr","c":4,"n":271,"e":"Nhãn hiệu có chức năng chỉ ra một nhà sản xuất hoặc nguồn gốc cụ thể.","vi":{"q":"Nhãn hiệu chỉ ra một nhà sản xuất cụ thể.","o":["Đúng","Sai"]}},
{"id":"ipr-272","q":"A trade mark is always protected, even if it loses its distinctiveness.","o":["True","False"],"a":[1],"m":"ipr","c":4,"n":272,"e":"Nhãn hiệu mất tính phân biệt thì mất bảo hộ, nên phát biểu «luôn được bảo hộ» là sai.","vi":{"q":"Một nhãn hiệu luôn được bảo hộ, ngay cả khi mất tính phân biệt.","o":["Đúng","Sai"]}},
{"id":"ipr-273","q":"What does NOT protects the intellectual property created by designers?","o":["Copyright","Patents","Registered designs","Design rights"],"a":[1],"m":"ipr","c":1,"n":273,"e":"Sáng chế không bảo hộ tài sản trí tuệ của nhà thiết kế (hình dáng); bản quyền, kiểu dáng đã đăng ký và quyền kiểu dáng thì có.","vi":{"q":"Quyền nào KHÔNG bảo hộ tài sản trí tuệ do các nhà thiết kế tạo ra?","o":["Bản quyền","Sáng chế","Kiểu dáng đã đăng ký","Quyền kiểu dáng"]}},
{"id":"ipr-274","q":"You write an original story, what type of intellectual property right that you can claim?","o":["Copyright","Trademarks","Registered designs","Patent"],"a":[0],"m":"ipr","c":2,"n":274,"e":"Câu chuyện nguyên gốc được bảo hộ bằng bản quyền.","vi":{"q":"Bạn viết một câu chuyện nguyên gốc, bạn có thể yêu cầu loại quyền sở hữu trí tuệ nào?","o":["Bản quyền","Nhãn hiệu","Kiểu dáng đã đăng ký","Sáng chế"]}},
{"id":"ipr-275","q":"Andy translates a book into Vietnamese with consent of the author. However, in this translated version, Andy re-arranges different parts of the book. Andy might commit infringement of....","o":["Translation right","Reproduction right","Integrity right","False attribution"],"a":[2],"m":"ipr","c":2,"n":275,"e":"Sắp xếp lại các phần của cuốn sách khi dịch làm thay đổi tác phẩm gốc, xâm phạm quyền toàn vẹn.","vi":{"q":"Andy dịch một cuốn sách sang tiếng Việt với sự đồng ý của tác giả. Tuy nhiên, trong bản dịch này, Andy sắp xếp lại các phần khác nhau của cuốn sách. Andy có thể đã xâm phạm....","o":["Quyền dịch thuật","Quyền sao chép","Quyền toàn vẹn tác phẩm (integrity right)","Việc gán sai tác giả"]}},
{"id":"ipr-276","q":"Ben covers a song with consent of the author. In addition to the name of the author, Ben adds his name to that song. Ben might.......","o":["commit infringement of reproduction right","commit infringement of paternity right","not commit infringement of intellectual property right","commit infringement of translation right"],"a":[1],"m":"ipr","c":2,"n":276,"e":"Thêm tên mình vào bài hát như đồng tác giả là gán sai/phủ nhận quyền được nhận là tác giả của tác giả gốc.","vi":{"q":"Ben hát lại (cover) một bài hát với sự đồng ý của tác giả. Ngoài tên tác giả, Ben thêm tên mình vào bài hát đó. Ben có thể.......","o":["xâm phạm quyền sao chép","xâm phạm quyền được nhận là tác giả (paternity right)","không xâm phạm quyền sở hữu trí tuệ nào","xâm phạm quyền dịch thuật"]}},
{"id":"ipr-277","q":"A literary work must be......... for being protected by copyright","o":["long","complex","Neither long nor complex","Long and complex"],"a":[2],"m":"ipr","c":2,"n":277,"e":"Tác phẩm văn học không cần dài hoặc phức tạp để được bảo hộ bản quyền.","vi":{"q":"Một tác phẩm văn học phải......... để được bảo hộ bản quyền","o":["dài","phức tạp","Không cần dài cũng không cần phức tạp","Vừa dài vừa phức tạp"]}},
{"id":"ipr-278","q":"A photograph is protected by..........","o":["copyright","patent","registered design","Trademark"],"a":[0],"m":"ipr","c":2,"n":278,"e":"Bức ảnh được bảo hộ bằng bản quyền (tác phẩm nghệ thuật).","vi":{"q":"Một bức ảnh được bảo hộ bởi..........","o":["bản quyền","sáng chế","kiểu dáng đã đăng ký","Nhãn hiệu"]}},
{"id":"ipr-279","q":"Copyright is NOT applied to..........","o":["Songs","Video tapes","Broadcasts","None of them"],"a":[3],"m":"ipr","c":2,"n":279,"f":1,"e":"Bản quyền áp dụng cho bài hát, băng video và chương trình phát sóng; nên «không loại nào là ngoại lệ».","vi":{"q":"Bản quyền KHÔNG áp dụng cho..........","o":["Bài hát","Băng video","Chương trình phát sóng","Không loại nào trong số đó"]}},
{"id":"ipr-280","q":"If a book cover is designed under the order of a publisher, the ownership of this page is..........","o":["The author of the book","The designer of this book cover","The publisher","Public"],"a":[2],"m":"ipr","c":2,"n":280,"e":"Theo đáp án của đề, nhà xuất bản đặt hàng thiết kế bìa là chủ sở hữu; xem cảnh báo bên dưới.","vi":{"q":"Nếu bìa sách được thiết kế theo đơn đặt hàng của nhà xuất bản, chủ sở hữu của trang bìa này là..........","o":["Tác giả cuốn sách","Người thiết kế bìa sách này","Nhà xuất bản","Công chúng"]},"k":"Theo luật Anh, nhà thiết kế làm tự do theo đơn đặt hàng thường vẫn là chủ sở hữu bản quyền nếu không có thỏa thuận chuyển nhượng (chỉ khi là nhân viên thì nhà xuất bản mới sở hữu, như câu #281). Đề chọn {C}."},
{"id":"ipr-281","q":"A designer is an employee of a publisher. Then, copyright of all his artistic works under employment contract is owned by.......","o":["This publisher","This designer","Both publisher and designer","Neither publisher nor designer"],"a":[0],"m":"ipr","c":2,"n":281,"e":"Tác phẩm do nhân viên tạo ra trong hợp đồng lao động thuộc về nhà tuyển dụng.","vi":{"q":"Một nhà thiết kế là nhân viên của một nhà xuất bản. Khi đó, bản quyền của mọi tác phẩm nghệ thuật của anh ta theo hợp đồng lao động thuộc về.......","o":["Nhà xuất bản này","Nhà thiết kế này","Cả nhà xuất bản và nhà thiết kế","Không phải nhà xuất bản cũng không phải nhà thiết kế"]}},
{"id":"ipr-282","q":"If copyright material is created by a computer, the owner of this copyright is..........","o":["The computer","The company producing this computer","The person making the arrangement necessary for that creation.","Nobody"],"a":[2],"m":"ipr","c":2,"n":282,"e":"Với tài liệu do máy tính tạo ra, chủ sở hữu là người thực hiện các sắp đặt cần thiết cho việc tạo ra.","vi":{"q":"Nếu tài liệu có bản quyền do máy tính tạo ra, chủ sở hữu bản quyền này là..........","o":["Chiếc máy tính","Công ty sản xuất chiếc máy tính này","Người thực hiện các sắp đặt cần thiết cho việc tạo ra đó.","Không ai cả"]}},
{"id":"ipr-283","q":"Paternity right.......","o":["Is similar to copyright","Lasts forever","can be transferred","Is given only to the author of an artistic works"],"a":[3],"m":"ipr","c":2,"n":283,"e":"Theo đáp án của đề chọn {D}; xem cảnh báo bên dưới.","vi":{"q":"Quyền được nhận là tác giả (paternity right).......","o":["Tương tự như bản quyền","Tồn tại vĩnh viễn","có thể chuyển nhượng","Chỉ dành cho tác giả của tác phẩm nghệ thuật"]},"k":"Đề chọn {D}. Thực tế quyền được nhận là tác giả áp dụng cho cả tác phẩm văn học, kịch, âm nhạc, nghệ thuật và đạo diễn phim (xem câu #5), nên đây chỉ là phương án «ít sai nhất» trong 4 phương án."},
{"id":"ipr-284","q":"Paternity right does NOT apply to:","o":["A book","Computer programmes","An article","A photograph"],"a":[1],"m":"ipr","c":2,"n":284,"e":"Chương trình máy tính không có quyền được nhận là tác giả (paternity right); sách, bài báo và ảnh thì có.","vi":{"q":"Quyền được nhận là tác giả (paternity right) KHÔNG áp dụng cho:","o":["Một cuốn sách","Chương trình máy tính","Một bài báo","Một bức ảnh"]}},
{"id":"ipr-285","q":"A hybrid car is intended for manufacture and the design is new and not commonplace, has an individual character. Which of the followings is WRONG?","o":["The car can be protected by a registered design.","The car can be protected by a design right.","The car cannot be protected by a registered right.","Both A&B"],"a":[2],"m":"ipr","c":6,"n":285,"f":1,"e":"Chiếc xe mới, không tầm thường, có tính độc đáo riêng nên bảo hộ được cả bằng kiểu dáng đã đăng ký lẫn quyền kiểu dáng; vì vậy phát biểu «không thể bảo hộ bằng kiểu dáng đã đăng ký» là sai.","vi":{"q":"Một chiếc xe hybrid dự định được sản xuất hàng loạt và thiết kế của nó mới, không tầm thường, có tính độc đáo riêng. Phát biểu nào sau đây SAI?","o":["Chiếc xe có thể được bảo hộ bằng kiểu dáng đã đăng ký.","Chiếc xe có thể được bảo hộ bằng quyền kiểu dáng (design right).","Chiếc xe không thể được bảo hộ bằng quyền đã đăng ký.","Cả A và B"]}},
{"id":"ipr-286","q":"Which of the followings is not a public domain material?","o":["Works expired copyrights","Works published by the United States government","A novel protected by Copyright","News and history"],"a":[2],"m":"ipr","c":2,"n":286,"e":"Tiểu thuyết còn được bảo hộ bản quyền thì không thuộc phạm vi công cộng; tác phẩm hết hạn, tài liệu của chính phủ Mỹ, tin tức và lịch sử thì có.","vi":{"q":"Điều nào sau đây không phải là tài liệu thuộc phạm vi công cộng (public domain)?","o":["Tác phẩm hết thời hạn bản quyền","Tác phẩm do chính phủ Hoa Kỳ xuất bản","Một cuốn tiểu thuyết đang được bảo hộ bản quyền","Tin tức và lịch sử"]}},
{"id":"ipr-287","q":"In most types of work, how long does copyright last for according to Bern Convention?","o":["10 years after the creation of the work","50 years after the creation of the work","10 years after the death of the person who created that work","50 years after the death of the person who created that work"],"a":[3],"m":"ipr","c":2,"n":287,"e":"Theo Berne, đa số tác phẩm được bảo hộ suốt đời tác giả cộng 50 năm sau khi tác giả mất.","vi":{"q":"Với hầu hết các loại tác phẩm, theo Công ước Berne bản quyền kéo dài bao lâu?","o":["10 năm sau khi tác phẩm được tạo ra","50 năm sau khi tác phẩm được tạo ra","10 năm sau khi người tạo ra tác phẩm qua đời","50 năm sau khi người tạo ra tác phẩm qua đời"]}},
{"id":"ipr-288","q":"Which of the following is RIGHT?","o":["As a copyright holder, you are compensated for fair use of your copyrighted work by others.","A teacher has copied a book for purpose of teaching. The teacher has to compensate for the book's copyright holder for the use.","A university professor has copied a book for purpose of his research. This is not an infringement of copynight.","If material is protected by copyright, in any cases, no anyone can use the material without copyright holder's permission."],"a":[2],"m":"ipr","c":3,"n":288,"e":"Giáo sư sao chép sách để nghiên cứu là ngoại lệ (fair dealing: nghiên cứu), không phải xâm phạm.","vi":{"q":"Điều nào sau đây ĐÚNG?","o":["Với tư cách chủ sở hữu bản quyền, bạn được đền bù khi người khác sử dụng hợp lý (fair use) tác phẩm có bản quyền của bạn.","Một giáo viên đã sao chép một cuốn sách để giảng dạy. Giáo viên đó phải đền bù cho chủ sở hữu bản quyền cuốn sách về việc sử dụng này.","Một giáo sư đại học đã sao chép một cuốn sách để phục vụ nghiên cứu của mình. Đây không phải là xâm phạm bản quyền.","Nếu tài liệu được bảo hộ bản quyền thì trong mọi trường hợp, không ai được sử dụng tài liệu đó mà không có sự cho phép của chủ sở hữu bản quyền."]}},
{"id":"ipr-289","q":"According to Vietnam law, duration of economics right in literature work:","o":["Lasts for 50 years from the year the film or record was made or, if it is released to the public, 50 years from its release","Lasts for the life of its creator plus a further 50 years.","Lasts for 70 years begins to run on the death of the last surviving creator if two or more authors were jointly involved in the work","Lasts for 75 years from the end of the year in which the film was created"],"a":[1],"m":"ipr","c":2,"n":289,"e":"Theo luật Việt Nam, quyền kinh tế đối với tác phẩm văn học kéo dài suốt đời tác giả cộng 50 năm.","vi":{"q":"Theo luật Việt Nam, thời hạn bảo hộ quyền kinh tế đối với tác phẩm văn học:","o":["Kéo dài 50 năm kể từ năm phim hoặc bản ghi được tạo ra, hoặc nếu được công bố ra công chúng thì 50 năm kể từ khi công bố","Suốt đời người sáng tạo cộng thêm 50 năm.","70 năm, bắt đầu tính từ khi người sáng tạo cuối cùng qua đời nếu có hai hay nhiều tác giả cùng tham gia tạo ra tác phẩm","75 năm kể từ cuối năm mà bộ phim được tạo ra"]}},
{"id":"ipr-290","q":"A design of a television set being intended for manufacture is new and has an individual character. The design is also not commonplace. What IPRs can simultaneously protect the design?","o":["Trademarks; and Copyright.","Registered Design; and Design Right.","Copyright, and Registered Design.","Copyright; Trademarks; and Registered Design."],"a":[2],"m":"ipr","c":1,"n":290,"e":"Thiết kế ti vi được bảo hộ đồng thời bằng bản quyền (bản vẽ) và kiểu dáng đã đăng ký (hình dáng); nhãn hiệu không bảo hộ thiết kế; quyền kiểu dáng bị loại khi đã đăng ký.","vi":{"q":"Thiết kế của một chiếc ti vi dự định được sản xuất là mới và có tính độc đáo riêng. Thiết kế đó cũng không tầm thường. Những quyền sở hữu trí tuệ nào có thể bảo hộ thiết kế này đồng thời?","o":["Nhãn hiệu; và Bản quyền.","Kiểu dáng đã đăng ký; và Quyền kiểu dáng.","Bản quyền, và Kiểu dáng đã đăng ký.","Bản quyền; Nhãn hiệu; và Kiểu dáng đã đăng ký."]}},
{"id":"ipr-291","q":"Which of the following is a generic term?","o":["\"car\" for cars","\"Apple' for computers","\"Camel\" for cigarettes","\"Kodak\" for cameras"],"a":[0],"m":"ipr","c":4,"n":291,"e":"«Car» cho ô tô là tên gọi chung (generic) nên không có tính phân biệt.","vi":{"q":"Thuật ngữ nào sau đây là thuật ngữ chung (generic)?","o":["\"car\" (ô tô) cho ô tô","\"Apple\" cho máy tính","\"Camel\" cho thuốc lá","\"Kodak\" cho máy ảnh"]}},
{"id":"ipr-292","q":"What does three stripes on Adidas clothing represent?","o":["A trade mark.","Trade dress.","A trade secret.","A patent."],"a":[0],"m":"ipr","c":5,"n":292,"e":"Ba sọc của Adidas là dấu hiệu nhận diện nguồn gốc, tức một nhãn hiệu.","vi":{"q":"Ba sọc trên quần áo Adidas đại diện cho điều gì?","o":["Một nhãn hiệu.","Trade dress (diện mạo thương mại).","Một bí mật thương mại.","Một sáng chế."]}},
{"id":"ipr-293","q":"Company H designs a new type of fuse holder. Company M has copied freely the parts of the holder that actually contact the fuse. Which of the following is RIGHT?","o":["Company M infringed Company H's Design right.","Company M have to obtain Company H's permission before coping the parts","Company M can copy and produced the parts without Company H's permission","Company H can request Company M for a Design right compensation."],"a":[0],"m":"ipr","c":6,"n":293,"e":"Theo đáp án của đề, Công ty M xâm phạm quyền kiểu dáng; xem cảnh báo bên dưới về ngoại lệ must-fit.","vi":{"q":"Công ty H thiết kế một loại đế cầu chì mới. Công ty M đã sao chép tự do những phần của đế cầu chì tiếp xúc trực tiếp với cầu chì. Phát biểu nào sau đây ĐÚNG?","o":["Công ty M đã xâm phạm quyền kiểu dáng của Công ty H.","Công ty M phải xin phép Công ty H trước khi sao chép các bộ phận đó","Công ty M có thể sao chép và sản xuất các bộ phận đó mà không cần sự cho phép của Công ty H","Công ty H có thể yêu cầu Công ty M bồi thường quyền kiểu dáng."]},"k":"Đề chọn {A}, nhưng các bộ phận tiếp xúc trực tiếp với cầu chì thuộc ngoại lệ «must fit» (phải khớp với sản phẩm khác) nên không được bảo hộ quyền kiểu dáng — tức {C} mới sát luật; xem câu #154 và #315."},
{"id":"ipr-294","q":"In a case on Design rights dispute, if the design right owner succeeds in proving the infringement, what cannot the Court award?","o":["An injunction to stop further manufacture or import","An arrest warrant for the infringer","Order payment of damages (e.g. for loss of sales by the design right owner)","The destruction of the offending articles produced during the previous 6 years or handing them over to the design right owner"],"a":[1],"m":"ipr","c":6,"n":294,"e":"Tòa án có thể tuyên cấm, buộc bồi thường, tiêu hủy hoặc giao nộp hàng vi phạm, nhưng không ra lệnh bắt giữ người vi phạm trong vụ kiện dân sự.","vi":{"q":"Trong một vụ tranh chấp quyền kiểu dáng, nếu chủ sở hữu quyền kiểu dáng thắng kiện chứng minh được hành vi xâm phạm, Tòa án KHÔNG thể tuyên điều gì?","o":["Lệnh cấm tiếp tục sản xuất hoặc nhập khẩu","Lệnh bắt giữ người vi phạm","Buộc trả tiền bồi thường thiệt hại (ví dụ cho việc mất doanh số của chủ sở hữu quyền kiểu dáng)","Tiêu hủy các sản phẩm vi phạm được sản xuất trong 6 năm trước đó hoặc giao chúng cho chủ sở hữu quyền kiểu dáng"]}},
{"id":"ipr-295","q":"In which case you are the creator of an Intellectual Property?","o":["You employed someone creating the intellectual property.","You created the intellectual property by yourself.","You bought the intellectual property rights from the previous owner of the property.","You are donated the intellectual property rights from the previous owner of the property."],"a":[1],"m":"ipr","c":1,"n":295,"e":"Bạn là người sáng tạo khi tự mình tạo ra tài sản trí tuệ; thuê, mua hay được tặng quyền không làm bạn thành người sáng tạo.","vi":{"q":"Trong trường hợp nào bạn là người sáng tạo ra tài sản trí tuệ?","o":["Bạn thuê người khác tạo ra tài sản trí tuệ.","Bạn tự mình tạo ra tài sản trí tuệ.","Bạn mua quyền sở hữu trí tuệ từ chủ sở hữu trước của tài sản đó.","Bạn được chủ sở hữu trước tặng quyền sở hữu trí tuệ đối với tài sản đó."]}},
{"id":"ipr-296","q":"According to current Vietnam Intellectual Property Law, Intellectual Property Rights includes:","o":["Literatural works; Designs; Trademark.","Copyright and rights related to copyright; Industrial property rights; Rights to plant varieties.","Rights to tangible property","Both of a&b"],"a":[1],"m":"ipr","c":1,"n":296,"f":1,"e":"Quyền sở hữu trí tuệ theo luật Việt Nam gồm quyền tác giả và quyền liên quan, quyền sở hữu công nghiệp, quyền đối với giống cây trồng.","vi":{"q":"Theo Luật Sở hữu trí tuệ hiện hành của Việt Nam, quyền sở hữu trí tuệ bao gồm:","o":["Tác phẩm văn học; Kiểu dáng; Nhãn hiệu.","Quyền tác giả và quyền liên quan; Quyền sở hữu công nghiệp; Quyền đối với giống cây trồng.","Quyền đối với tài sản hữu hình","Cả a và b"]}},
{"id":"ipr-297","q":"Which of the IP Laws below currently having legal validity in Viet Nam?","o":["The Intellectual Property Law No. 50/2005/QH11","The Intellectual Property Law No. 50/2005/QH11 having been amended and supplemented in accordance with the Law No. 36/2009/QH12; the Law No. 42/2019/QH14; and the Law No. 07/2022/QH15","The Intellectual Property Law No. 50/2005/QH11 having been amended and supplemented in accordance with the Law No. 36/2009/QH12 and the Law No. 42/2019/QH14.","All of the above"],"a":[1],"m":"ipr","c":1,"n":297,"f":1,"e":"Luật SHTT hiện hành là Luật 50/2005/QH11 đã được sửa đổi, bổ sung bởi các Luật 36/2009, 42/2019 và 07/2022.","vi":{"q":"Luật Sở hữu trí tuệ nào dưới đây hiện đang có hiệu lực pháp luật ở Việt Nam?","o":["Luật Sở hữu trí tuệ số 50/2005/QH11","Luật Sở hữu trí tuệ số 50/2005/QH11 được sửa đổi, bổ sung theo Luật số 36/2009/QH12; Luật số 42/2019/QH14; và Luật số 07/2022/QH15","Luật Sở hữu trí tuệ số 50/2005/QH11 được sửa đổi, bổ sung theo Luật số 36/2009/QH12 và Luật số 42/2019/QH14.","Tất cả các đáp án trên"]}},
{"id":"ipr-298","q":"What is the \"public interest\" principle with regard to IP protection?","o":["It means that the protection and exercise of IP rights must be for the interests of the general public.","It means that the protection and exercise of IP rights must be for the profits of public corporations having important role for national economic development.","It means that the protection and exercise of IP rights must be balanced with the public interest, and that a balance must be maintained between the interests of right holders and the general public.","It means that the protection and exercise of IP rights must be for the interests of IP right holders."],"a":[2],"m":"ipr","c":1,"n":298,"e":"Nguyên tắc lợi ích công cộng: bảo hộ và thực thi quyền sở hữu trí tuệ phải cân bằng giữa lợi ích của chủ sở hữu quyền và của công chúng.","vi":{"q":"Nguyên tắc \"lợi ích công cộng\" (public interest) trong bảo hộ sở hữu trí tuệ là gì?","o":["Nghĩa là việc bảo hộ và thực thi quyền sở hữu trí tuệ phải vì lợi ích của công chúng nói chung.","Nghĩa là việc bảo hộ và thực thi quyền sở hữu trí tuệ phải vì lợi nhuận của các tập đoàn nhà nước có vai trò quan trọng đối với phát triển kinh tế quốc gia.","Nghĩa là việc bảo hộ và thực thi quyền sở hữu trí tuệ phải cân bằng với lợi ích công cộng, và phải duy trì sự cân bằng giữa lợi ích của chủ sở hữu quyền và của công chúng.","Nghĩa là việc bảo hộ và thực thi quyền sở hữu trí tuệ phải vì lợi ích của chủ sở hữu quyền sở hữu trí tuệ."]}},
{"id":"ipr-299","q":"A design for a car body is registered. Can the same design be used for:","o":["A toy car","A chocolate bar","A print on a tea towel","Not any of A,B&C"],"a":[3],"m":"ipr","c":6,"n":299,"f":1,"e":"Kiểu dáng đã đăng ký cho thân xe bảo hộ thiết kế đó cho mọi loại sản phẩm, nên không ai được dùng cho đồ chơi, sô-cô-la hay họa tiết khăn mà không xin phép.","vi":{"q":"Một thiết kế thân xe ô tô đã được đăng ký. Cùng thiết kế đó có thể được dùng cho:","o":["Một chiếc ô tô đồ chơi","Một thanh sô-cô-la","Họa tiết in trên khăn lau chén","Không trường hợp nào trong A, B và C"]}},
{"id":"ipr-300","q":"According to TRIPS, a registered mark can give the owner....","o":["Exclusive right to prevent use by a third party in the course of trade of an identical or similar sign for identical or similar goods","Exclusive right to prevent use by a third party in the course of trade of an identical or similar sign for identical or similar services","Exclusive right to prevent use by a third party in the course of trade of an identical or similar sign for identical or similar goods and services","Exclusive right to prevent use by a third party in the course of trade of an identical or similar sign for different goods"],"a":[2],"m":"ipr","c":4,"n":300,"e":"Theo TRIPS, nhãn hiệu đã đăng ký cho quyền ngăn bên thứ ba dùng dấu hiệu giống hoặc tương tự cho hàng hóa và dịch vụ giống hoặc tương tự.","vi":{"q":"Theo TRIPS, một nhãn hiệu đã đăng ký có thể trao cho chủ sở hữu....","o":["Quyền độc quyền ngăn bên thứ ba sử dụng trong hoạt động thương mại một dấu hiệu giống hệt hoặc tương tự cho hàng hóa giống hệt hoặc tương tự","Quyền độc quyền ngăn bên thứ ba sử dụng trong hoạt động thương mại một dấu hiệu giống hệt hoặc tương tự cho dịch vụ giống hệt hoặc tương tự","Quyền độc quyền ngăn bên thứ ba sử dụng trong hoạt động thương mại một dấu hiệu giống hệt hoặc tương tự cho hàng hóa và dịch vụ giống hệt hoặc tương tự","Quyền độc quyền ngăn bên thứ ba sử dụng trong hoạt động thương mại một dấu hiệu giống hệt hoặc tương tự cho hàng hóa khác nhau"]}},
{"id":"ipr-301","q":"Which of the following is NOT a type of Intellectual Property Right (IPR)?","o":["Patent","Copyright","Trademark","Real Estate Ownership"],"a":[3],"m":"ipr","c":1,"n":301,"e":"Quyền sở hữu bất động sản là quyền tài sản thông thường, không phải quyền sở hữu trí tuệ.","vi":{"q":"Điều nào sau đây KHÔNG phải là một loại quyền sở hữu trí tuệ (IPR)?","o":["Sáng chế","Bản quyền","Nhãn hiệu","Quyền sở hữu bất động sản"]}},
{"id":"ipr-302","q":"Which of the following cannot be registered as a design under the Registered Designs Act?","o":["A sculpture","A computer program","A vehicle's external shape","A typeface"],"a":[1],"m":"ipr","c":6,"n":302,"e":"Chương trình máy tính không đăng ký được làm kiểu dáng; tác phẩm điêu khắc, hình dáng ngoài của xe và kiểu chữ thì có.","vi":{"q":"Điều nào sau đây không thể được đăng ký làm kiểu dáng theo Đạo luật Kiểu dáng Đã đăng ký (Registered Designs Act)?","o":["Một tác phẩm điêu khắc","Một chương trình máy tính","Hình dáng bên ngoài của một chiếc xe","Một kiểu chữ (typeface)"]}},
{"id":"ipr-303","q":"What is the main domestic law applicable in the UK for copyright?","o":["The Copyright, Designs and Patents Act 1988 and its revision","A WIPO Treaty on Copyright","EU directives on e-commerce and digital copyright","The Patents Act 1977"],"a":[0],"m":"ipr","c":2,"n":303,"e":"Luật chính về bản quyền ở Anh là CDPA 1988 và các bản sửa đổi.","vi":{"q":"Luật nội địa chính áp dụng cho bản quyền ở Anh là gì?","o":["Đạo luật Bản quyền, Kiểu dáng và Sáng chế 1988 và các bản sửa đổi","Một hiệp ước của WIPO về bản quyền","Các chỉ thị của EU về thương mại điện tử và bản quyền kỹ thuật số","Đạo luật Sáng chế 1977"]}},
{"id":"ipr-304","q":"What is the requirement for an invented word to be a trade mark?","o":["It must be distinctive","It must be meaningful","It must indicate the nature of the products","It must be new"],"a":[0],"m":"ipr","c":4,"n":304,"e":"Từ tự đặt ra chỉ cần có tính phân biệt để làm nhãn hiệu.","vi":{"q":"Điều kiện để một từ tự đặt ra (invented word) trở thành nhãn hiệu là gì?","o":["Phải có tính phân biệt","Phải có ý nghĩa","Phải chỉ ra bản chất của sản phẩm","Phải mới"]}},
{"id":"ipr-305","q":"What are the basic requirements that trade mark should be?","o":["Easy to remember and sufficiently different from marks used by competitors","Easy to remember and creating confusion","Distinctive and confusion","All are correct"],"a":[0],"m":"ipr","c":4,"n":305,"f":1,"e":"Nhãn hiệu cần dễ nhớ và đủ khác so với nhãn hiệu đối thủ.","vi":{"q":"Các yêu cầu cơ bản mà một nhãn hiệu cần đáp ứng là gì?","o":["Dễ nhớ và đủ khác biệt so với nhãn hiệu của đối thủ","Dễ nhớ và tạo ra sự nhầm lẫn","Có tính phân biệt và gây nhầm lẫn","Tất cả đều đúng"]}},
{"id":"ipr-306","q":"Which is not the way of recovering the cost of developing an engineering technology (an IP)?","o":["Both of b&d","Granting a license to a company, who all paid a royalty for the right to use the IP.","Applying for the IP registration at an authorized State agency.","Making a product and selling it, with the IPR keeping competitors out of the market."],"a":[2],"m":"ipr","c":1,"n":306,"f":1,"e":"Nộp đơn đăng ký chỉ là cách có được quyền, không phải cách thu hồi chi phí; cấp phép thu royalty và sản xuất bán hàng được bảo hộ là cách thu hồi.","vi":{"q":"Cách nào sau đây không phải là cách thu hồi chi phí phát triển một công nghệ kỹ thuật (một tài sản trí tuệ)?","o":["Cả b và d","Cấp phép cho một công ty, công ty đó trả tiền bản quyền (royalty) để được sử dụng tài sản trí tuệ.","Nộp đơn đăng ký tài sản trí tuệ tại cơ quan nhà nước có thẩm quyền.","Sản xuất sản phẩm và bán, với quyền sở hữu trí tuệ giúp ngăn đối thủ khỏi thị trường."]}},
{"id":"ipr-307","q":"Assuming that an article is not common place, if this article could have been protected by a registered design but no application was filed, what is the potential result?","o":["It will be protected by design right.","It will be protected by trademark","It will be protected by copyright","All are not correct"],"a":[0],"m":"ipr","c":6,"n":307,"f":1,"e":"Sản phẩm không tầm thường nhưng không đăng ký kiểu dáng thì có thể được bảo hộ tự động bằng quyền kiểu dáng.","vi":{"q":"Giả sử một sản phẩm không tầm thường, nếu sản phẩm này có thể được bảo hộ bằng kiểu dáng đã đăng ký nhưng không có đơn nào được nộp, thì kết quả có thể xảy ra là gì?","o":["Nó sẽ được bảo hộ bằng quyền kiểu dáng.","Nó sẽ được bảo hộ bằng nhãn hiệu","Nó sẽ được bảo hộ bằng bản quyền","Tất cả đều không đúng"]}},
{"id":"ipr-308","q":"Which of the following is not a moral right in Vietnamese IP law?","o":["Right to make copies","Right to attribution","None of the options","Right to publish the work"],"a":[0],"m":"ipr","c":2,"n":308,"f":1,"e":"Quyền sao chép là quyền tài sản; đặt tên, công bố tác phẩm là quyền nhân thân.","vi":{"q":"Điều nào sau đây không phải là quyền nhân thân theo luật sở hữu trí tuệ Việt Nam?","o":["Quyền sao chép","Quyền được nêu tên (attribution)","Không có lựa chọn nào","Quyền công bố tác phẩm"]}},
{"id":"ipr-309","q":"The standard that must be met for a plaintiff to win a trade mark dilution claim is the likelihood of confusion.","o":["Yes. Likelihood of confusion is the key indicator to identify a trade mark infringement.","No. Since dilution is a form of damage in passing off, the plaintiff must show there is a reputation in the mark or get-up; there has been confusion in the marketplace, and the owner has suffered damage to win the claim.","No. The damage is the fundamental indicator in a dilution claim, that the plaintiff must prove to win the ca","There are no correct answers"],"a":[3],"m":"ipr","c":5,"n":309,"e":"Theo đáp án của đề không phương án nào đúng: pha loãng nhãn hiệu không đòi hỏi khả năng gây nhầm lẫn mà liên quan đến suy giảm giá trị của nhãn hiệu nổi tiếng.","vi":{"q":"Tiêu chuẩn mà nguyên đơn phải đáp ứng để thắng kiện về pha loãng nhãn hiệu (trade mark dilution) là khả năng gây nhầm lẫn.","o":["Đúng. Khả năng gây nhầm lẫn là chỉ báo then chốt để xác định hành vi xâm phạm nhãn hiệu.","Không. Vì pha loãng là một dạng thiệt hại trong passing off, nguyên đơn phải chứng minh có uy tín đối với nhãn hiệu hoặc get-up; đã có sự nhầm lẫn trên thị trường, và chủ sở hữu đã bị thiệt hại thì mới thắng kiện.","Không. Thiệt hại là chỉ báo cơ bản trong khiếu kiện pha loãng, nguyên đơn phải chứng minh điều đó để thắng kiện","Không có đáp án nào đúng"]}},
{"id":"ipr-310","q":"If the design is NOT put to practical use,.....","o":["Its legal protection shall last for 10 years from the time it is created","Its legal protection shall last for 15 years from the time it is created","Its legal protection shall last for 05 years from the time it is created","Its legal protection shall last for 20 years from the time it is created"],"a":[2],"m":"ipr","c":6,"n":310,"e":"Theo đáp án của đề, thiết kế chưa đưa vào sử dụng được bảo hộ 5 năm; xem cảnh báo bên dưới.","vi":{"q":"Nếu thiết kế CHƯA được đưa vào sử dụng thực tế,.....","o":["Sự bảo hộ pháp lý kéo dài 10 năm kể từ thời điểm thiết kế được tạo ra","Sự bảo hộ pháp lý kéo dài 15 năm kể từ thời điểm thiết kế được tạo ra","Sự bảo hộ pháp lý kéo dài 05 năm kể từ thời điểm thiết kế được tạo ra","Sự bảo hộ pháp lý kéo dài 20 năm kể từ thời điểm thiết kế được tạo ra"]},"k":"Theo quyền kiểu dáng (design right) của Anh, nếu chưa đưa ra thị trường thì thời hạn là 15 năm kể từ cuối năm tạo ra thiết kế (phương án {B}); còn nếu đã bán/cho thuê/quảng cáo thì 10 năm (xem câu #161). Đề chọn {C} (5 năm)."},
{"id":"ipr-311","q":"Which is litigation model applied in the countries used the civil law system?","o":["Adversarial litigation","Inquisitorial litigation","Civil procedure","Court procedure"],"a":[1],"m":"ipr","c":1,"n":311,"e":"Các nước theo hệ thống luật dân sự áp dụng mô hình tố tụng thẩm vấn (inquisitorial).","vi":{"q":"Mô hình tố tụng nào được áp dụng ở các nước theo hệ thống luật dân sự (civil law)?","o":["Tố tụng tranh tụng (adversarial)","Tố tụng thẩm vấn (inquisitorial)","Thủ tục dân sự","Thủ tục tòa án"]}},
{"id":"ipr-312","q":"Who traditionally owns the copyright in a sound recording?","o":["The composer of the music","The person who performs the music","The person making the arrangements necessary for the recording to be made, typically the producer","The recording studio"],"a":[2],"m":"ipr","c":2,"n":312,"e":"Chủ sở hữu bản quyền bản ghi âm thường là người sắp xếp việc ghi âm, tức nhà sản xuất.","vi":{"q":"Ai thường sở hữu bản quyền đối với một bản ghi âm?","o":["Nhà soạn nhạc","Người biểu diễn bản nhạc","Người thực hiện các sắp đặt cần thiết để bản ghi được thực hiện, thường là nhà sản xuất","Phòng thu âm"]}},
{"id":"ipr-313","q":"Company X pays Company Y for one copy of a program such as a word processing or accountancy packag for a PC (Company Y is the owner of the program). Company X then makes copies for every PC in the company without the permission of the Company Y. Which of the following option is wrong?","o":["Company Y can sue Company X for the Copyright Infringement.","Company X can make copies of the program for every PC in the company for internal use only within the company as it has paid for the program already.","Company X does not have the right to make copies for every PC in the company, unless the accompanying license gives this permission.","Both of a&c"],"a":[1],"m":"ipr","c":3,"n":313,"f":1,"e":"Mua một bản chương trình không cho phép sao chép cho mọi máy trong công ty; trừ khi giấy phép cho phép, đó là xâm phạm, nên phát biểu {B} là sai.","vi":{"q":"Công ty X trả tiền cho Công ty Y để mua một bản chương trình, ví dụ phần mềm soạn thảo văn bản hoặc kế toán, cho một máy tính (Công ty Y là chủ sở hữu chương trình). Sau đó Công ty X sao chép cho mọi máy tính trong công ty mà không có sự cho phép của Công ty Y. Phương án nào sau đây là sai?","o":["Công ty Y có thể kiện Công ty X về hành vi xâm phạm bản quyền.","Công ty X có thể sao chép chương trình cho mọi máy tính trong công ty để chỉ dùng nội bộ vì đã trả tiền mua chương trình rồi.","Công ty X không có quyền sao chép cho mọi máy tính trong công ty, trừ khi giấy phép kèm theo cho phép việc này.","Cả a và c"]}},
{"id":"ipr-314","q":"According to Vietnam law, duration of moral right in literature work:","o":["Lasts for 50 years from the year the film or record was made or, if it is released to the public, 50 years fro its release","Lasts for the life of its creator plus a further 50 years.","Lasts for 70 years begins to run on the death of the last surviving creator if two or more authors were jointly involved in the work","Lasts forever"],"a":[3],"m":"ipr","c":2,"n":314,"e":"Theo đáp án của đề, quyền nhân thân đối với tác phẩm văn học theo luật Việt Nam được bảo hộ vô thời hạn.","vi":{"q":"Theo luật Việt Nam, thời hạn bảo hộ quyền nhân thân đối với tác phẩm văn học:","o":["Kéo dài 50 năm kể từ năm phim hoặc bản ghi được tạo ra, hoặc nếu được công bố ra công chúng thì 50 năm kể từ khi công bố","Suốt đời người sáng tạo cộng thêm 50 năm.","70 năm, bắt đầu tính từ khi người sáng tạo cuối cùng qua đời nếu có hai hay nhiều tác giả cùng tham gia tạo ra tác phẩm","Vĩnh viễn"]}},
{"id":"ipr-315","q":"In the context of the 'must fit' exception, which of the following scenarios is true?","o":["The entire car exhaust system can be copied without permission","The design of a contact lens front surface can be copied","Only the parts of an exhaust system that connect to the car can be copied","The overall shape of a car cannot be copied"],"a":[2],"m":"ipr","c":6,"n":315,"e":"Theo ngoại lệ must-fit, chỉ các bộ phận dùng để nối với ô tô có thể sao chép; không được sao chép toàn bộ hệ thống ống xả hay hình dáng tổng thể.","vi":{"q":"Trong bối cảnh ngoại lệ 'must fit' (phải khớp), tình huống nào sau đây đúng?","o":["Có thể sao chép toàn bộ hệ thống ống xả của ô tô mà không cần xin phép","Có thể sao chép thiết kế mặt trước của kính áp tròng","Chỉ có thể sao chép những bộ phận của hệ thống ống xả dùng để nối với ô tô","Không thể sao chép hình dáng tổng thể của một chiếc ô tô"]}},
{"id":"ipr-316","q":"Distinguishing those products from the products of competitors and being capable of indicating goods or services originating from a particular source are.... element of trade mark","o":["Comparative","Original","Distinctive","Memorable"],"a":[2],"m":"ipr","c":4,"n":316,"e":"Khả năng phân biệt hàng hóa/dịch vụ và chỉ ra nguồn gốc là yếu tố phân biệt (distinctive) của nhãn hiệu.","vi":{"q":"Việc phân biệt các sản phẩm đó với sản phẩm của đối thủ và có khả năng chỉ ra hàng hóa hoặc dịch vụ có nguồn gốc từ một chủ thể nhất định là yếu tố .... của nhãn hiệu","o":["So sánh (comparative)","Nguyên gốc (original)","Phân biệt (distinctive)","Dễ nhớ (memorable)"]}},
{"id":"ipr-317","q":"Which of the following is NOT a copyright infringement according to the UK law?","o":["Copying in a different medium to the original work, such as a photocopy of a book, or a scanned-in digital copy of a photograph","Making a short-term or transient copy","Speaking words aloud without making a copy whether by shorthand or on tape","Making an object in three dimensions from a drawing of that object"],"a":[2],"m":"ipr","c":3,"n":317,"e":"Đọc to các từ mà không tạo bản sao không phải sao chép nên không xâm phạm.","vi":{"q":"Điều nào sau đây KHÔNG phải là hành vi xâm phạm bản quyền theo luật Anh?","o":["Sao chép sang một phương tiện khác với tác phẩm gốc, như photocopy một cuốn sách hoặc bản sao kỹ thuật số quét từ một bức ảnh","Tạo ra một bản sao tạm thời hoặc ngắn hạn","Đọc to các từ mà không tạo bản sao, dù bằng tốc ký hay trên băng","Làm một vật thể ba chiều từ bản vẽ của chính vật thể đó"]}},
{"id":"ipr-318","q":"If an owner of copyright believes the material it protects is being copied without permission, which are the courts the owner will take a legal action for the infringement?","o":["Courts having the jurisdiction on labor cases.","Civil courts.","Courts having the jurisdiction on marriage issues","Courts having the jurisdiction on administrative cases."],"a":[1],"m":"ipr","c":1,"n":318,"e":"Vụ kiện xâm phạm bản quyền được khởi kiện tại tòa án dân sự.","vi":{"q":"Nếu chủ sở hữu bản quyền tin rằng tài liệu được bảo hộ đang bị sao chép mà không có sự cho phép, chủ sở hữu sẽ khởi kiện về hành vi xâm phạm tại tòa án nào?","o":["Tòa án có thẩm quyền về các vụ việc lao động.","Tòa án dân sự.","Tòa án có thẩm quyền về các vấn đề hôn nhân","Tòa án có thẩm quyền về các vụ việc hành chính."]}},
{"id":"ipr-319","q":"Why is protection of Intellectual Property Rights (IPRs) significant? (check all that apply)","o":["Encouraging creations and innovations","Protecting innovations and investments required for the development of advanced technologies.","Not sustaining long-term social growth.","Promoting a comprehensive cooperation among countries worldwide."],"a":[0,1,3],"m":"ipr","c":1,"n":319,"e":"Bảo hộ quyền sở hữu trí tuệ khuyến khích sáng tạo, bảo vệ đầu tư vào công nghệ, thúc đẩy hợp tác quốc tế; không phải «không duy trì tăng trưởng xã hội».","vi":{"q":"Vì sao việc bảo hộ quyền sở hữu trí tuệ (IPR) có ý nghĩa quan trọng? (chọn tất cả đáp án đúng)","o":["Khuyến khích sáng tạo và đổi mới","Bảo vệ các đổi mới và khoản đầu tư cần thiết để phát triển các công nghệ tiên tiến.","Không duy trì tăng trưởng xã hội dài hạn.","Thúc đẩy hợp tác toàn diện giữa các quốc gia trên toàn thế giới."]}},
{"id":"ipr-320","q":"Computer program can be simultaneously protected by:","o":["Trade Mark and Registered Design","Copyright, Patent and Confidential Information","Design Right, Trade Mark and Copyright","Trade secret and Trade Mark"],"a":[1],"m":"ipr","c":1,"n":320,"e":"Chương trình máy tính có thể được bảo hộ đồng thời bằng bản quyền, sáng chế và thông tin bí mật.","vi":{"q":"Chương trình máy tính có thể được bảo hộ đồng thời bởi:","o":["Nhãn hiệu và Kiểu dáng đã đăng ký","Bản quyền, Sáng chế và Thông tin bí mật","Quyền kiểu dáng, Nhãn hiệu và Bản quyền","Bí mật thương mại và Nhãn hiệu"]}},
{"id":"ipr-321","q":"What happens to copyright protection when minor bug-fixing changes are made to a computer program?","o":["The program loses its copyright protection","The former copyright still applies","A new copyright must be filed","The changes are not protected by copyright"],"a":[1],"m":"ipr","c":2,"n":321,"e":"Chỉnh sửa nhỏ để sửa lỗi không làm mất bản quyền; bản quyền trước đó vẫn áp dụng.","vi":{"q":"Điều gì xảy ra với sự bảo hộ bản quyền khi có những thay đổi nhỏ để sửa lỗi (bug-fixing) trong một chương trình máy tính?","o":["Chương trình mất sự bảo hộ bản quyền","Bản quyền trước đó vẫn áp dụng","Phải nộp đăng ký bản quyền mới","Những thay đổi không được bảo hộ bản quyền"]}},
{"id":"ipr-322","q":"What entity typically owns the copyright in a broadcast?","o":["The director of the broadcast","The actors in the broadcast","The broadcasting company that makes the broadcast","The viewers of the broadcast"],"a":[2],"m":"ipr","c":2,"n":322,"e":"Công ty phát sóng thực hiện chương trình thường là chủ sở hữu bản quyền chương trình phát sóng.","vi":{"q":"Chủ thể nào thường sở hữu bản quyền đối với một chương trình phát sóng?","o":["Đạo diễn của chương trình phát sóng","Các diễn viên trong chương trình phát sóng","Công ty phát sóng thực hiện chương trình","Khán giả xem chương trình"]}},
{"id":"ipr-323","q":"What does copyright in software include?","o":["Protection of the code and related documentation","Only the visual design","Only the underlying ideas","Only the user interface"],"a":[0],"m":"ipr","c":2,"n":323,"e":"Bản quyền phần mềm bảo hộ mã nguồn và tài liệu liên quan.","vi":{"q":"Bản quyền phần mềm bao gồm những gì?","o":["Bảo hộ mã nguồn và tài liệu liên quan","Chỉ thiết kế hình ảnh","Chỉ các ý tưởng nền tảng","Chỉ giao diện người dùng"]}},
{"id":"ipr-324","q":"What must an idea have to be protected by copyright?","o":["Be original and registered","Be expressed in a tangible form","Be reviewed by an authority","Be published"],"a":[1],"m":"ipr","c":2,"n":324,"e":"Ý tưởng chỉ được bảo hộ bản quyền khi được thể hiện dưới dạng hữu hình (expression).","vi":{"q":"Một ý tưởng phải có điều gì để được bảo hộ bản quyền?","o":["Nguyên gốc và đã đăng ký","Được thể hiện dưới dạng hữu hình","Được một cơ quan thẩm định","Được công bố"]}},
{"id":"ipr-325","q":"Which of the following is incorrect?","o":["Nonfiction information is copyrightable.","The author's intention when making a literary work is irrelevant to its copyrightability.","Short phrases are generally not protected by copyright.","None of the options"],"a":[0],"m":"ipr","c":2,"n":325,"f":1,"e":"Thông tin phi hư cấu (sự kiện, dữ kiện) không được bảo hộ bản quyền; chỉ cách diễn đạt mới được. Nên phát biểu {A} là sai.","vi":{"q":"Điều nào sau đây không đúng?","o":["Thông tin phi hư cấu (nonfiction) có thể được bảo hộ bản quyền.","Ý định của tác giả khi tạo ra tác phẩm văn học không liên quan đến khả năng được bảo hộ bản quyền.","Các cụm từ ngắn nói chung không được bảo hộ bản quyền.","Không lựa chọn nào"]}},
{"id":"ipr-326","q":"Who is the designer?","o":["The draughts person who made the drawing","Anyone who contributes the ideas of the drawing","Person who provides the concept for designing","All are correct"],"a":[3],"m":"ipr","c":6,"n":326,"f":1,"e":"Theo đáp án của đề, mọi người đóng góp vào thiết kế đều có thể là designer; xem cảnh báo bên dưới.","vi":{"q":"Ai là nhà thiết kế (designer)?","o":["Người vẽ kỹ thuật đã thực hiện bản vẽ","Bất kỳ ai đóng góp ý tưởng cho bản vẽ","Người cung cấp ý tưởng chủ đạo (concept) cho việc thiết kế","Tất cả đều đúng"]},"k":"Theo luật Anh, nhà thiết kế là người tạo ra thiết kế (người thể hiện), còn người chỉ đóng góp ý tưởng không phải tác giả/nhà thiết kế (xem #88, #167). Đề chọn {D}."},
{"id":"ipr-327","q":"According to the UK's law, copyright for a novel, which is written by a novelist, in 2011, lasts for _","o":["The novelist's life plus 70 years","The novelist's life plus 50 years","20 years","The novelist's life"],"a":[0],"m":"ipr","c":2,"n":327,"e":"Theo luật Anh, bản quyền tiểu thuyết viết năm 2011 kéo dài suốt đời tác giả cộng thêm 70 năm.","vi":{"q":"Theo luật Anh, bản quyền đối với một cuốn tiểu thuyết do một tiểu thuyết gia viết năm 2011 kéo dài _","o":["Suốt đời tiểu thuyết gia cộng thêm 70 năm","Suốt đời tiểu thuyết gia cộng thêm 50 năm","20 năm","Suốt đời tiểu thuyết gia"]}},
{"id":"ipr-328","q":"What does this mean for Ander if he is an author of a novel based on the \"National treatment principle in the Berne Convention on Literary and Artistic Works 1886","o":["He is required to register his works with the Berne Convention office.","He is exempt from any copyright regulations in the Berne Convention's country members","His novel will be in the public domain.","Ander is given the same rights and privileges (copyright) to his novel as domestic authors in any country that ratified Berne Convention."],"a":[3],"m":"ipr","c":2,"n":328,"e":"Theo nguyên tắc đối xử quốc gia, Ander được hưởng các quyền như tác giả trong nước ở mọi nước thành viên Berne.","vi":{"q":"Điều này có ý nghĩa gì với Ander, một tác giả tiểu thuyết, dựa trên \"nguyên tắc đối xử quốc gia\" trong Công ước Berne về bảo hộ tác phẩm văn học và nghệ thuật 1886?","o":["Ông phải đăng ký tác phẩm của mình tại văn phòng của Công ước Berne.","Ông được miễn mọi quy định về bản quyền ở các nước thành viên Công ước Berne","Tiểu thuyết của ông sẽ thuộc phạm vi công cộng.","Ander được hưởng các quyền và đặc quyền (bản quyền) đối với tiểu thuyết của mình giống như các tác giả trong nước ở bất kỳ quốc gia nào đã phê chuẩn Công ước Berne."]}},
{"id":"ipr-329","q":"What is a \"public performance\" in terms of copyright?","o":["Any performance of a work in a public space","A private showing of a work","A limited distribution of a work","A performance by a professional artist only"],"a":[0],"m":"ipr","c":3,"n":329,"e":"Biểu diễn trước công chúng là bất kỳ buổi biểu diễn tác phẩm ở không gian công cộng.","vi":{"q":"\"Biểu diễn trước công chúng\" (public performance) theo nghĩa bản quyền là gì?","o":["Bất kỳ buổi biểu diễn một tác phẩm nào ở không gian công cộng","Một buổi trình chiếu riêng tư một tác phẩm","Việc phân phối hạn chế một tác phẩm","Chỉ buổi biểu diễn của nghệ sĩ chuyên nghiệp"]}},
{"id":"ipr-330","q":"What must a work be to qualify for artistic copyright?","o":["Original, not copied from elsewhere","Registered with an official body","Of high artistic merit","Published in an art magazine"],"a":[0],"m":"ipr","c":2,"n":330,"e":"Tác phẩm nghệ thuật chỉ cần nguyên gốc, không sao chép; không cần đăng ký, giá trị nghệ thuật cao hay được công bố.","vi":{"q":"Một tác phẩm phải như thế nào để đủ điều kiện được bảo hộ bản quyền tác phẩm nghệ thuật?","o":["Nguyên gốc, không sao chép từ nơi khác","Được đăng ký với một cơ quan chính thức","Có giá trị nghệ thuật cao","Được đăng trên tạp chí nghệ thuật"]}},
{"id":"ipr-331","q":"If a work was created by multiple authors, when does the 70-year copyright duration begin?","o":["From the date the work is completed","From the death of the last surviving author","From the date of the first publication","From the date the work is registered"],"a":[1],"m":"ipr","c":2,"n":331,"e":"Với tác phẩm nhiều tác giả, thời hạn 70 năm tính từ khi tác giả còn sống cuối cùng qua đời.","vi":{"q":"Nếu một tác phẩm do nhiều tác giả tạo ra, thời hạn bản quyền 70 năm bắt đầu tính khi nào?","o":["Từ ngày tác phẩm hoàn thành","Từ khi tác giả cuối cùng còn sống qua đời","Từ ngày xuất bản đầu tiên","Từ ngày tác phẩm được đăng ký"]}},
{"id":"ipr-332","q":"How would you copyright a poem that you have created and sent to a poem contest?","o":["It is protected by copyright once you have written it on paper or any other medium.","You need to receive a Copyright certificate from the Copyright Office in your country.","It is never protected by copyright, because you have let people at the contest read it.","You need to register it with the Copyright Office in your country and in foreign countries."],"a":[0],"m":"ipr","c":2,"n":332,"e":"Bài thơ được bảo hộ bản quyền ngay khi bạn viết ra trên giấy hoặc phương tiện khác, không cần đăng ký.","vi":{"q":"Làm thế nào để bạn có bản quyền cho bài thơ bạn sáng tác và gửi đến một cuộc thi thơ?","o":["Nó được bảo hộ bản quyền ngay khi bạn viết ra trên giấy hoặc bất kỳ phương tiện nào khác.","Bạn cần nhận giấy chứng nhận bản quyền từ Cơ quan Bản quyền của nước bạn.","Nó không bao giờ được bảo hộ bản quyền, vì bạn đã để người tham dự cuộc thi đọc nó.","Bạn cần đăng ký nó với Cơ quan Bản quyền ở nước bạn và ở các nước ngoài."]}},
{"id":"ipr-333","q":"Which of the following is considered a \"literary work\" under copyright law, relevant to engineering?","o":["Sound recordings","Engineering reports","Films","Broadcasts"],"a":[1],"m":"ipr","c":2,"n":333,"e":"Báo cáo kỹ thuật là tác phẩm văn học; bản ghi âm, phim và chương trình phát sóng là các loại tác phẩm khác.","vi":{"q":"Điều nào sau đây được coi là \"tác phẩm văn học\" theo luật bản quyền, liên quan đến kỹ thuật?","o":["Bản ghi âm","Báo cáo kỹ thuật","Phim","Chương trình phát sóng"]}},
{"id":"ipr-334","q":"How does copyright apply to computer programs?","o":["Only applies to commercial software","They are protected as literary works under copyright law","They are not covered by copyright","Only the source code is protected"],"a":[1],"m":"ipr","c":2,"n":334,"e":"Chương trình máy tính được bảo hộ như tác phẩm văn học theo luật bản quyền.","vi":{"q":"Bản quyền áp dụng cho chương trình máy tính như thế nào?","o":["Chỉ áp dụng cho phần mềm thương mại","Chúng được bảo hộ như tác phẩm văn học theo luật bản quyền","Chúng không thuộc phạm vi bản quyền","Chỉ mã nguồn được bảo hộ"]}},
{"id":"ipr-335","q":"Which of the following is NOT an example of literary work?","o":["A character in a novel","A novel written by Smith","A technical report or specification","None of the options"],"a":[0],"m":"ipr","c":2,"n":335,"f":1,"e":"Một nhân vật trong tiểu thuyết (ý tưởng) không phải tác phẩm văn học; còn tiểu thuyết và báo cáo kỹ thuật thì có.","vi":{"q":"Điều nào sau đây KHÔNG phải là ví dụ về tác phẩm văn học?","o":["Một nhân vật trong tiểu thuyết","Một cuốn tiểu thuyết do Smith viết","Một báo cáo hoặc bản mô tả kỹ thuật","Không lựa chọn nào"]}},
{"id":"ipr-336","q":"What does copyright protection in sound recordings cover?","o":["Only recordings of music","Any type of sound recording, including spoken words and noises","Only digital recordings","Only films and broadcasts"],"a":[1],"m":"ipr","c":2,"n":336,"e":"Bản ghi âm được bảo hộ bản quyền dù là nhạc, lời nói hay tiếng ồn.","vi":{"q":"Bảo hộ bản quyền đối với bản ghi âm bao gồm những gì?","o":["Chỉ các bản ghi âm nhạc","Bất kỳ loại bản ghi âm nào, kể cả lời nói và tiếng ồn","Chỉ các bản ghi kỹ thuật số","Chỉ phim và chương trình phát sóng"]}},
{"id":"ipr-337","q":"Which of the following is a moral right in Vietnamese IP law?","o":["Public communication right","Right to attribution","Right to lease","Right to make copies"],"a":[1],"m":"ipr","c":2,"n":337,"e":"Quyền được nêu tên (attribution) là quyền nhân thân; truyền đạt, cho thuê, sao chép là quyền tài sản.","vi":{"q":"Điều nào sau đây là quyền nhân thân theo luật sở hữu trí tuệ Việt Nam?","o":["Quyền truyền đạt tới công chúng","Quyền được nêu tên (attribution)","Quyền cho thuê","Quyền sao chép"]}},
{"id":"ipr-338","q":"What does the legal term \"overlap in Intellectual Property Right (IPR) protection\" mean?","o":["It indicates the simultaneous use of multiple IPR protection mechanisms to protect a single IP.","It refers to the legal conflicts arising when one type of IPR protection are applied to more than one IP","It implies the expiration of IPR protection, allowing others to use the protected IP freely.","It is about the collaboration among creators/owners to collectively protect their IPRs."],"a":[0],"m":"ipr","c":1,"n":338,"e":"«Overlap» (chồng lấn) là việc dùng đồng thời nhiều cơ chế bảo hộ sở hữu trí tuệ cho một tài sản trí tuệ.","vi":{"q":"Thuật ngữ pháp lý \"chồng lấn bảo hộ quyền sở hữu trí tuệ\" (overlap in IPR protection) có nghĩa là gì?","o":["Chỉ việc sử dụng đồng thời nhiều cơ chế bảo hộ quyền sở hữu trí tuệ để bảo hộ một tài sản trí tuệ duy nhất.","Chỉ các xung đột pháp lý phát sinh khi một loại bảo hộ quyền sở hữu trí tuệ được áp dụng cho nhiều hơn một tài sản trí tuệ","Hàm ý sự hết hiệu lực của bảo hộ quyền sở hữu trí tuệ, cho phép người khác tự do sử dụng tài sản trí tuệ được bảo hộ.","Nói về sự hợp tác giữa các nhà sáng tạo/chủ sở hữu để cùng bảo vệ quyền sở hữu trí tuệ của họ."]}},
{"id":"ipr-339","q":"Get-up includes:","o":["The color of packaging and the type of lettering used on a label","A slogan used for broadcast or printed advertising","Visual impression of business premises, such as the style of fascia board and the color of shop fittings","All are correct"],"a":[3],"m":"ipr","c":5,"n":339,"f":1,"e":"Get-up gồm màu bao bì, kiểu chữ, khẩu hiệu, ấn tượng thị giác của cơ sở kinh doanh; chọn «tất cả».","vi":{"q":"Get-up (diện mạo thương mại) bao gồm:","o":["Màu sắc bao bì và kiểu chữ dùng trên nhãn","Khẩu hiệu dùng trong quảng cáo phát sóng hoặc in ấn","Ấn tượng thị giác của cơ sở kinh doanh, như kiểu bảng hiệu cửa hàng và màu sắc đồ đạc trong cửa hàng","Tất cả đều đúng"]}},
{"id":"ipr-340","q":"Who can handle the trade mark registration?","o":["A professional trade mark agent","Anyone","The judge in the court","The All"],"a":[0],"m":"ipr","c":4,"n":340,"e":"Theo đáp án của đề, đại diện nhãn hiệu chuyên nghiệp xử lý việc đăng ký nhãn hiệu.","vi":{"q":"Ai có thể xử lý việc đăng ký nhãn hiệu?","o":["Một đại diện nhãn hiệu chuyên nghiệp","Bất kỳ ai","Thẩm phán tại tòa án","Tất cả"]}},
{"id":"ipr-341","q":"What is an invented word that used as a trade mark?","o":["A word which has been made up specially for use as a trade and has no meaning in the English language","A word which is commonly used in specific context","Any word with meaning is invented word","A word which is used out of it context"],"a":[0],"m":"ipr","c":4,"n":341,"e":"Từ tự đặt ra là từ được tạo ra riêng để dùng làm nhãn hiệu và không có nghĩa trong tiếng Anh.","vi":{"q":"Từ tự đặt ra (invented word) được dùng làm nhãn hiệu là gì?","o":["Một từ được tạo ra riêng để dùng trong thương mại và không có nghĩa trong tiếng Anh","Một từ thường được dùng trong một ngữ cảnh cụ thể","Bất kỳ từ nào có nghĩa đều là từ tự đặt ra","Một từ được dùng ngoài ngữ cảnh của nó"]}},
{"id":"ipr-342","q":"How did the House of Lords rule in the case of British Leyland vs. Armstrong Patents Company Limited regarding car exhaust systems?","o":["They ruled that copyright could not be used to prevent car repairs at a reasonable price","They upheld British Leyland's copyright claim","They ruled in favor of Armstrong's copyright","They decided that the exhaust system design was public domain"],"a":[0],"m":"ipr","c":6,"n":342,"e":"Trong vụ British Leyland kiện Armstrong, Thượng viện phán quyết không thể dùng bản quyền để ngăn việc sửa chữa xe với giá hợp lý; vì thế mới có quyền kiểu dáng.","vi":{"q":"Thượng viện Anh (House of Lords) đã phán quyết như thế nào trong vụ British Leyland kiện Armstrong Patents Company Limited về hệ thống ống xả ô tô?","o":["Họ phán quyết rằng không thể dùng bản quyền để ngăn việc sửa chữa ô tô với giá hợp lý","Họ giữ nguyên yêu cầu về bản quyền của British Leyland","Họ phán quyết có lợi cho bản quyền của Armstrong","Họ quyết định rằng thiết kế hệ thống ống xả thuộc phạm vi công cộng"]}},
{"id":"ipr-343","q":"Can a method of construction be protected by design right?","o":["Yes, always","No, methods of construction are excluded from design right protection","Only if it is innovative","Only if it is registered"],"a":[1],"m":"ipr","c":6,"n":343,"e":"Phương pháp chế tạo bị loại trừ khỏi bảo hộ quyền kiểu dáng.","vi":{"q":"Phương pháp chế tạo (method of construction) có thể được bảo hộ bằng quyền kiểu dáng không?","o":["Có, luôn luôn","Không, phương pháp chế tạo bị loại trừ khỏi sự bảo hộ của quyền kiểu dáng","Chỉ nếu nó có tính đổi mới","Chỉ nếu nó đã được đăng ký"]}},
{"id":"ipr-344","q":"The assignment and licensing agreement shall be registered by the competent authority as required by law. Is this statement correct?","o":["No. Only the licensing is needed","Yes. They can be registered upon the requirement of the law","No. Only the assignment agreement is needed","No. They can never be registered"],"a":[1],"m":"ipr","c":1,"n":344,"e":"Hợp đồng chuyển nhượng và cấp phép có thể đăng ký khi luật yêu cầu.","vi":{"q":"Hợp đồng chuyển nhượng và cấp phép phải được cơ quan có thẩm quyền đăng ký theo yêu cầu của luật. Phát biểu này có đúng không?","o":["Không. Chỉ cần đăng ký hợp đồng cấp phép","Có. Chúng có thể được đăng ký khi luật yêu cầu","Không. Chỉ cần đăng ký hợp đồng chuyển nhượng","Không. Chúng không bao giờ có thể được đăng ký"]}},
{"id":"ipr-345","q":"What is an IPRs (Intellectual Property Rights) Know-how Contract?","o":["A legal agreement in which the owner of an intellectual property (IP) share specific knowledge, techniques, processes, or expertise to another party (other parties) for a particular purpose, typically in business, manufacturing, or technology.","A legal contract in which the owner of an intellectual property (IP) grants permission to another party (other parties) to use that IP under defined conditions.","A legal contract on transferring of ownership of IP from the assignor to the assignee.","Both of b&c"],"a":[0],"m":"ipr","c":1,"n":345,"f":1,"e":"Hợp đồng bí quyết (know-how) là thỏa thuận trong đó chủ sở hữu chia sẻ kiến thức, kỹ thuật, quy trình hoặc chuyên môn cụ thể cho bên khác.","vi":{"q":"Hợp đồng bí quyết (know-how) về quyền sở hữu trí tuệ là gì?","o":["Một thỏa thuận pháp lý trong đó chủ sở hữu một tài sản trí tuệ (IP) chia sẻ kiến thức, kỹ thuật, quy trình hoặc chuyên môn cụ thể cho một bên khác (các bên khác) vì một mục đích nhất định, thường trong kinh doanh, sản xuất hoặc công nghệ.","Một hợp đồng pháp lý trong đó chủ sở hữu một tài sản trí tuệ (IP) cho phép một bên khác (các bên khác) sử dụng IP đó theo các điều kiện đã định.","Một hợp đồng pháp lý về việc chuyển giao quyền sở hữu IP từ bên chuyển nhượng sang bên nhận chuyển nhượng.","Cả b và c"]}},
{"id":"ipr-346","q":"According to UK laws, which is not the types of IP case that the Patent Court (belonging to the Chancery Division of the High Court) hears?","o":["Cases relating to Registered designs and Design rights.","Cases relating to the theft of artworks.","Cases relating to Patent.","Cases relating to Trade marks, Passing-off and Copyright."],"a":[1],"m":"ipr","c":1,"n":346,"e":"Tòa Sáng chế không xét các vụ trộm cắp tác phẩm nghệ thuật; nó xét sáng chế, kiểu dáng, nhãn hiệu, passing off và bản quyền.","vi":{"q":"Theo luật Anh, loại vụ việc sở hữu trí tuệ nào KHÔNG thuộc thẩm quyền xét xử của Tòa Sáng chế (Patent Court) (thuộc Chancery Division của High Court)?","o":["Các vụ việc liên quan đến kiểu dáng đã đăng ký và quyền kiểu dáng.","Các vụ việc liên quan đến trộm cắp tác phẩm nghệ thuật.","Các vụ việc liên quan đến sáng chế.","Các vụ việc liên quan đến nhãn hiệu, passing-off và bản quyền."]}},
{"id":"ipr-347","q":"Who must prove primary infringement?","o":["The right owner","The licensee","The infringer","Police"],"a":[0],"m":"ipr","c":3,"n":347,"e":"Chủ sở hữu quyền (nguyên đơn) phải chứng minh vi phạm trực tiếp.","vi":{"q":"Ai phải chứng minh vi phạm trực tiếp (primary infringement)?","o":["Chủ sở hữu quyền","Bên được cấp phép","Người vi phạm","Cảnh sát"]}},
{"id":"ipr-348","q":"Agreement on Trade-Related Aspects of Intellectual Property Rights (TRIPS) is an international agreement that... for all World Trade Organization members.","o":["Sets maximum standards for protection of intellectual property","Sets minimum standards for intellectual property protection","Regulates average standards for protection of intellectual property","Sets basic limitations for intellectual property protection"],"a":[1],"m":"ipr","c":1,"n":348,"e":"TRIPS đặt ra các tiêu chuẩn tối thiểu về bảo hộ sở hữu trí tuệ cho mọi thành viên WTO.","vi":{"q":"Hiệp định về các khía cạnh liên quan đến thương mại của quyền sở hữu trí tuệ (TRIPS) là một hiệp định quốc tế mà.... đối với tất cả các thành viên Tổ chức Thương mại Thế giới (WTO).","o":["Đặt ra các tiêu chuẩn tối đa về bảo hộ sở hữu trí tuệ","Đặt ra các tiêu chuẩn tối thiểu về bảo hộ sở hữu trí tuệ","Quy định các tiêu chuẩn trung bình về bảo hộ sở hữu trí tuệ","Đặt ra các giới hạn cơ bản đối với bảo hộ sở hữu trí tuệ"]}},
{"id":"ipr-349","q":"Which convention primarily deals with the protection of industrial property such as patents and trademarks?","o":["Berne Convention","Paris Convention","Rome Convention","Geneva Convention"],"a":[1],"m":"ipr","c":1,"n":349,"e":"Công ước Paris điều chỉnh bảo hộ sở hữu công nghiệp như sáng chế, nhãn hiệu; Berne là về bản quyền.","vi":{"q":"Công ước nào chủ yếu điều chỉnh việc bảo hộ sở hữu công nghiệp như sáng chế và nhãn hiệu?","o":["Công ước Berne","Công ước Paris","Công ước Rome","Công ước Geneva"]}},
{"id":"ipr-350","q":"What is the primary Law in the area of intellectual property in Vietnam?","o":["Vietnam Copyright Law","Vietnam Trademark Law","Vietnam Intellectual Property Law 2005 (amended and supplemented in 2009, 2019 and 2022).","Vietnam Industrial Design Law"],"a":[2],"m":"ipr","c":1,"n":350,"e":"Luật chính về sở hữu trí tuệ ở Việt Nam là Luật Sở hữu trí tuệ 2005 (sửa đổi, bổ sung 2009, 2019, 2022).","vi":{"q":"Luật chính về sở hữu trí tuệ ở Việt Nam là gì?","o":["Luật Bản quyền Việt Nam","Luật Nhãn hiệu Việt Nam","Luật Sở hữu trí tuệ Việt Nam 2005 (sửa đổi, bổ sung năm 2009, 2019 và 2022).","Luật Kiểu dáng công nghiệp Việt Nam"]}},
{"id":"ipr-351","q":"___ indicate that the user of the mark is a member of a trade association which owns the mark.","o":["Certification trade marks","Generic marks","Unregistered trade marks","Collective trade marks"],"a":[3],"m":"ipr","c":4,"n":351,"e":"Nhãn hiệu tập thể cho biết người dùng là thành viên của hiệp hội sở hữu nhãn hiệu.","vi":{"q":"___ cho biết người sử dụng nhãn hiệu là thành viên của một hiệp hội thương mại sở hữu nhãn hiệu đó.","o":["Nhãn hiệu chứng nhận","Nhãn hiệu chung (generic)","Nhãn hiệu chưa đăng ký","Nhãn hiệu tập thể"]}},
{"id":"ipr-352","q":"Get-up includes___","o":["the type of lettering used on a label","the colour of packaging","internal parts of a product that can not be seen in normal use","visual impression of business premises"],"a":[0,1,3],"m":"ipr","c":5,"n":352,"e":"Get-up gồm kiểu chữ trên nhãn, màu bao bì và ấn tượng thị giác của cơ sở kinh doanh; các bộ phận bên trong không nhìn thấy khi sử dụng bình thường thì không.","vi":{"q":"Get-up bao gồm___","o":["kiểu chữ dùng trên nhãn","màu sắc bao bì","các bộ phận bên trong của sản phẩm mà không nhìn thấy được khi sử dụng bình thường","ấn tượng thị giác của cơ sở kinh doanh"]}},
{"id":"ipr-353","q":"Which statement best describe the owner of a registered design?","o":["A person who actually creates a registered design","The company placing the commission","The manager of the technical team of a company","A person who contributes the idea"],"a":[1],"m":"ipr","c":6,"n":353,"e":"Theo quy tắc cũ của luật Anh, bên đặt hàng (commission) là chủ sở hữu kiểu dáng; xem cảnh báo bên dưới.","vi":{"q":"Phát biểu nào mô tả đúng nhất chủ sở hữu của kiểu dáng đã đăng ký?","o":["Người thực sự tạo ra kiểu dáng đã đăng ký","Công ty đặt hàng (commission)","Trưởng nhóm kỹ thuật của một công ty","Người đóng góp ý tưởng"]},"k":"Đây là quy tắc cũ của luật Anh (bên đặt hàng sở hữu kiểu dáng); luật hiện hành (từ 10/2014) đã bỏ và nhà thiết kế là chủ sở hữu — xem câu #29."},
{"id":"ipr-354","q":"What is the advantage of the community right?","o":["Community right has the same effect in all EU countries, and that for the registration system there need be only one application.","The community right does not have any advantage","Community right has the different effect in all EU countries, so in some countries it can have longer protecting duration","Community right has the same effect in all EU countries but in some special circumstances it can have longer protecting duration"],"a":[0],"m":"ipr","c":6,"n":354,"e":"Ưu điểm của quyền cộng đồng là có hiệu lực như nhau ở mọi nước EU và chỉ cần một đơn đăng ký.","vi":{"q":"Lợi thế của quyền cộng đồng (community right) là gì?","o":["Quyền cộng đồng có hiệu lực như nhau ở tất cả các nước EU, và hệ thống đăng ký chỉ cần một đơn duy nhất.","Quyền cộng đồng không có lợi thế nào","Quyền cộng đồng có hiệu lực khác nhau ở các nước EU nên ở một số nước có thể có thời hạn bảo hộ dài hơn","Quyền cộng đồng có hiệu lực như nhau ở tất cả các nước EU nhưng trong một số trường hợp đặc biệt có thể có thời hạn bảo hộ dài hơn"]}},
{"id":"ipr-355","q":"The UK government department has copied a design and authorised Company H to manufacture the design for use in the national defence of the UK. Which of the following is RIGHT?","o":["If the Department uses of the design in the way as described above, it has to notify and inform of the extent of use to the owner of the design.","The owner of the design can sue the Department for an infringement of Design right","The Department cannot copy the design for any purposes.","The Department cannot authorise the company H to manufacture the design, and this is an infringement."],"a":[0],"m":"ipr","c":6,"n":355,"e":"Nếu cơ quan chính phủ dùng thiết kế cho quốc phòng (Crown use), phải thông báo và cho chủ sở hữu biết phạm vi sử dụng.","vi":{"q":"Một cơ quan chính phủ Anh đã sao chép một thiết kế và ủy quyền cho Công ty H sản xuất thiết kế đó để dùng cho quốc phòng của Anh. Phát biểu nào sau đây ĐÚNG?","o":["Nếu cơ quan này sử dụng thiết kế theo cách nêu trên thì phải thông báo và cho chủ sở hữu thiết kế biết phạm vi sử dụng.","Chủ sở hữu thiết kế có thể kiện cơ quan này về hành vi xâm phạm quyền kiểu dáng","Cơ quan này không được sao chép thiết kế cho bất kỳ mục đích nào.","Cơ quan này không được ủy quyền cho Công ty H sản xuất thiết kế, và đó là hành vi xâm phạm."]}},
{"id":"ipr-356","q":"What is individual character informed?","o":["The design must be identical to the other previous designs or available products","The design must be original","The design must produce on an informed user an overall impression which differs from the overall impression produced by the earlier design","All are correct"],"a":[2],"m":"ipr","c":6,"n":356,"f":1,"e":"Tính độc đáo riêng nghĩa là thiết kế tạo ấn tượng tổng thể khác với thiết kế trước đối với người dùng am hiểu.","vi":{"q":"Tính độc đáo riêng (individual character) được hiểu thế nào?","o":["Thiết kế phải giống hệt các thiết kế trước đó hoặc sản phẩm có sẵn","Thiết kế phải nguyên gốc","Thiết kế phải tạo cho người dùng am hiểu (informed user) một ấn tượng tổng thể khác với ấn tượng tổng thể do thiết kế trước đó tạo ra","Tất cả đều đúng"]}},
{"id":"ipr-357","q":"Which of the following forms a secondary infringement of copyright?","o":["Smith purchases copies abroad and imports them into the UK.","Smith adapts a copyright work of Peter.","Smith copies a substantial part of Peter's non-technical book.","Smith photocopies a copyrighted book of Peter."],"a":[0],"m":"ipr","c":3,"n":357,"e":"Mua bản sao ở nước ngoài rồi nhập vào Anh là vi phạm thứ cấp (nhập khẩu); các hành vi còn lại là vi phạm trực tiếp.","vi":{"q":"Hành vi nào sau đây là vi phạm bản quyền thứ cấp (secondary infringement)?","o":["Smith mua các bản sao ở nước ngoài và nhập khẩu vào Anh.","Smith chuyển thể một tác phẩm có bản quyền của Peter.","Smith sao chép một phần đáng kể cuốn sách phi kỹ thuật của Peter.","Smith photocopy một cuốn sách có bản quyền của Peter."]}},
{"id":"ipr-358","q":"Which of the following is not excluded from a design registration?","o":["a mass-produced product with novelty and individual character","a feature of a product which is dictated by its function","internal features which are not seen in normal use","a feature which allows a product to fit to another product"],"a":[0],"m":"ipr","c":6,"n":358,"e":"Sản phẩm sản xuất hàng loạt có tính mới và tính độc đáo riêng đăng ký được; đặc điểm do chức năng quyết định, đặc điểm bên trong và đặc điểm để khớp với sản phẩm khác bị loại.","vi":{"q":"Điều nào sau đây không bị loại trừ khỏi đăng ký kiểu dáng?","o":["một sản phẩm sản xuất hàng loạt có tính mới và tính độc đáo riêng","một đặc điểm của sản phẩm do chức năng quyết định","các đặc điểm bên trong không nhìn thấy được khi sử dụng bình thường","một đặc điểm cho phép sản phẩm khớp với một sản phẩm khác"]}},
{"id":"ipr-359","q":"A new software code can be protected by:","o":["Trademark and Design Right","Copyright and Patent","Patent and Trade Secret","Copyright and Trade Secret"],"a":[3],"m":"ipr","c":1,"n":359,"e":"Mã phần mềm mới được bảo hộ bản quyền và bí mật thương mại.","vi":{"q":"Mã phần mềm mới có thể được bảo hộ bởi:","o":["Nhãn hiệu và Quyền kiểu dáng","Bản quyền và Sáng chế","Sáng chế và Bí mật thương mại","Bản quyền và Bí mật thương mại"]}},
{"id":"ipr-360","q":"How does the duration of copyright in a cable programme compare to that of a sound recording?","o":["Both last for 50 years from the date of first transmission or release","Copyright in cable programmes lasts longer","Sound recordings have indefinite copyright protection","Cable programmes have shorter copyright duration"],"a":[0],"m":"ipr","c":2,"n":360,"e":"Bản quyền chương trình truyền hình cáp và bản ghi âm đều kéo dài 50 năm kể từ truyền phát hoặc phát hành đầu tiên.","vi":{"q":"Thời hạn bản quyền của chương trình truyền hình cáp so với bản ghi âm như thế nào?","o":["Cả hai đều kéo dài 50 năm kể từ ngày truyền phát hoặc phát hành đầu tiên","Bản quyền chương trình truyền hình cáp kéo dài hơn","Bản ghi âm có bảo hộ bản quyền vô thời hạn","Chương trình truyền hình cáp có thời hạn bản quyền ngắn hơn"]}},
{"id":"ipr-361","q":"Which of the following is not primary infringement of copyright?","o":["Purchasing copies abroad and importing them into the UK","Adapt a copyright work","Making a short-term copy in a different medium to the original work","Reutilising a substantial part of a computer-stored database"],"a":[0],"m":"ipr","c":3,"n":361,"e":"Mua bản sao ở nước ngoài rồi nhập vào Anh là vi phạm thứ cấp; chuyển thể, sao chép tạm, khai thác lại cơ sở dữ liệu là vi phạm trực tiếp.","vi":{"q":"Điều nào sau đây không phải là vi phạm bản quyền trực tiếp (primary infringement)?","o":["Mua các bản sao ở nước ngoài và nhập khẩu vào Anh","Chuyển thể một tác phẩm có bản quyền","Tạo một bản sao ngắn hạn trên một phương tiện khác với tác phẩm gốc","Khai thác lại một phần đáng kể của cơ sở dữ liệu lưu trên máy tính"]}},
{"id":"ipr-362","q":"Is IPR assignment a contract?","o":["Yes, it is a contract","No, it is a kind of order with military nature","No, it is a license","No, assignment is a kind of home exercise for student"],"a":[0],"m":"ipr","c":1,"n":362,"e":"Chuyển nhượng quyền sở hữu trí tuệ là một hợp đồng.","vi":{"q":"Việc chuyển nhượng quyền sở hữu trí tuệ có phải là một hợp đồng không?","o":["Có, đó là một hợp đồng","Không, đó là một loại mệnh lệnh mang tính quân sự","Không, đó là một giấy phép","Không, chuyển nhượng là một loại bài tập về nhà dành cho sinh viên"]}},
{"id":"ipr-363","q":"Some types of copying or of trading in copyright material are criminal offences. What are they?","o":["Making the article for private or domestic use","Selling, hiring, exhibiting or distributing the article in the course of a business","Designing a famous quote of someone for decoration","Copy some pages of a book for researching"],"a":[1],"m":"ipr","c":3,"n":363,"e":"Bán, cho thuê, trưng bày hoặc phân phối bản sao trong hoạt động kinh doanh là tội hình sự; sao chép cá nhân hay nghiên cứu thì không.","vi":{"q":"Một số hình thức sao chép hoặc buôn bán tài liệu có bản quyền là tội hình sự. Đó là những hình thức nào?","o":["Làm ra sản phẩm để dùng cho cá nhân hoặc gia đình","Bán, cho thuê, trưng bày hoặc phân phối sản phẩm trong hoạt động kinh doanh","Thiết kế một câu trích dẫn nổi tiếng của ai đó để trang trí","Sao chép vài trang của một cuốn sách để nghiên cứu"]}},
{"id":"ipr-364","q":"What are the main objectives of WIPO?","o":["To promote the protection of intellectual property worldwide","To ensure administrative cooperation among the intellectual property Unions established by the treaties that WIPO administers","A and B is correct","A and B is not correct"],"a":[2],"m":"ipr","c":1,"n":364,"f":1,"e":"Mục tiêu chính của WIPO gồm thúc đẩy bảo hộ sở hữu trí tuệ toàn cầu và bảo đảm hợp tác hành chính giữa các Liên minh do WIPO quản lý.","vi":{"q":"Mục tiêu chính của WIPO là gì?","o":["Thúc đẩy bảo hộ sở hữu trí tuệ trên toàn thế giới","Bảo đảm sự hợp tác hành chính giữa các Liên minh sở hữu trí tuệ được thành lập theo các hiệp ước do WIPO quản lý","A và B đều đúng","A và B đều sai"]}},
{"id":"ipr-365","q":"Under the 'must match' exception, what can be freely made and sold?","o":["Any patented product","Replacement parts that must match other parts of a product","The original product only","Decorative items"],"a":[1],"m":"ipr","c":6,"n":365,"e":"Theo ngoại lệ must-match, các bộ phận thay thế phải khớp với bộ phận khác của sản phẩm được tự do sản xuất và bán.","vi":{"q":"Theo ngoại lệ 'must match' (phải trùng khớp), cái gì có thể được tự do sản xuất và bán?","o":["Bất kỳ sản phẩm nào được cấp bằng sáng chế","Các bộ phận thay thế phải khớp với các bộ phận khác của sản phẩm","Chỉ sản phẩm gốc","Đồ trang trí"]}},
{"id":"ipr-366","q":"What is the significance of the 50-year duration for copyright in broadcasts and cable programmes?","o":["It defines the period during which the copyright holder has exclusive rights over the content","It limits the time a programme can be aired","It determines when a programme can be remade","It ensures that the content can be freely shared after 50 years"],"a":[0],"m":"ipr","c":2,"n":366,"e":"Thời hạn 50 năm xác định khoảng thời gian chủ sở hữu có quyền độc quyền đối với nội dung chương trình phát sóng, truyền hình cáp.","vi":{"q":"Ý nghĩa của thời hạn 50 năm đối với bản quyền chương trình phát sóng và chương trình truyền hình cáp là gì?","o":["Nó xác định khoảng thời gian chủ sở hữu bản quyền có quyền độc quyền đối với nội dung","Nó giới hạn thời gian một chương trình được phát sóng","Nó xác định khi nào một chương trình có thể được làm lại","Nó bảo đảm nội dung có thể được chia sẻ tự do sau 50 năm"]}},
{"id":"ipr-367","q":"Why is surface decoration not protected by design right?","o":["Because it is too complex","Because it is not functional","Because it can be protected by registered designs law instead","Because it is too simple"],"a":[1],"m":"ipr","c":6,"n":367,"e":"Trang trí bề mặt không được bảo hộ bằng quyền kiểu dáng vì không mang tính chức năng (quyền này dành cho thiết kế hình dáng, cấu hình).","vi":{"q":"Vì sao trang trí bề mặt không được bảo hộ bằng quyền kiểu dáng (design right)?","o":["Vì nó quá phức tạp","Vì nó không mang tính chức năng","Vì thay vào đó nó có thể được bảo hộ bởi luật kiểu dáng đã đăng ký","Vì nó quá đơn giản"]}},
{"id":"ipr-368","q":"The photographer owns the copyright but the person paying for the photograph to be taken can stop it being used for other purposes, which is referred to as___","o":["Integrity right","Paternity right","False attribution right","Privacy right"],"a":[3],"m":"ipr","c":2,"n":368,"e":"Người trả tiền thuê chụp ảnh có thể ngăn việc dùng ảnh cho mục đích khác, đó là quyền riêng tư (privacy right).","vi":{"q":"Nhiếp ảnh gia sở hữu bản quyền nhưng người trả tiền để thuê chụp ảnh có thể ngăn việc ảnh bị dùng cho mục đích khác, quyền này được gọi là___","o":["Quyền toàn vẹn tác phẩm","Quyền được nhận là tác giả","Quyền chống gán sai tác giả","Quyền riêng tư (privacy right)"]}},
{"id":"ipr-369","q":"What kind of works in graphic design can be protected by intellectual property rights?","o":["Only logos","Only printed materials","Graphic design works that is tangible and creations of minds","Only digital designs"],"a":[2],"m":"ipr","c":1,"n":369,"e":"Tác phẩm thiết kế đồ họa hữu hình và là sáng tạo của trí tuệ có thể được bảo hộ, không chỉ logo, ấn phẩm in hay thiết kế số.","vi":{"q":"Loại tác phẩm thiết kế đồ họa nào có thể được bảo hộ bởi quyền sở hữu trí tuệ?","o":["Chỉ logo","Chỉ ấn phẩm in","Tác phẩm thiết kế đồ họa hữu hình và là sản phẩm sáng tạo của trí tuệ","Chỉ thiết kế kỹ thuật số"]}},
{"id":"ipr-370","q":"What is not the benefit of winning a lawsuit?","o":["Sending a message to others that IP owners is willing to defend the IPR.","Protecting the market for the products of IP owners by stopping infringers from IP infringements","Spending time and money for the litigation.","Other parties need to take an IPR license if they intend to exploit the PR."],"a":[2],"m":"ipr","c":1,"n":370,"e":"Tốn thời gian và tiền bạc cho kiện tụng là chi phí chứ không phải lợi ích của việc thắng kiện.","vi":{"q":"Điều nào KHÔNG phải là lợi ích của việc thắng kiện?","o":["Gửi thông điệp cho người khác biết chủ sở hữu sở hữu trí tuệ sẵn sàng bảo vệ quyền sở hữu trí tuệ.","Bảo vệ thị trường cho sản phẩm của chủ sở hữu sở hữu trí tuệ bằng cách ngăn người vi phạm xâm phạm quyền sở hữu trí tuệ","Tốn thời gian và tiền bạc cho việc kiện tụng.","Các bên khác cần xin giấy phép quyền sở hữu trí tuệ nếu muốn khai thác quyền sở hữu trí tuệ đó."]}},
{"id":"ipr-371","q":"What is required for electronic works to qualify for copyright protection compared to conventional literary works?","o":["The need for legal registration","The work must be published","There must be a spark of creativity","The work must be over a certain length"],"a":[2],"m":"ipr","c":2,"n":371,"e":"Tác phẩm điện tử cần có «tia sáng sáng tạo» (spark of creativity) để được bảo hộ, không cần đăng ký, công bố hay độ dài.","vi":{"q":"Tác phẩm điện tử cần điều gì để đủ điều kiện được bảo hộ bản quyền so với tác phẩm văn học truyền thống?","o":["Cần đăng ký pháp lý","Tác phẩm phải được công bố","Phải có một tia sáng sáng tạo (spark of creativity)","Tác phẩm phải dài hơn một độ dài nhất định"]}},
{"id":"ipr-372","q":"Which is the Statute in the UK that covers a wide range of intellectual property rights, including copyright, design rights, and patents?","o":["Trade Marks Act 1994","Copyright, Designs and Patents Act 1988, amended in the 1990s.","Copyright and Related Rights Regulations 2003","Patents Act 1977"],"a":[1],"m":"ipr","c":2,"n":372,"e":"CDPA 1988 là đạo luật Anh bao trùm bản quyền, quyền kiểu dáng và sáng chế (sửa đổi trong những năm 1990).","vi":{"q":"Đạo luật nào của Anh bao trùm nhiều quyền sở hữu trí tuệ, gồm bản quyền, quyền kiểu dáng và sáng chế?","o":["Đạo luật Nhãn hiệu 1994","Đạo luật Bản quyền, Kiểu dáng và Sáng chế 1988, được sửa đổi vào những năm 1990","Quy định về Bản quyền và các Quyền liên quan 2003","Đạo luật Sáng chế 1977"]}}
]);
